  ('cpiuris2025::0146cdd16fbc6be9bc240c26c7ed1b72', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão entre crimes comuns e crimes eleitorais', '## Conexão entre crimes comuns e crimes eleitorais

A competência para julgar crimes comuns em conexão com crimes eleitorais é da Justiça Eleitoral, independentemente da competência da Justiça Federal ou Estadual. A análise de conexão cabe à Justiça Eleitoral e não à Justiça Federal e/ou Estadual.

### Conceitos
- **Conexão entre crimes comuns e crimes eleitorais**: Relação entre um crime comum e um crime eleitoral, que determina a competência para julgá-los
- **Competência da Justiça Eleitoral**: A capacidade do Tribunal Eleitoral de processar e julgar um caso
- **Análise de conexão**: Exame feito pela Justiça Eleitoral para determinar se há uma relação entre o crime comum e o crime eleitoral

### Referências legais
- Art. 109, § 3º, da Lei nº 9.504/1997
- Súmula 4435 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Conexão entre crimes comuns e crimes eleitorais

### Dicas de prova
- Entenda a competência da Justiça Eleitoral para julgar crimes em conexão com crimes eleitorais
- Análise de conexão é feita pela Justiça Eleitoral, mas não é o único fator que determina a competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 3º, da Lei nº 9.504/1997", "Súmula 4435 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conexão entre crimes comuns e crimes eleitorais"], "confidence": 0.8, "extracted_at": "2026-05-29T00:15:40.411571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=206", "doc_key": "0146cdd16fbc6be9bc240c26c7ed1b72"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '132a88c6a843f53442955450a9b4e4ba6735e87c14deebf250f3e3fe4beaf1a9'),
  ('cpiuris2025::2cd1e60efa257eb8ad4b34e343c6171c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão entre crimes comuns e eleitorais', '## Conexão entre crimes comuns e eleitorais

A conexão entre crime comum de competência da Justiça Federal e crime eleitoral deve haver separação dos processos, já que ambas as competências originam-se diretamente da Constituição Federal. Já a conexão entre crime comum de competência da Justiça Estadual e crime eleitoral não é permitida, pois a competência da Justiça Estadual é residual.

### Conceitos
- **Competência originária**: A competência que se origina diretamente da Constituição Federal
- **Competência residual**: A competência que não se origina diretamente da Constituição Federal, mas sim é derivada de outras fontes legais
- **Conexão entre crimes comuns e eleitorais**: A regra que permite a conexão entre processos de crimes comuns e eleitorais

### Referências legais
- Art. 109 da CF/88
- Art. 121 da CF/88
- Art. 69, inciso V do CPP

### Dicas de prova
- Distinção entre competência originária e residual é fundamental
- A conexão entre crimes comuns e eleitorais deve haver separação dos processos
- Regras constitucionais não podem ser afastadas por normas infraconstitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da CF/88", "Art. 121 da CF/88", "Art. 69, inciso V do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:16:25.857093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=206", "doc_key": "2cd1e60efa257eb8ad4b34e343c6171c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '16f0ce0b4248a7dbd5baff3746429aecafa0bc35dbd769b8b5da187e5907988c'),
  ('cpiuris2025::d45965e08892e420ff234365773491aa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça do Trabalho e da Justiça Federal', '## Competência da Justiça do Trabalho e da Justiça Federal

A competência para processar e julgar mandados de segurança, habeas corpus e habeas data é determinada pela Constituição, com a Justiça do Trabalho competente apenas em casos específicos.

### Conceitos
- **Competência da Justiça do Trabalho**: A competência para processar e julgar ações trabalhistas
- **Justiça Federal**: A competência para processar e julgar infrações penais
- **Mandados de segurança**: Ação que visa proteger direitos individuais
- **Habeas corpus**: Ação que visa garantir liberdade individual
- **Habeas data**: Ação que visa garantir direitos de propriedade

### Referências legais
- Art. 114, IV, da CF/88
- Art. 108, inciso I, alínea a, da CF/88

### Dicas de prova
- Distinção entre competência da Justiça do Trabalho e da Justiça Federal
- Reconhecimento de competência específica para cada tipo de ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 114, IV, da CF/88", "Art. 108, inciso I, alínea a, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:18:08.558850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=207", "doc_key": "d45965e08892e420ff234365773491aa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bf78eace75d294cf2b4a3f49d3992235a61cb99ca592ad5dd5ba30a137e33cc6'),
  ('cpiuris2025::d7cbb1d0dce5e67d2f00f109e1a02f64', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência dos Tribunais Regionais Federais e Juízes Federais', '## Competência dos Tribunais Regionais Federais e Juízes Federais

A competência dos Tribunais Regionais Federais está disposta no art. 108 da CF/88, que determina a competência dos juízes federais em casos específicos, como crimes políticos e crimes praticados contra a União.

### Conceitos
- **Competência**: A capacidade do Tribunal ou Juiz de processar e julgar um caso
- **Tribunal Regional Federal**: Entidade que processa e julga casos específicos, como crimes políticos e crimes praticados contra a União
- **Foro por prerrogativa de função**: Direito concedido a certos funcionários públicos para exercer competência em determinadas áreas
- **Justiça Federal**: Tribunal que processa e julga casos específicos, como crimes políticos e crimes praticados contra a União

### Referências legais
- Art. 108 da CF/88
- Art. 109, inciso IV, primeira parte, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência dos Tribunais Regionais Federais e Juízes Federais
- Diferencie entre crimes políticos e crimes praticados contra a União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 108 da CF/88", "Art. 109, inciso IV, primeira parte, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:18:48.993008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=208", "doc_key": "d7cbb1d0dce5e67d2f00f109e1a02f64"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3e5c85f46502c8fb55ea2f32c993847add86302a6f3c9f1ee499ea930da9e608'),
  ('cpiuris2025::1499368e2792fb92e2941145a6b47e8b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência entre Justiça Eleitoral e Militar', '## Competência entre Justiça Eleitoral e Militar

A competência da Justiça Eleitoral e da Justiça Militar é determinada pela Constituição Federal. A conexão entre crimes eleitorais e militares impede a força atrativa da Justiça Eleitoral sobre os crimes militares, sendo necessária separação dos processos.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar um caso
- **Justiça Eleitoral**: O sistema jurisdicional que processa e julga crimes eleitorais
- **Justiça Militar**: O sistema jurisdicional que processa e julga crimes militares
- **Conexão entre crimes**: A relação entre dois ou mais crimes que ocorrem simultaneamente ou estão relacionados
- **Força atrativa**: O poder de um tribunal ou juiz para determinar a competência de outro tribunal ou juiz
- **Separação dos processos**: A decisão de julgar dois ou mais casos separadamente, em vez de unificá-los em um único processo

### Referências legais
- Art. 78, inciso IV, do CPP
- Art. 69, inciso V, do CPP
- Art. 5º, inciso XXXVIII, alínea d) da CF/88
- Art. 121, caput da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Conexão entre crimes eleitorais e militares

### Dicas de prova
- Entenda a competência da Justiça Eleitoral e da Justiça Militar
- Conheça a regra de conexão entre crimes eleitorais e militares
- Aprenda a aplicar a força atrativa e a separação dos processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 78, inciso IV, do CPP", "Art. 69, inciso V, do CPP", "Art. 5º, inciso XXXVIII, alínea d) da CF/88", "Art. 121, caput da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conexão entre crimes eleitorais e militares"], "confidence": 0.8, "extracted_at": "2026-05-29T00:19:13.852838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=207", "doc_key": "1499368e2792fb92e2941145a6b47e8b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'df55e92168481437f2a4ab4c50f0cc9f97bbc2e2f06c63f220314715b00bfc36'),
  ('cpiuris2025::e30f2f4c0843902fd70dd7731342172d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal', '## Competência da Justiça Federal

A competência da Justiça Federal é necessária para processar e julgar infrações penais que causam danos a bens, serviços ou interesses da União ou de suas entidades autárquicas ou empresas públicas. A competência é atraída pela ofensa direta a esses interesses.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é necessária para processar e julgar infrações penais que causam danos a bens, serviços ou interesses da União ou de suas entidades autárquicas ou empresas públicas.
- **Atração da Competência**: A competência da Justiça Federal é atraída pela ofensa direta a bens, serviços ou interesses da União ou de suas entidades autárquicas ou empresas públicas.

### Referências legais
- Art. 109, § 2º, da CF
- STJ, AgRg no CC n. 193.250/GO

### Jurisprudência
- AgRg no CC n. 193.250/GO
- STJ

### Dicas de prova
- Distinção entre ofensa direta e indireta aos interesses da União
- Importância de demonstrar a atração da competência da Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 2º, da CF", "STJ, AgRg no CC n. 193.250/GO"], "jurisprudence": ["AgRg no CC n. 193.250/GO", "STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T00:20:31.885679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=208", "doc_key": "e30f2f4c0843902fd70dd7731342172d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '19a4b2ffe3542d3aaf51749e485cca3f698e9ec39dd734e6d3c45546f811af11'),
  ('cpiuris2025::b7e3b72e0d10e273a1dca89bfbc62313', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Jurisdicional', '## Competência Jurisdicional

A competência jurisdicional é determinada pela legislação, podendo ser federal ou estadual. As sociedades de economia mista da União não estão arroladas no artigo 109, inciso IV, da CF/88, o que significa que a infração penal praticada em seu detrimento compete à Justiça Comum Estadual e não Federal.

### Conceitos
- **Competência Jurisdicional**: A competência jurisdicional é determinada pela legislação
- **Justiça Federal**: É a competência do juiz federal para processar e julgar infrações penais
- **Justiça Comum Estadual**: É a competência da Justiça estadual para processar e julgar infrações penais
- **Sociedades de Economia Mista**: Não estão arroladas no artigo 109, inciso IV, da CF/88

### Referências legais
- Art. 109, inciso IV, da CF/88
- Súmula n.º 42 do STJ

### Jurisprudência
- STJ. 3ª Seção. CC 182.940-SP
- RE 123456

### Dicas de prova
- Entenda a distinção entre Justiça Federal e Justiça Comum Estadual
- Conheça as exceções à competência federal, como as sociedades de economia mista da União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IV, da CF/88", "Súmula n.º 42 do STJ"], "jurisprudence": ["STJ. 3ª Seção. CC 182.940-SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:21:22.863524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=209", "doc_key": "b7e3b72e0d10e273a1dca89bfbc62313"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6b20bbee69564d66d9f66494d7affced33353dbf934e1192ca86aa3fe53c382c'),
  ('cpiuris2025::4ebefbf94fd2541c362a23b7c150452c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Estadual em crimes e contravenções penais', '## Competência da Justiça Federal e Estadual em crimes e contravenções penais

A competência da Justiça Federal e Estadual é determinada pela conexão entre crime e contravenção penal, bem como pelo foro do detentor de prerrogativa de função. A regra contida no art. 109, inciso IV, da CF/88, deve ser interpretada com atenção ao fato de que a Justiça Federal de 2ª instância tem competência para o processo e julgamento de contravenções penais.

### Conceitos
- **Competência Federal**: A competência da Justiça Federal é determinada pela conexão entre crime e contravenção penal
- **Competência Estadual**: A competência da Justiça Estadual é determinada pela conexão entre crime e contravenção penal
- **Conexão entre crime e contravenção penal**: É obrigatória a separação dos processos, com o crime julgado pela Justiça Federal e a contravenção penal pela Justiça Estadual
- **Foro do detentor de prerrogativa de função**: O foro do juiz federal é competente para processar e julgar contravenções penais

### Referências legais
- Art. 109, inciso IV, da CF/88

### Jurisprudência
- Súmula n.º 38 do Superior Tribunal de Justiça

### Dicas de prova
- Pergunte sobre a competência da Justiça Federal e Estadual em crimes e contravenções penais
- Entenda a conexão entre crime e contravenção penal e sua separação obrigatória nos processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IV, da CF/88"], "jurisprudence": ["Súmula n.º 38 do Superior Tribunal de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-29T00:22:00.718169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=209", "doc_key": "4ebefbf94fd2541c362a23b7c150452c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '142fa5b1240176acf4362309f9182ea8baa0b927f12e013ce0caa0d6e927c2ce'),
  ('cpiuris2025::60ba81e1e3bc7dc961e90375590042ae', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Comum Estadual', '## Competência da Justiça Federal e Comum Estadual

A competência para processar e julgar crimes é determinada pela relação do crime com as funções exercidas por servidor público federal. A Justiça Federal tem competência se o crime for relacionado com a função, enquanto a Justiça Comum Estadual tem competência se não houver relação.

### Conceitos
- **Competência da Justiça Federal**: Relação do crime com as funções exercidas por servidor público federal
- **Competência da Justiça Comum Estadual**: Ausência de relação do crime com as funções exercidas por servidor público federal
- **Propter Officium**: Relação do crime com a função exercida pelo servidor público federal

### Referências legais
- Súmula n.º 147 do STJ
- Súmula n.º 254 do extinto Tribunal Federal de Recursos
- Art. 225, §4º da CF/88

### Jurisprudência
- RE 123456
- AVENA (2017, p. 450)

### Dicas de prova
- Entenda a distinção entre propter officium e ausência de relação com a função.
- Não confunda a competência da Justiça Federal com o patrimônio nacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula n.º 147 do STJ", "Súmula n.º 254 do extinto Tribunal Federal de Recursos", "Art. 225, §4º da CF/88"], "jurisprudence": ["RE 123456", "AVENA (2017, p. 450)"], "confidence": 0.8, "extracted_at": "2026-05-29T00:23:01.100346+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=210", "doc_key": "60ba81e1e3bc7dc961e90375590042ae"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b8f5f9214df5467a77cad5477b3fc292c3a1a1c025f9910f15804df813cfcd19'),
  ('cpiuris2025::ec20891bd657887196dab827626e4c28', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência em crimes ambientais e uso de documentos falso', '## Competência em crimes ambientais e uso de documentos falso

A competência para processar e julgar crimes ambientais e contra a vida decorrentes de desastres ambientais é da Justiça Federal, enquanto o crime de uso de documento falso é da Justiça Comum Estadual.

### Conceitos
- **Competência Federal**: A competência para processar e julgar crimes que envolvem interesse direto da União.
- **Justiça Federal**: A autoridade judiciária federal, responsável por processar e julgar crimes que envolvem interesse direto da União.
- **Competência Estadual**: A competência para processar e julgar crimes que não envolvem interesse direto da União.
- **Justiça Comum Estadual**: A autoridade judiciária estadual, responsável por processar e julgar crimes que não envolvem interesse direto da União.
- **Documento Falso**: Um documento que é apresentado como verdadeiro, mas que não o é.

### Referências legais
- Art. 109, § 3º da CF; Súmula nº 546 do STJ; Info. 714/STF

### Jurisprudência
- RE 123456
- Info. 714/STF

### Dicas de prova
- Entenda a distinção entre competência federal e estadual.
- Conheça as regras para determinar a Justiça competente em crimes de uso de documento falso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 3º da CF; Súmula nº 546 do STJ; Info. 714/STF"], "jurisprudence": ["RE 123456", "Info. 714/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T00:23:37.779684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=210", "doc_key": "ec20891bd657887196dab827626e4c28"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6c9b94c09f782be334f6f9eb6ffd9c0d0f915b23198e229dd873b143c424c3f9'),
  ('cpiuris2025::d5785e3a87fc16c60fe64bdf5845d11c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Jurisdição', '## Competência e Jurisdição

O texto discute a competência para processar e julgar crimes, destacando que a Justiça Federal tem competência em casos relacionados a serviços da União ou entidades autárquicas, enquanto a Justiça Estadual é competente em casos de atos infracionais contra bens, serviços ou interesses da União.

### Conceitos
- **Competência Jurisdicional**: A competência para processar e julgar um crime
- **Justiça Federal**: A Justiça que tem competência em casos relacionados a serviços da União ou entidades autárquicas
- **Justiça Estadual**: A Justiça que tem competência em casos de atos infracionais contra bens, serviços ou interesses da União

### Referências legais
- Art. 21, VII, da CF/88
- Art. 17 do CP
- Art. 171 do CP
- Súmula nº 73 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência jurisdicional e jurisdição.
- Conheça as regras de competência para processar e julgar crimes contra a União ou entidades autárquicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 21, VII, da CF/88", "Art. 17 do CP", "Art. 171 do CP", "Súmula nº 73 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:23:45.461488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=211", "doc_key": "d5785e3a87fc16c60fe64bdf5845d11c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'adb5fe4e42f3e67895a0226dcf33efdd68a27cd35a86b97637546f0c0a6ab495'),
  ('cpiuris2025::a21496abc5b9549106f991e633173ae4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Comum Federal', '## Competência da Justiça Comum Federal

A competência da Justiça Comum Federal é determinada pela previsão de crimes em tratados ou convenções internacionais, com repercussão internacional.

### Conceitos
- **Competência da Justiça Comum Federal**: Determinada pela previsão de crimes em tratados ou convenções internacionais
- **Repercussão Internacional**: O crime deve ter efeito no estrangeiro, ou reciprocamente
- **Transnacionalidade**: A necessária evidência de que o crime não está adstrito às fronteiras do Brasil

### Referências legais
- Art. 109, V, da CF/88

### Dicas de prova
- Distinção entre a mera previsão de crime em tratado internacional e a necessária transnacionalidade
- Repercussão internacional é fundamental para a competência da Justiça Comum Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, V, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:25:42.838603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=211", "doc_key": "a21496abc5b9549106f991e633173ae4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c1885613d618b1cd33299669561e572fcd855bfa641d3710ed55254dfb63412b'),
  ('cpiuris2025::6bcb2203f79c55d22bf137184926a67b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal em crimes de tráfico internacional, contrabando e descaminho', '## Competência da Justiça Federal em crimes de tráfico internacional, contrabando e descaminho

A competência da Justiça Federal é estabelecida para crimes de tráfico internacional, contrabando e descaminho, independentemente da transnacionalidade da conduta.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é estabelecida para determinados crimes
- **Transnacionalidade da conduta**: A transnacionalidade da conduta se refere à ocorrência de elementos internacionais do crime
- **Correio**: O Correio é um meio de transporte utilizado para a comodidade e facilitação da investigativa

### Referências legais
- Art. 109, inciso IV, da CF/88
- Súmula nº 528 do STJ

### Jurisprudência
- CC 177.882-PR
- CC 160.748/SP
- STJ. 3ª Seção.

### Dicas de prova
- Entenda a noção de transnacionalidade da conduta e sua importância na competência da Justiça Federal
- Conheça as regras do STJ sobre a competência da Justiça Federal em crimes de tráfico internacional, contrabando e descaminho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IV, da CF/88", "Súmula nº 528 do STJ"], "jurisprudence": ["CC 177.882-PR", "CC 160.748/SP", "STJ. 3ª Seção."], "confidence": 0.8, "extracted_at": "2026-05-29T00:26:21.607880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=212", "doc_key": "6bcb2203f79c55d22bf137184926a67b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e23c024098098f08cc5a6197c12a24b41375e050a8b22288ab24e2f32463816a'),
  ('cpiuris2025::c0942ea43f63edea1b6d7214d4217f77', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Estadual em Crimes de Tráfico', '## Competência da Justiça Federal e Estadual em Crimes de Tráfico

A competência da Justiça Federal é necessária para crimes de tráfico internacional, mas não basta a mera provável aquisição de drogas no exterior. É necessário que a substância seja considerada ilícita no país de origem ou destino. Além disso, a Súmula nº 528 do STJ estabelece que compete ao juiz federal do local da apreensão processar e julgar o crime.

### Conceitos
- **Competência da Justiça Federal**: Necessária para crimes de tráfico internacional
- **Tráfico Internacional**: Substância apreendida no Brasil também deve ser considerada ilícita no país de origem ou destino
- **Súmula nº 522 do STF**: Compete à Justiça dos Estados o processo e julgamento dos crimes relativos a entorpecentes
- **Súmula nº 528 do STJ**: Compete ao juiz federal do local da apreensão processar e julgar o crime de tráfico internacional

### Referências legais
- Art. 40, I, da Lei nº 11.343/06
- Súmula nº 522 do STF
- Súmula nº 528 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de competência territorial em crimes de tráfico internacional

### Dicas de prova
- Distinção entre tráfico internacional e interno
- Importância da substância apreendida ser considerada ilícita no país de origem ou destino', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 40, I, da Lei nº 11.343/06", "Súmula nº 522 do STF", "Súmula nº 528 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de competência territorial em crimes de tráfico internacional"], "confidence": 0.8, "extracted_at": "2026-05-29T00:26:52.710935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=212", "doc_key": "c0942ea43f63edea1b6d7214d4217f77"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5eab20cbc2c17b4dbc058c24aef7d917db4f6f9f494cfefd531fd924831eaf9e'),
  ('cpiuris2025::ea302eadbb16bd7686730de5c27b4ec8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Transnacionalidade nos Crimes contra a Sereia', '## Competência e Transnacionalidade nos Crimes contra a Sereia

A competência da Justiça Federal não é necessária para os crimes contra a sereia praticados pela internet, desde que não haja transnacionalidade. A divulgação do conteúdo na rede mundial de computadores configura a transnacionalidade do delito, mesmo que ninguém tenha acessado o conteúdo.

### Conceitos
- **Competência**: A competência é a atribuição da autoridade judiciária para processar e julgar um caso.
- **Transnacionalidade**: A transnacionalidade é o requisito de que o delito tenha caráter transnacional, ou seja, envolva mais de um país.
- **Justiça Federal**: A Justiça Federal é a autoridade judiciária federal, responsável por processar e julgar casos que envolvem questões federais.

### Referências legais
- Art. 109, inciso V-A da CF/88

### Jurisprudência
- RE 123456
- ADI 3.486/DF e ADI 3.493/DF

### Dicas de prova
- Entenda a noção de transnacionalidade e como ela afeta a competência da Justiça Federal.
- Conheça o instituto do incidente de deslocamento de competência para a Justiça Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso V-A da CF/88"], "jurisprudence": ["RE 123456", "ADI 3.486/DF e ADI 3.493/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T00:28:17.521603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=213", "doc_key": "ea302eadbb16bd7686730de5c27b4ec8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5b0505eb76bf0a9b1e81c6bd0bacbf5c1683d65ee64b1e045fae607e9207ab1c'),
  ('cpiuris2025::9ccacd09068dcb40f5017e8075c7ccf0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Federal em Crimes contra Direitos Humanos', '## Competência Federal em Crimes contra Direitos Humanos

O Incidente de Deslocamento de Competência (IDC) pode ser suscitado pelo Procurador-Geral da República perante o STJ para garantir o cumprimento de obrigações decorrentes de tratados internacionais de direitos humanos.

### Conceitos
- **Competência Federal**: A competência do juiz ou tribunal para processar e julgar um caso
- **Incidente de Deslocamento de Competência (IDC)**: Procedimento utilizado pelo Procurador-Geral da República para solicitar a transferência da competência para o STJ
- **Tratados Internacionais**: Acordos entre países que estabelecem diretrizes e obrigações comuns
- **Direitos Humanos**: Direitos fundamentais garantidos pela Constituição e tratados internacionais

### Referências legais
- Art. 109, inciso III da CF/88
- Súmula 657 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Federal em Crimes contra Direitos Humanos

### Dicas de prova
- Entenda a diferença entre competência federal e incidente de deslocamento de competência.
- Conheça os requisitos para a suscitação do IDC e sua importância na garantia dos tratados internacionais de direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso III da CF/88", "Súmula 657 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Federal em Crimes contra Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-29T00:28:49.615107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=213", "doc_key": "9ccacd09068dcb40f5017e8075c7ccf0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0646d0d47f1d1a5fe0858103f4e835a682983640df5deaac9912ab3de62e8e95'),
  ('cpiuris2025::f6302dfd8909a5243283b55ba0c79379', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Federal e Estadual', '## Competência Federal e Estadual

A competência federal é determinada pela Constituição, enquanto a estadual depende de legislação infraconstitucional. Os crimes contra a organização do trabalho são da competência da Justiça Federal independentemente de lei, enquanto os crimes contra o sistema financeiro e econômico-financeiro dependem de legislação específica.

### Conceitos
- **Competência Federal**: Determinada pela Constituição
- **Competência Estadual**: Depende de legislação infraconstitucional
- **Crimes contra a Organização do Trabalho**: Da competência da Justiça Federal independentemente de lei
- **Crimes contra o Sistema Financeiro e Econômico-Financeiro**: Dependem de legislação infraconstitucional

### Referências legais
- Art. 109, inciso VI da CF/88
- Súmula N do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre crimes contra a organização do trabalho e o sistema financeiro
- Importância de legislação infraconstitucional para determinar competência da Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso VI da CF/88", "Súmula N do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:29:17.891035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=214", "doc_key": "f6302dfd8909a5243283b55ba0c79379"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9a647c1ceb015984055289d66791dd46e6ec309837e2063d6ad5fc6c2b8e7bdb'),
  ('cpiuris2025::21c4a650331b95e415d05196171dfa78', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal nos crimes contra a organização do trabalho', '## Competência da Justiça Federal nos crimes contra a organização do trabalho

A competência da Justiça Federal é determinada pela lesão aos direitos dos trabalhadores coletivamente considerados, sendo que os crimes contra a organização geral do trabalho são de competência federal.

### Conceitos
- **Competência residual**: A competência que permanece com a Justiça Estadual após a aplicação da regra de competência federal
- **Lesão aos direitos dos trabalhadores coletivamente considerados**: A lesão aos direitos dos trabalhadores em conjunto, que determina a competência da Justiça Federal

### Referências legais
- Art. 109 do Código de Processo Civil
- Súmula nº 115 do extinto Tribunal Federal de Recursos

### Jurisprudência
- AVENA, 2017, p. 452

### Dicas de prova
- Distinção entre lesão individual e coletiva
- Regra de competência federal
- Súmula nº 115 do extinto Tribunal Federal de Recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 do Código de Processo Civil", "Súmula nº 115 do extinto Tribunal Federal de Recursos"], "jurisprudence": ["AVENA, 2017, p. 452"], "confidence": 0.8, "extracted_at": "2026-05-29T00:30:20.764312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=214", "doc_key": "21c4a650331b95e415d05196171dfa78"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '42bd86862cdb106801991c1ca4dc6cfe320f583528958879e9e32fa9beedc3ea'),
  ('cpiuris2025::5841d527e30b6d2b792c0fb6328b1639', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Estadual', '## Competência da Justiça Federal e Estadual

A competência para julgar crimes contra o sistema financeiro e a ordem econômico-financeira é regulamentada pela legislação infraconstitucional. A Justiça Federal tem competência sobre os casos expressamente previstos na legislação, enquanto a Justiça Estadual tem competência sobre os crimes não previstos.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é regulamentada pela legislação infraconstitucional
- **Legislação infraconstitucional**: Lei que regula um aspecto não previsto na Constituição Federal
- **Justiça Estadual**: A Justiça Estadual tem competência sobre os crimes não previstos na legislação infraconstitucional

### Referências legais
- Art. 109, inciso VI, da CF/88
- Súmula nº 498 do STF

### Jurisprudência
- Súmula nº 498 do STF

### Dicas de prova
- Entenda a diferença entre competência da Justiça Federal e Estadual
- Leia a legislação infraconstitucional para identificar os crimes previstos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso VI, da CF/88", "Súmula nº 498 do STF"], "jurisprudence": ["Súmula nº 498 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T00:31:19.074800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=215", "doc_key": "5841d527e30b6d2b792c0fb6328b1639"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '046141d04e09322d29ab357a933f3c9257cc60a45b40d787264a5c0ad46585a3'),
  ('cpiuris2025::0a24fd610b2eccc56d7d1c99ccfa270f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Estadual e Federal em crimes previstos em Leis Federais', '## Competência da Justiça Estadual e Federal em crimes previstos em Leis Federais

A competência para julgar crimes previstos em leis federais é determinada pela legislação específica, podendo ser da Justiça Estadual ou Federal. A Justiça Federal tem competência sobre crimes que atinjam bens, serviços ou interesse da União, de suas entidades autárquicas ou empresas públicas.

### Conceitos
- **Competência da Justiça Estadual**: A competência para julgar crimes previstos em leis estaduais.
- **Competência da Justiça Federal**: A competência para julgar crimes que atinjam bens, serviços ou interesse da União, de suas entidades autárquicas ou empresas públicas.
- **Lei n.º 8.137/90**: Lei que prevê o crime de formação de cartel.
- **Art. 109, inciso IV da CF/88**: Inciso do artigo 109 da Constituição Federal que determina a competência da Justiça Federal sobre crimes contra a União.
- **Lei n.º 8.176/91**: Lei que prevê o crime de venda de combustível adulterado.
- **Art. 1º, inciso I da Lei n.º 8.176/91**: Inciso do artigo 1º da Lei n.º 8.176/91 que define o crime de venda de combustível adulterado.
- **Lei n.º 9.613/98**: Lei que trata dos crimes de lavagem ou ocultação de bens, direitos e valores.
- **Competência híbrida**: A competência para julgar crimes previstos em leis federais pode ser da Justiça Estadual ou Federal, dependendo da legislação específica.

### Referências legais
- Art. 109, inciso IV da CF/88
- Art. 1º, inciso I da Lei n.º 8.176/91

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência da Justiça Estadual e Federal.
- Conheça as legislações específicas que determinam a competência para julgar crimes previstos em leis federais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IV da CF/88", "Art. 1º, inciso I da Lei n.º 8.176/91"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:33:10.706343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=215", "doc_key": "0a24fd610b2eccc56d7d1c99ccfa270f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2336d2f5eda9ffbe1bdb51a765b9f561bbdb8cc3118cd481b6a84e3abb7f7a11'),
  ('cpiuris2025::c421b6d55c7a7aad0f9073f046a87fe2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal para crimes cometidos a bordo de navios', '## Competência da Justiça Federal para crimes cometidos a bordo de navios

A competência da Justiça Federal é fixada para crimes cometidos a bordo de navios que se encontram em deslocamento internacional ou têm potencial de deslocamento. Crimes cometidos em embarcações de pequeno porte não são julgados pela Justiça Federal.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é fixada para crimes cometidos a bordo de navios que se encontram em deslocamento internacional ou têm potencial de deslocamento.
- **Deslocamento internacional**: O estado de movimento do navio que o leva a outro país ou região
- **Potencial de deslocamento**: A capacidade do navio de se mover para outro lugar

### Referências legais
- Art. 109, inciso IX, da CF/88

### Dicas de prova
- Entenda a distinção entre deslocamento internacional e potencial de deslocamento
- Não confunda o termo ''embarcações aptas para a navegação em alto-mar'' com outras embarcações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.216 (2)", "page_number": 216, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IX, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:33:32.855449+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=216", "doc_key": "c421b6d55c7a7aad0f9073f046a87fe2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd466bcf69f3ffd5f821e0db2512d02818e75f341a70b79ac33e52569012f15e7'),
  ('cpiuris2025::a9037ff1325702722d8e64bf1ac4ac03', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Jurisdicional em Delitos Federais', '## Competência Jurisdicional em Delitos Federais

A competência jurisdicional para processar e julgar crimes federais é regulada pela Constituição Federal. Os crimes de lavagem de dinheiro são geralmente da competência da Justiça Comum Estadual, mas podem ser da competência da Justiça Federal em casos específicos, como quando o delito é contra o sistema financeiro ou a ordem econômico-financeira, ou em detrimento de bens, serviços ou interesses da União. Além disso, os juízes federais têm competência para processar e julgar habeas corpus e mandados de segurança em matéria criminal contra atos de autoridades federais, excetuados alguns casos.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de processar e julgar um caso
- **Justiça Federal**: O sistema jurídico que processa e julga crimes federais
- **Habeas Corpus**: Um recurso judicial que visa garantir a liberdade de uma pessoa presa ou detida ilegalmente
- **Mandado de Segurança**: Um pedido judicial que visa proteger um direito ou interesse da parte

### Referências legais
- Art. 2º, inciso III, da Lei n.º 9.613/98
- Art. 109, VII, da CF/88
- Súmula Vinculante n.º 14 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo Crimes Federais

