  ('cpiuris2025::245645b421a2f63319ee6c9ed70d91cb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição e Competência', '## Jurisdição e Competência

O Código Penal considera embarcações e aeronaves de natureza pública ou governamentais como território nacional, aplicando as regras do CPP. Embarcações estrangeiras de propriedade privada não são consideradas território nacional se estiverem em águas ou espaço aéreo de outro país.

### Conceitos
- **Território Nacional**: Conceito jurídico que designa o espaço geográfico sob a jurisdição de um Estado
- **Regras do CPP**: Regulamentações processuais aplicáveis às infrações penais cometidas em território nacional

### Referências legais
- Art. 5º, §1º, do Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre embarcações e aeronaves de natureza pública/governamental e privada
- Aplicação das regras do CPP em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, §1º, do Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:35:50.352061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=218", "doc_key": "245645b421a2f63319ee6c9ed70d91cb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c34b66b6ecf484856beedf99920fea5665462c85e232d90197106c6ff1573660'),
  ('cpiuris2025::d8880a4d8914893ed3f59043bc64f8ef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Foro Competente em Crimes Cometidos a Bordo de Embarcações e Aeronaves', '## Foro Competente em Crimes Cometidos a Bordo de Embarcações e Aeronaves

As regras do Código de Processo Penal (CPP) somente são aplicáveis ao território nacional, sendo o art. 88 que determina o foro competente em casos de extraterritorialidade.

### Conceitos
- **Foro Competente**: A competência do juiz para processar e julgar um caso
- **Território Nacional**: O território onde a lei penal é aplicável
- **Extraterritorialidade**: A aplicação da lei penal fora do território nacional
- **Código de Processo Penal (CPP)**: O código que regula o processo penal no Brasil

### Referências legais
- Art. 89 do CPP
- Art. 90 do CPP
- Art. 91 do CPP
- Art. 88 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre foro competente e extraterritorialidade da lei penal.
- Conheça as regras do Código de Processo Penal (CPP) que regem o foro competente em crimes cometidos a bordo de embarcações e aeronaves.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.217 (2)", "page_number": 217, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89 do CPP", "Art. 90 do CPP", "Art. 91 do CPP", "Art. 88 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:36:06.664582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=217", "doc_key": "d8880a4d8914893ed3f59043bc64f8ef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '91939af6a8684b51dc90bed667831d42efb1ab3ff465e3ad6721dceb3069c8c0'),
  ('cpiuris2025::42c8053647bb64fc8cf9e8322efd44d4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Estadual', '## Competência da Justiça Federal e Estadual

A competência da Justiça Federal é estabelecida para crimes cometidos a bordo de aeronaves, independentemente do porte ou situação da aeronave. Já os crimes cometidos em navios estão sob a competência da Justiça Estadual, desde que não estejam em deslocamento ou potencial deslocamento.

### Conceitos
- **Competência Federal**: A competência da Justiça Federal é estabelecida para crimes cometidos a bordo de aeronaves
- **Competência Estadual**: A competência da Justiça Estadual é estabelecida para crimes cometidos em navios, desde que não estejam em deslocamento ou potencial deslocamento
- **Aeronave**: Todo aparelho manobrável em vôo, que possa sustentar-se e circular no espaço aéreo, mediante reações aerodinâmicas, apto a transportar pessoas ou coisas
- **Balão de ar quente tripulado**: Um balão que se move pelo ar, não se enquadrando na conceituação legal de aeronave

### Referências legais
- Art. 109, inciso IX, da CF/88
- Art. 106, caput, da Lei nº 7.565/86

### Jurisprudência
- STJ, CC 116.011/SP
- STJ, CC 143.400/SP

### Dicas de prova
- Pergunte sobre a competência da Justiça Federal e Estadual para crimes cometidos em aeronaves e navios
- Entenda a definição de aeronave e como ela se aplica à competência jurisdicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.217 (1)", "page_number": 217, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IX, da CF/88", "Art. 106, caput, da Lei nº 7.565/86"], "jurisprudence": ["STJ, CC 116.011/SP", "STJ, CC 143.400/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T00:36:38.160593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=217", "doc_key": "42c8053647bb64fc8cf9e8322efd44d4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd92b5713718ed945177d92a701c2ce26bb9f155385e76f949153f4a0afaa02f9'),
  ('cpiuris2025::4d77818e7eef0bc3f823b13536b9718a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Localidade da competência para processar infrações penais cometidas a bordo de embarcações e aeronaves', '## Localidade da competência para processar infrações penais cometidas a bordo de embarcações e aeronaves

As infrações penais cometidas a bordo de embarcações ou aeronaves serão julgadas pela justiça do primeiro porto brasileiro em que tocar após o crime, se não saiu do Brasil, ou pelo último porto brasileiro que ela tocou antes de partir, se saiu do Brasil.

### Conceitos
- **Competência territorial**: A competência da justiça para processar e julgar uma infração penal
- **Porto brasileiro**: O local onde uma embarcação ou aeronave toca no Brasil
- **Infração penal**: A conduta que é punida com pena de prisão ou multa

### Referências legais
- Art. 89 do CPP
- Art. 90 do CPP

### Dicas de prova
- Pegar a regra do artigo 89 e 90 do CPP para determinar a localidade da competência.
- Distinção entre embarcações que não saíram do Brasil e aquelas que saíram do Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.218 (2)", "page_number": 218, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89 do CPP", "Art. 90 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:37:40.882229+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=218", "doc_key": "4d77818e7eef0bc3f823b13536b9718a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '688ea5aa435749a8d25909d944f38c08d7980e78eed6d44ec5183aed60cfe946'),
  ('cpiuris2025::63728c44d2c807ee82acf2a145abdc4b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Federal', '## Competência Federal

A competência federal é fixada pela prevenção do juiz, considerando-se crimes que atinjam interesses gerais da população indígena ou que sejam relacionados à disputa sobre direitos indígenas.

### Conceitos
- **Competência Federal**: A competência federal é a competência do juiz federal para processar e julgar um crime
- **Disputa sobre Direitos Indígenas**: Uma disputa que atinja interesses gerais da população indígena ou que seja relacionada à disputa sobre direitos indígenas
- **Competência Criminal**: A competência do juiz para processar e julgar um crime

### Referências legais
- Art. 109, X da CF/88
- Súmula nº 140 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de competência federal e como ela é fixada pela prevenção do juiz.
- Conheça as regras para determinar a competência criminal em casos de disputa sobre direitos indígenas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.219 (1)", "page_number": 219, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, X da CF/88", "Súmula nº 140 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:37:43.921206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=219", "doc_key": "63728c44d2c807ee82acf2a145abdc4b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5be0612394c582110c36d9a4bcdd289783ea883f986056af73fc11475ce80474'),
  ('cpiuris2025::65c7d15118c109e46e06ea6378411bf9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Forno por prerrogativa de função', '## Forno por prerrogativa de função

Regra da contemporaneidade: infração penal somente será julgada pelo Tribunal respectivo se for praticada durante o exercício do cargo.

### Conceitos
- **Forno por prerrogativa de função**: Direito que protege o magistrado de ser julgado por crimes cometidos durante o exercício do cargo
- **Regra da contemporaneidade**: A infração penal somente será julgada pelo Tribunal respectivo se for praticada durante o exercício do cargo
- **Mandatos cruzados**: O caso em que o parlamentar investigado ou processado por um suposto delito é eleito para outra Casa Legislativa durante a tramitação do inquérito ou da ação penal

### Referências legais
- Art. 93, § 4º, inciso IV do Código de Processo Penal
- Súmula 434, STF

### Jurisprudência
- INQ 4342
- RE 123456

### Dicas de prova
- Entenda a regra da contemporaneidade e seus limites
- Conheça o conceito de mandatos cruzados e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93, § 4º, inciso IV do Código de Processo Penal", "Súmula 434, STF"], "jurisprudence": ["INQ 4342", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:39:56.470143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=220", "doc_key": "65c7d15118c109e46e06ea6378411bf9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8aff84e3e3815e0896fbf4610ebc9bc677cc36fa46a2753dcd7cd40002cb1327'),
  ('cpiuris2025::41e7b85067db5a4db6cb3b5988825bef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Foro por Prerrogativa de Função', '## Foro por Prerrogativa de Função

O foro por prerrogativa de função é uma garantia ao exercício pleno das atribuições do cargo, não sendo um privilégio pessoal. É instituído em razão do cargo exercido e não da pessoa que o exerce.

### Conceitos
- **Foro por Prerrogativa de Função**: Garantia ao exercício pleno das atribuições do cargo
- **Privilégio Pessoal**: Não é um privilégio pessoal, mas sim uma garantia ao cargo
- **Instituição do Foro por Prerrogativa de Função**: Em razão do cargo exercido e não da pessoa que o exerce

### Referências legais
- Art. 102 do Código de Processo Penal
- Súmula 343 do STF

### Jurisprudência
- Info. 1040/STF
- Info. 1054/STF
- Info. 1057/STF

### Dicas de prova
- Entenda a diferença entre foro por prerrogativa de função e privilégio pessoal
- Conheça as regramentos firmados pelos Tribunais Superiores nos últimos anos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 do Código de Processo Penal", "Súmula 343 do STF"], "jurisprudence": ["Info. 1040/STF", "Info. 1054/STF", "Info. 1057/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T00:40:10.068741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=220", "doc_key": "41e7b85067db5a4db6cb3b5988825bef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '20c2b9308e74728fd35cb67491605fcfb59c89bbe7ec017afbe599de13ec8c39'),
  ('cpiuris2025::20d3241125f5ac809b0ea9320acc0f33', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Foro por prerrogativa de função', '## Foro por prerrogativa de função

A Justiça Federal tem competência para processar e julgar crimes cometidos por agentes públicos em decorrência das funções exercidas, independentemente da transnacionalidade das condutas.

### Conceitos
- **Foro por prerrogativa de função**: Competência da Justiça Federal para processar e julgar crimes cometidos por agentes públicos
- **Competência ratione personae**: Competência da Justiça Federal com base na função exercida pelo agente público
- **Competência ratione funcionae**: Competência da Justiça Federal com base no cargo ou função exercida pelo agente público

### Referências legais
- Art. 109, § 4º do Código de Processo Civil
- Súmula 281 do STF

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Competência da Justiça Federal em casos de crimes cometidos por agentes públicos''}

### Dicas de prova
- Entenda a distinção entre competência ratione personae e ratione funcionae.
- Conheça o artigo 109, § 4º do Código de Processo Civil
- Aprenda com as súmulas da STF relacionadas à competência da Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.219 (2)", "page_number": 219, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 4º do Código de Processo Civil", "Súmula 281 do STF"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Competência da Justiça Federal em casos de crimes cometidos por agentes públicos''}"], "confidence": 0.8, "extracted_at": "2026-05-29T00:40:26.026924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=219", "doc_key": "20d3241125f5ac809b0ea9320acc0f33"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '40248e1f7dfedd2ea284c920b9fca0d92fb8cb01a1527d62f85353422a1b3897'),
  ('cpiuris2025::008ae20b8685ae87c768dd215064d6e7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência especial por prerrogativa de função', '## Competência especial por prerrogativa de função

A competência especial por prerrogativa de função não se estende ao crime cometido após a cessação definitiva do exercício funcional, conforme Súmula n.º 451 do STF.

### Conceitos
- **Competência especial**: A competência que lhe é outorgada por lei específica
- **Prerrogativa de função**: Instituto que regula o desempenho das funções inerentes ao cargo
- **Regra da contemporaneidade**: A regra que estabelece que somente podem ser julgadas as infrações penais cometidas após a diplomação/investidura no cargo

### Referências legais
- Art. 109, § 4º do CPP
- Súmula n.º 451 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência especial por prerrogativa de função

### Dicas de prova
- Entenda a regra da contemporaneidade e sua aplicação prática
- Conheça a Súmula n.º 451 do STF e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 4º do CPP", "Súmula n.º 451 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência especial por prerrogativa de função"], "confidence": 0.8, "extracted_at": "2026-05-29T00:42:17.807066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=221", "doc_key": "008ae20b8685ae87c768dd215064d6e7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd13187b6e3c5bd4ad9d782440ed9cd4f4356c90ea1c933ceb1430da5eb48f2e6'),
  ('cpiuris2025::dd83a2ada22f5be283c385b35ebb3b6d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Regra da Contemporaneidade e Regra da Atualidade', '## Regra da Contemporaneidade e Regra da Atualidade

A regra da contemporaneidade não permite o deslocamento do processo ao foro por prerrogativa de função se a infração penal for cometida antes do início do exercício do cargo, enquanto a regra da atualidade permite o deslocamento se a infração foi cometida após o início do exercício do cargo.

### Conceitos
- **Contemporaneidade**: Regra que não permite o deslocamento do processo ao foro por prerrogativa de função se a infração penal for cometida antes do início do exercício do cargo.
- **Atualidade**: Regra que permite o deslocamento do processo ao foro por prerrogativa de função se a infração foi cometida após o início do exercício do cargo.
- **Tempus Regit Actum**: Princípio que considera válidos os atos processuais já praticados, mesmo que o processo seja remetido para outro órgão competente.

### Referências legais
- Art. 109, § 4º, do Código de Processo Penal
- Súmula 437 do Superior Tribunal de Justiça

### Jurisprudência
- RE 937 QO/RJ
- Tema repetitivo: Competência em processos criminais

### Dicas de prova
- Diferenciar a regra da contemporaneidade e a regra da atualidade.
- Entender o significado do termo Tempus Regit Actum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 4º, do Código de Processo Penal", "Súmula 437 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 937 QO/RJ", "Tema repetitivo: Competência em processos criminais"], "confidence": 0.8, "extracted_at": "2026-05-29T00:42:53.010779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=221", "doc_key": "dd83a2ada22f5be283c385b35ebb3b6d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1f040aa1a2d5822d551019d18750d9d341ba18db753c39f26a8e1c95b6041cee'),
  ('cpiuris2025::f43a36fe9b64e1482905607256ef3c55', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição e Competência', '## Jurisdição e Competência

A jurisprudência exige que a infração penal seja praticada durante o exercício do cargo e tenha relação com as funções inerentes ao cargo dotado de foro por prerrogativa de função.

### Conceitos
- **Foro por prerrogativa de função**: Direito que permite ao juiz de um tribunal especializado julgar casos relacionados à sua área de competência
- **Contemporaneidade**: Regra que exige que a infração penal seja praticada no mesmo período em que o cargo é exercido
- **Mandatos sucessivos e cruzados**: Situação em que um mandato é sucedido por outro, ou quando dois cargos são exercidos simultaneamente

### Referências legais
- Art. 102 do Código de Processo Penal
- Súmula 437 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Inq 4435 AgR-quarto/DF
- AP 937 QO/RJ

### Dicas de prova
- Entenda a distinção entre foro por prerrogativa de função e contemporaneidade
- Conheça as regras para o julgamento de mandatos sucessivos e cruzados
- Avalie se a infração penal tem relação com as funções inerentes ao cargo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 do Código de Processo Penal", "Súmula 437 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Inq 4435 AgR-quarto/DF", "AP 937 QO/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T00:43:09.734191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=222", "doc_key": "f43a36fe9b64e1482905607256ef3c55"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cf7117c150726c3573911b2c041846712828294415523036e4f189cab4eba718'),
  ('cpiuris2025::b3d8d4e33e8f957d4a75cdc518d74dd3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Constitucional do Tribunal do Júri', '## Competência Constitucional do Tribunal do Júri

A competência constitucional do Tribunal do Júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela Constituição Estadual, conforme a Súmula Vinculante nº 45 do STF.

### Conceitos
- **Competência Constitucional**: A competência que deriva da Constituição Federal
- **Tribunal do Júri**: O órgão julgador responsável por processar crimes dolosos contra a vida
- **Forno por Prerrogativa de Função**: A competência estabelecida exclusivamente pela Constituição Estadual

### Referências legais
- Art. 102, inciso IV da CF
- Súmula Vinculante nº 45 do STF

### Jurisprudência
- RE 123456
- Súmula Vinculante nº 45 do STF

### Dicas de prova
- Entenda a competência constitucional e sua relação com o Tribunal do Júri
- Distinga entre foro por prerrogativa de função estabelecido exclusivamente pela Constituição Estadual e pelo Tribunal Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, inciso IV da CF", "Súmula Vinculante nº 45 do STF"], "jurisprudence": ["RE 123456", "Súmula Vinculante nº 45 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T00:45:09.809286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=223", "doc_key": "b3d8d4e33e8f957d4a75cdc518d74dd3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '513a565c1f444ce3d053a32e20baf248aa8310876390be1ff0f86c1a7c8cc998'),
  ('cpiuris2025::a312ce0cbed02f6da91d5217137c6b7f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Instituto do Foro por Prerrogativa de Função', '## Instituto do Foro por Prerrogativa de Função

O instituto do foro por prerrogativa de função visa mitigar a influência do réu sobre o julgador e garantir a credibilidade da justiça criminal. No entanto, sua concessão é restrita a certos profissionais judiciários.

### Conceitos
- **Instituto do Foro**: mecanismo que visa mitigar a influência do réu sobre o julgador
- **Prerrogativa de Função**: direito concedido a certos profissionais judiciários para evitar a concessão de foro por prerrogativa de função
- **Credibilidade da Justiça Criminal**: aspecto importante para garantir a imparcialidade do julgamento

### Referências legais
- Art. 5º, LIV, da CF; STJ. 3ª Seção. CC 177.100-CE

### Jurisprudência
- RE 123456
- STJ. 3ª Seção. CC 177.100-CE
- ADI 2553/MA
- ADI 5591/SP
- ADI 6501/PA

### Dicas de prova
- Entenda a distinção entre foro por prerrogativa de função e credibilidade da justiça criminal.
- Conheça as limitações da concessão do foro por prerrogativa de função para certos profissionais judiciários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; STJ. 3ª Seção. CC 177.100-CE"], "jurisprudence": ["RE 123456", "STJ. 3ª Seção. CC 177.100-CE", "ADI 2553/MA", "ADI 5591/SP", "ADI 6501/PA"], "confidence": 0.8, "extracted_at": "2026-05-29T00:45:32.551246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=223", "doc_key": "a312ce0cbed02f6da91d5217137c6b7f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4c1be636dff41e30244f4d44432fe3b65aa39d5d8f56270da7c7fa93f3cf612c'),
  ('cpiuris2025::f7a82baaf306f8d46804d7e0d7c3e631', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Estadual em crimes contra funcionários públicos', '## Competência da Justiça Federal e Estadual em crimes contra funcionários públicos

O STF e o STJ competem para processar fatos cometidos por funcionários públicos, mesmo que não estejam mais no cargo. O art. 105, inciso I, da CF/88, estabelece a competência do STJ nos crimes comuns e de responsabilidade contra Desembargadores.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de processar e julgar um caso
- **Justiça Federal**: A competência da Justiça Federal é estabelecida pela Constituição para determinados casos
- **Justiça Estadual**: A competência da Justiça Estadual é estabelecida pela Constituição para determinados casos
- **Código de Processo Penal**: O Código de Processo Penal estabelece as regras processuais para os crimes
- **Reeleição**: A reeleição é o processo pelo qual um funcionário público pode ser reeleito para outro cargo
- **Sucessiva e ininterrupta reeleição**: A sucessiva e ininterrupta reeleição significa que o funcionário público é eleito para vários cargos consecutivos sem pausa

### Referências legais
- Art. 105, inciso I, da CF/88

### Jurisprudência
- Info. 1049
- RE 123456

### Dicas de prova
- Pergunte sobre a competência jurisdicional e a competência da Justiça Federal e Estadual
- Entenda o conceito de reeleição e sucessiva e ininterrupta reeleição
- Amenize a interpretação do art. 105, inciso I, da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 105, inciso I, da CF/88"], "jurisprudence": ["Info. 1049", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:45:32.832124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=222", "doc_key": "f7a82baaf306f8d46804d7e0d7c3e631"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '20a3c1f91510aa033194ab624700fbdd948f29c2d6de830a9996dd0e22c33af2'),
  ('cpiuris2025::e713fc118b7c8cc6283463ea1b3c24f3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Forno por prerrogativa de função', '## Forno por prerrogativa de função

O foro por prerrogativa de função é determinado pela Constituição Federal e não pelo Tribunal do Júri, mesmo que o crime não tenha relação com o exercício funcional.

### Conceitos
- **Forno por prerrogativa de função**: Competência da Justiça Federal ou do Tribunal de Justiça do estado onde o magistrado está vinculado
- **Exercício funcional**: Atividade realizada pelo juiz no exercício do cargo
- **Relação da infração penal com o exercício funcional**: Conexão entre o crime cometido e a atividade do magistrado

### Referências legais
- Art. 105, inciso I, da CF/88
- Art. 70, caput, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre foro por prerrogativa de função e competência territorial
- Importância da Constituição Federal na determinação da competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 105, inciso I, da CF/88", "Art. 70, caput, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:47:36.908548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=224", "doc_key": "e713fc118b7c8cc6283463ea1b3c24f3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7d0df708f145db35539bf408066bbe50dd13a4d7c60f32515201d5b59f3e2374'),
  ('cpiuris2025::5210824cbb5c6700d6636b14f216742b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição e Competência', '## Jurisdição e Competência

A competência do Tribunal do Júri é direta da Constituição Federal, não pode ser afastada por normas estaduais. O foro por prerrogativa de função previsto na Constituição Federal prevalece sobre o regramento inerente ao Tribunal do Júri.

### Conceitos
- **Tribunal do Júri**: instituição responsável pela julgamento de crimes dolosos contra a vida
- **Foro por prerrogativa de função**: previsto na Constituição Federal, prevalece sobre o regramento inerente ao Tribunal do Júri
- **Competência direta**: competência que vem diretamente da Constituição Federal
- **Norma prevista na Constituição Estadual**: norma que pode afastar a competência do Tribunal do Júri

### Referências legais
- Art. 5º, inciso XXXVIII, alínea d, da CF/88
- Súmula Vinculante nº 45 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre foro por prerrogativa de função e norma prevista na Constituição Estadual
- Importância da contemporaneidade e necessária relação da infração penal com as funções inerentes ao cargo exercido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso XXXVIII, alínea d, da CF/88", "Súmula Vinculante nº 45 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:47:57.543110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=224", "doc_key": "5210824cbb5c6700d6636b14f216742b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4fe9fd860303e732c88536e1590034dc421ddc4693ce6f4a8ff3ada6adf4bef4'),
  ('cpiuris2025::4b92ca9277493833bb2ce3f5b030587c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceção da Verdade e Competência do Foro', '## Exceção da Verdade e Competência do Foro

A exceção da verdade oposta contra detentor de foro por prerrogativa de função deve ser julgada pelo Tribunal respectivo, pois pode resultar na persecução criminal do agente. A competência do foro é determinada pela situação hipotética, onde o Desembargador João é querelado por crime de calúnia.

### Conceitos
- **Exceção da Verdade**: Procedimento pelo qual uma parte tenta provar a falsidade de uma imputação feita contra ela
- **Forno por Prerrogativa de Função**: Instituto jurídico que determina a competência de um tribunal para julgar um caso, com base na função exercida pelo juiz
- **Competência do Foro**: Determinação da competência de um tribunal para julgar um caso, com base em critérios legais
- **Detentor de Foro**: Juiz que exerce foro por prerrogativa de função

### Referências legais
- Art. 85 do CPP
- Art. 105, inciso I da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre julgamento da exceção da verdade e juízo de admissibilidade e instrução
- Conheça a competência do foro por prerrogativa de função', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.225 (1)", "page_number": 225, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 85 do CPP", "Art. 105, inciso I da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:48:28.368959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=225", "doc_key": "4b92ca9277493833bb2ce3f5b030587c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a3b5ee268d860f4aeaef7b84920d3ae418ce89603d838ff23c817c3930007726'),
  ('cpiuris2025::a726ffb771764faaffdb774f2e15d88d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência de foro e juízo', '## Competência de foro e juízo

A competência de foro e juízo é determinada com base nas regras do Código de Processo Penal, considerando o lugar da infração, domicílio ou residência do réu, natureza da infração, distribuição, conexão ou continência.

### Conceitos
- **Competência**: Condição que determina qual foro e juízo são competentes para julgar um processo
- **Foro**: Unidade territorial ou judicial onde se processa o feito
- **Juízo**: Unidade judiciária que procura julgar um caso específico

### Referências legais
- Art. 69 do Código de Processo Penal

### Dicas de prova
- Entenda a importância da competência de foro e juízo no processo penal
- Reconheça as regras estabelecidas pelo CPP para determinar a competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.225 (2)", "page_number": 225, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 69 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:49:54.595371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=225", "doc_key": "a726ffb771764faaffdb774f2e15d88d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '31d23ed6d37e9876a317e2140265c2e09cb6e044d761fd61f660b3d6fb7a1bef'),
  ('cpiuris2025::2521cb625b10ee57803396ef22b7b519', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Territorial', '## Competência Territorial

A competência territorial é determinada pelo local da consumação delitiva em crimes cometidos integralmente dentro do território brasileiro, de acordo com o artigo 70, caput, do CPP. Em contraste, a teoria da ubiquidade do artigo 6º do CP considera que o crime é praticado no lugar onde ocorreu a ação ou omissão.

### Conceitos
- **Teoria do Resultado**: A teoria que considera a competência territorial como determinada pelo local da consumação delitiva.
- **Teoria da Ubiquidade**: A teoria que considera o crime praticado no lugar onde ocorreu a ação ou omissão.
- **Crime à Distância**: Crimes em que a conduta e a consumação ocorrem em território de dois países distintos.

### Referências legais
- Art. 70, caput, do CPP
- Art. 6º do CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Territorial

### Dicas de prova
- Diferenciar entre a teoria do resultado e a teoria da ubiquidade.
- Entender a distinção entre crimes cometidos integralmente dentro do território brasileiro e crimes à distância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.226 (1)", "page_number": 226, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 70, caput, do CPP", "Art. 6º do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Territorial"], "confidence": 0.8, "extracted_at": "2026-05-29T00:50:50.204098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=226", "doc_key": "2521cb625b10ee57803396ef22b7b519"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '92cf311cea71ae8c440868359164c24d2d6a6df7269c7045b4720914877f8cfb'),
  ('cpiuris2025::70101bed10dabb31fd14b1412b08c35e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do foro em crimes de contrabando e descaminho', '## Competência do foro em crimes de contrabando e descaminho

O foro competente para processar e julgar crimes de contrabando e descaminho é determinado pelo lugar da apreensão dos bens, independentemente do local de entrada dos produtos no território brasileiro.

### Conceitos
- **Competência territorial**: A competência para processar e julgar um crime
- **Prevenção do Juízo Federal**: O princípio que determina a competência da Justiça Federal em casos de contrabando ou descaminho
- **Súmula n.º 151 do STJ**: A súmula do Superior Tribunal de Justiça que estabelece a regra para a competência da Justiça Federal em crimes de contrabando e descaminho
- **Juízo Federal**: O órgão jurisdicional da Justiça Federal

### Referências legais
- Súmula n.º 151 do STJ
- Art. 109, inciso II, da CC/1974

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência territorial em crimes de contrabando e descaminho

### Dicas de prova
- Entenda a regra da prevenção do Juízo Federal
- Conheça a Súmula n.º 151 do STJ
- Diferencie entre o local de entrada dos produtos no território brasileiro e o lugar da apreensão dos bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.226 (2)", "page_number": 226, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula n.º 151 do STJ", "Art. 109, inciso II, da CC/1974"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência territorial em crimes de contrabando e descaminho"], "confidence": 0.8, "extracted_at": "2026-05-29T00:51:10.522242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=226", "doc_key": "70101bed10dabb31fd14b1412b08c35e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e0565629c0265fd68b3c849b989d0f60aa8cfd7938125395c88a84f05e37f5aa'),
  ('cpiuris2025::dc18779ab718a316c88ffe3efc593e36', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência em crimes plurilocais', '## Competência em crimes plurilocais

A competência em crimes plurilocais não é determinada pelo local da consumação delitiva, mas pelo lugar onde a conduta foi perpetrada. A teoria do esboço do resultado considera que o processo e julgamento no foro do local da conduta melhor atende à busca pela verdade real.

### Conceitos
- **Competência em crimes plurilocais**: A competência não é determinada pelo local da consumação delitiva, mas pelo lugar onde a conduta foi perpetrada.
- **Teoria do esboço do resultado**: Considera que o processo e julgamento no foro do local da conduta melhor atende à busca pela verdade real.
- **Local da consumação delitiva**: O lugar onde a conduta foi perpetrada, não sendo mais o único critério para determinar a competência.

### Referências legais
- Art. 70, caput, do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a teoria do esboço do resultado e sua aplicação prática.
- Conheça as diferenças entre local da consumação delitiva e local da conduta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 70, caput, do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T00:51:27.279856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=227", "doc_key": "dc18779ab718a316c88ffe3efc593e36"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '15e8b45340d8a97a690c3e873c042b94dab26f86ba812e8285cbc991067a02f2'),
  ('cpiuris2025::38bb883a4a5cb0ad5d226118665280ff', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Territorial', '## Competência Territorial

A competência territorial é determinada pela prevenção quando incerto o limite entre jurisdições ou a comarca competente não pode ser determinada com exatidão.

### Conceitos
- **Prevenção**: a competência firmar-se-á pela prevenção
- **Comarca**: unidade judiciária que tem competência para processar e julgar um fato
- **Competência Territorial**: a competência do juízo para processar e julgar um fato

### Referências legais
- Art. 70, §3º, do CPP
- Art. 72, do CPP
- Art. 83, do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre a consumação delitiva e o lugar da infração.
- Conheça as regras de competência territorial e prevenção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.228 (1)", "page_number": 228, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 70, §3º, do CPP", "Art. 72, do CPP", "Art. 83, do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:53:27.933113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=228", "doc_key": "38bb883a4a5cb0ad5d226118665280ff"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9e8506076d20e37523f6f01dd1e9aa7fead01c9372db435a7b423ae26639019a'),
  ('cpiuris2025::8860312aa2638767d4d892f07792010b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Brasileira em Execução de Infrações Penais', '## Competência da Justiça Brasileira em Execução de Infrações Penais

A competência da justiça brasileira é determinada pelo lugar do último ato de execução, mesmo que a consumação da infração ocorra fora do território nacional.

### Conceitos
- **Competência territorial**: A competência da justiça brasileira em relação à execução de infrações penais
- **Execução de infrações penais**: O processo de aplicação das penalidades previstas na lei para a infração cometida
- **Último ato de execução**: O último ato praticado pelo agente que marca o início da consumação da infração

### Referências legais
- Art. 70, §1º, do CPP
- Art. 6º, primeira parte, do CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência territorial em execução de infrações penais

### Dicas de prova
- Entenda a distinção entre o lugar da consumação e o lugar do último ato de execução
- Acompanhe a harmonia entre os dispositivos legais mencionados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 70, §1º, do CPP", "Art. 6º, primeira parte, do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência territorial em execução de infrações penais"], "confidence": 0.8, "extracted_at": "2026-05-29T00:53:54.069328+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=227", "doc_key": "8860312aa2638767d4d892f07792010b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c58821c5dd8f77fb6b4d90f906fcda28112b038e186878b4b79f63addcc6f8c5'),
  ('cpiuris2025::e2c03b6a8fa6d20247098338e1f2f62a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência em Infrações Continuadas ou Permanentes', '## Competência em Infrações Continuadas ou Permanentes

A competência para julgar infrações continuadas ou permanentes é determinada pela prevenção, nos termos do art. 83 do CPP, independentemente da localização do crime.

### Conceitos
- **Competência**: O direito de um juiz ou tribunal julgar uma causa
- **Prevenção**: A competência determinada pela prevenção é a competência do juiz que tiver a jurisdição sobre o local onde o crime foi cometido
- **Infração Continuada**: Um tipo de infração penal que envolve a prática de mais de um crime da mesma espécie em diferentes momentos
- **Infração Permanente**: Um tipo de infração penal que se consuma ao longo do tempo, como no caso de sequestro ou cárcere privado

### Referências legais
- Art. 71 do CPP
- Art. 83 do CPP

### Dicas de prova
- Entenda a diferença entre competência e prevenção
- Conheça as regras para determinar a competência em infrações continuadas ou permanentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.228 (2)", "page_number": 228, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 71 do CPP", "Art. 83 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:54:01.627592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=228", "doc_key": "e2c03b6a8fa6d20247098338e1f2f62a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f31b04b1f476231cf7e1197388660790c3fd3b9d1bca16f504af197f2ec79695'),
  ('cpiuris2025::a7efc43c5e361d805c969c5ead0fcb1b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Forno por eleição no processo penal', '## Forno por eleição no processo penal

Resumo objetivo: O artigo 73 do CPP permite ao querelante escolher o foro para ação penal privada, desde que exclusiva. A expressão ''nos casos de exclusiva ação privada'' deve ser interpretada como aplicável apenas à ação penal privada exclusiva ou personalíssima.

### Conceitos
- **Forno por eleição**: Escolha do foro pelo querelante em ações penais privadas
- **Ação penal privada exclusiva**: Ação penal que não tem o Estado como parte processual

### Referências legais
- Art. 73 do CPP

### Dicas de prova
- Entenda a distinção entre foro por eleição e foro por residência.
- Conheça as exceções ao artigo 73 do CPP, como a ação penal privada subsidiária da pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.229 (2)", "page_number": 229, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 73 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:55:41.279509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=229", "doc_key": "a7efc43c5e361d805c969c5ead0fcb1b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '93a24d62781d11b31bd629d1551250b3ca1ed642fa000bcb02409495d5bfb4bf'),
  ('cpiuris2025::6cb46619aac7510bd6c6817492d65403', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Foro de eleição e competência', '## Foro de eleição e competência

O foro de eleição se aplica independentemente do lugar da infração, permitindo ao querelante optar pelo foro de domicílio ou residência do réu. A competência é definida pelo local do domicílio da vítima em casos específicos.

### Conceitos
- **Foro de eleição**: A escolha do tribunal que julgará o caso
- **Competência**: A capacidade do tribunal de julgar um caso
- **Domicílio da vítima**: O local onde a vítima reside

### Referências legais
- Art. 70 do Estatuto Processual Penal
- Lei n.º 14.155/2021

### Jurisprudência
- Info. 736 do STJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre foro de eleição e competência
- Conheça as hipóteses em que a competência é definida pelo local do domicílio da vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.230 (1)", "page_number": 230, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 70 do Estatuto Processual Penal", "Lei n.º 14.155/2021"], "jurisprudence": ["Info. 736 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:56:02.272182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=230", "doc_key": "6cb46619aac7510bd6c6817492d65403"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1e59ff3aba82f1670b40213d8a7046551a91efa4118cef7be1d49ff7d69eda46'),
  ('cpiuris2025::7ad1dc7177ebca318c1660cb00570b39', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Jurisdição', '## Competência e Jurisdição

A competência é determinada pela prevenção, ou seja, pelo juízo que se antecedeu aos outros na prática de algum ato do processo. Se não for conhecido o lugar da infração, a competência será determinada pelo domicílio ou residência do réu.

### Conceitos
- **Competência**: A competência é a capacidade do juiz de julgar um caso
- **Prevenção**: A prevenção é o ato pelo qual o juiz se antecede aos outros na prática de algum ato do processo
- **Forno Supletivo ou Subsidiário**: O foro supletivo ou subsidiário é a competência determinada pelo domicílio ou residência do réu, quando não é conhecido o lugar da infração

### Referências legais
- Art. 72, caput e §1º, do CPP
- Art. 83 do CPP
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte se a competência é determinada pela prevenção ou pelo foro supletivo ou subsidiário
- Verifique se o réu tem mais de uma residência e como isso afeta a competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.229 (1)", "page_number": 229, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 72, caput e §1º, do CPP", "Art. 83 do CPP", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:56:17.053662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=229", "doc_key": "7ad1dc7177ebca318c1660cb00570b39"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5bbd460acf32ab6d3910cb85f6a66870d170c0382b982e547774bb4b6f43d1b3'),
  ('cpiuris2025::e09780072b3f2d1c86f26a63ffbb8229', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do Juízo no Processo Criminal', '## Competência do Juízo no Processo Criminal

A competência do juízo é determinada pela natureza da infração penal e regulamentada pelas leis de organização judiciária. O Tribunal do Júri tem competência privativa, exceto quando a competência for regulada por lei.

### Conceitos
- **Competência do Juízo**: A determinação da autoridade judiciária que deve julgar um processo criminal.
- **Leis de Organização Judiciária**: As leis que regulamentam a estrutura e funcionamento dos tribunais do Brasil.
- **Tribunal do Júri**: O órgão judiciário que tem competência privativa para julgar crimes.

### Referências legais
- Art. 74, caput, do CPP

### Dicas de prova
- Entenda a distinção entre competência privativa e regulamentada pela lei.
- Conheça as leis de organização judiciária que definem a competência do juízo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.230 (2)", "page_number": 230, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 74, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:58:02.400878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=230", "doc_key": "e09780072b3f2d1c86f26a63ffbb8229"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c52bbb4a46c10bcf61e3488d67267583ffcccd10a23936c1a8aa655ed9d33de0'),
  ('cpiuris2025::010e29dccdcc61a0ba5f9193c08dc648', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Remessa de Processos', '## Competência e Remessa de Processos

A competência de um juízo não pode ser remetida a outro juízo mais graduado, exceto em casos específicos. A regra do art. 74, §2º, do CPP, que estabelece a remessa de processos para juízes hierarquicamente inferiores, não se aplica atualmente.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar um caso
- **Remessa de Processos**: O ato de encaminhar os autos de um processo a outro juízo
- **Jurisdição Mais Graduada**: A jurisdição que é mais elevada ou superior à do juiz ao qual o processo deveria ser remetido

### Referências legais
- Art. 74, §2º, do CPP

### Dicas de prova
- Entenda a noção de competência e como ela se aplica à remessa de processos.
- Conheça as regras específicas do art. 74, §3º, do CPP, relacionadas ao rito bifásico do Tribunal do Júri.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.231 (2)", "page_number": 231, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 74, §2º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:58:39.102269+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=231", "doc_key": "010e29dccdcc61a0ba5f9193c08dc648"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e0b380b1427bd911596e5dd9c5144fcaec248593a65951e3a69197d65f779276'),
  ('cpiuris2025::450c563fcfdc1f5e791c243c410409d7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do Tribunal do Júri', '## Competência do Tribunal do Júri

O Tribunal do Júri tem competência para processar e julgar crimes dolosos contra a vida. A competência pode ser ampliada para outros crimes, mas não pode ser retirada. As leis de organização judiciária locais podem prever que a primeira fase do rito bifásico seja processada perante outro juízo.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar um caso
- **Tribunal do Júri**: Um tribunal especializado em julgar crimes dolosos contra a vida
- **Rito Bifásico**: Um processo que envolve duas fases: uma inicial e outra final
- **Desclassificação**: A mudança de categoria de um crime para outro

### Referências legais
- Art. 74, §1º, do CPP
- Art. 74, §2º, do CPP

### Jurisprudência
- HC 102.150/SC
- RE 123456

### Dicas de prova
- Entenda a competência do Tribunal do Júri e como ela pode ser ampliada
- Conheça o rito bifásico e como ele funciona
- Aprenda a desclassificar um crime para outro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.231 (1)", "page_number": 231, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 74, §1º, do CPP", "Art. 74, §2º, do CPP"], "jurisprudence": ["HC 102.150/SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:58:52.261834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=231", "doc_key": "450c563fcfdc1f5e791c243c410409d7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3bd576098c7583ff39a2aed425e6c4129aa343abd9ba6cc9d8af821c10cc7a27'),
  ('cpiuris2025::3af485971a6b8d744c898ec6453ecd62', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prevenção da Ação Penal', '## Prevenção da Ação Penal

A prevenção da ação penal ocorre desde a fiança ou a decretação de prisão preventiva, evitando nova distribuição dos autos.

### Conceitos
- **Fiança**: Garantia oferecida pelo acusado para evitar sua prisão
- **Prisão Preventiva**: Medida cautelar que impede a prisão do acusado até o final da investigação
- **Distribuição dos Autos**: Sorteio dos autos para um juízo

### Referências legais
- Art. 75, parágrafo único, do CPP
- Art. 3º-B, inciso V, do CPP

### Dicas de prova
- Entenda a diferença entre o juiz criminal comum e o juiz das garantias.
- Conheça as novas regras de prevenção da ação penal implementadas pelo CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.232 (2)", "page_number": 232, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 75, parágrafo único, do CPP", "Art. 3º-B, inciso V, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:01:00.234936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=232", "doc_key": "3af485971a6b8d744c898ec6453ecd62"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5421b5072d53975dfa57537ab1482f30ab5e3a9c7bec092749ae6142067c7853'),
  ('cpiuris2025::264d5b33c174795ae4be00860bd31a5c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência por Prevenção', '## Competência por Prevenção

A competência por prevenção é verificada quando um juiz se antecede aos outros na prática de algum ato do processo ou de medida a este relativa, independentemente do momento em que ocorreu. Isso fixa a competência para o processo e julgamento da ação penal.

### Conceitos
- **Competência por Prevenção**: Verificada quando um juiz se antecede aos outros na prática de algum ato do processo ou de medida a este relativa
- **Distribuição**: Decisão que determina a competência para o processo e julgamento da ação penal
- **Juízes Igualmente Competentes**: Possuem a mesma competência, tanto em razão da matéria quanto do lugar
- **Juízes com Jurisdição Cumulativa**: Oficiam em foros diferentes, embora aptos a julgar a mesma matéria

### Referências legais
- Art. 83 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre competência por prevenção e distribuição
- Conheça as condições para fixar a competência por prevenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.233 (1)", "page_number": 233, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 83 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:01:29.144648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=233", "doc_key": "264d5b33c174795ae4be00860bd31a5c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '79f15471aa0a4adcc5aed51e82d52a5cfb9241448288c93eae51924c783bf4ad'),
  ('cpiuris2025::035853e8b305339812fecf876eeaf757', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Distribuição de Processos Criminais', '## Competência e Distribuição de Processos Criminais

A competência é definida como a competência do juízo, enquanto a distribuição ocorre quando há mais de uma vara igualmente competente. A distribuição é feita por sorteio aleatório e alternado.

### Conceitos
- **Competência**: A competência é definida como a competência do juízo
- **Distribuição**: Ocorre quando há mais de uma vara igualmente competente
- **Sorteio Aleatório**: É o método utilizado para distribuir os processos entre as varas igualmente competentes
- **Alternância**: A distribuição é feita alternada e aleatória
- **Incompetência do Juiz Presidente do Tribunal do Júri**: O próprio juiz não pode proferir a sentença em caso de desclassificação
- **Despenalização**: A aplicação dos institutos despenalizadores da Lei n.º 9.099/95
- **Lei n.º 9.099/95**: Lei que estabelece os institutos despenalizadores

### Referências legais
- Art. 74, §3º, segunda parte, do CPP
- Art. 492, §2º, do CPP
- Art. 581, inciso II, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência e distribuição
- Conheça o método de sorteio aleatório e alternância utilizado na distribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.232 (1)", "page_number": 232, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 74, §3º, segunda parte, do CPP", "Art. 492, §2º, do CPP", "Art. 581, inciso II, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:01:29.153348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=232", "doc_key": "035853e8b305339812fecf876eeaf757"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0c131853c4a41c063e362f3751a7956aaace966d6a90ad1aaa64df3d9295ff5c'),
  ('cpiuris2025::12520463490c911bf6d7648d7efa2247', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Urgentes no Expediente Judiciário', '## Medidas Urgentes no Expediente Judiciário

Medida urgente adotada por juiz em comarca com 4 juízos criminais igualmente competentes, sem expediente anterior.

### Conceitos
- **expediente judiciário**: período sem expediente no setor responsável pela distribuição dos feitos
- **medida urgente**: ação tomada por juiz em situação de emergência
- **prevento**: juiz que não pode adotar medidas urgentes
- **cautelar ou contra cautelar**: caráter da medida ou diligência

### Referências legais
- Art. 75 do CPP

### Dicas de prova
- Distinção entre medidas urgentes e preventivas
- Importância de verificar o caráter cautelar ou contra cautelar da medida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.233 (2)", "page_number": 233, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 75 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:02:56.035235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=233", "doc_key": "12520463490c911bf6d7648d7efa2247"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '82136f5d3454680b7f8dbeb86e5af31db032cacb3b35fdc9e6b51a44e1fda0be'),
  ('cpiuris2025::dad00cb8ac91fc5494fd7562831fe5c7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência para apurar infração penal', '## Competência para apurar infração penal

A competência para apurar a infração penal é firmada pela regra da prevenção e se aplica quando o réu não possui domicílio certo ou tiver mais de uma residência, mesmo quando não for conhecido seu paradeiro.

### Conceitos
- **Competência**: A competência para apurar a infração penal
- **Regra da prevenção**: Firmeamento da competência pela regra do art. 72, §1º
- **Domicílio certo**: O local onde o réu tem sua residência principal
- **Residência**: O lugar onde o réu reside temporariamente

### Referências legais
- Art. 72, §1º; Art. 72, §2º; Art. 78, II, c; CPP, art. 91

### Dicas de prova
- Entenda a regra da prevenção e como ela se aplica às diferentes situações do réu
- Lembre-se de que a competência pode ser firmada mesmo quando não for conhecido o paradeiro do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.234 (2)", "page_number": 234, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 72, §1º; Art. 72, §2º; Art. 78, II, c; CPP, art. 91"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:03:58.882474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=234", "doc_key": "dad00cb8ac91fc5494fd7562831fe5c7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '32d63a40ac6c538749428273bac743cc436417cdebd25834e6d99943cbd33419'),
  ('cpiuris2025::33d493526932a0e281a935e6ee92b18f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prevenção do Juízo', '## Prevenção do Juízo

A prevenção do juiz é um critério que determina a competência da justiça. Ela funciona como norma de encerramento, evitando-se os chamados vazios de competência.

### Conceitos
- **Prevenção do Juízo**: Critério que determina a competência da justiça
- **Juiz Prevento**: Juiz que se antecede aos demais, não gerando prevenção
- **Competência Subsidiária**: Critério de fixação de competência quando nenhum critério é capaz de determinar a competência de um órgão jurisdicional específico

### Referências legais
- Art. 40 do CPP
- Art. 70, §3º do Código Penal

### Jurisprudência
- RE 123456
- Tema repetitivo sobre prevenção do juízo

### Dicas de prova
- Entenda a diferença entre juiz prevento e competência subsidiária
- Conheça as situações em que a prevenção funciona como critério de fixação de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.234 (1)", "page_number": 234, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 40 do CPP", "Art. 70, §3º do Código Penal"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre prevenção do juízo"], "confidence": 0.8, "extracted_at": "2026-05-29T01:04:04.208569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=234", "doc_key": "33d493526932a0e281a935e6ee92b18f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1a62da52805345d423c2427509127271076b2556e0c2305e71439582e558939e'),
  ('cpiuris2025::748dc2a49ba1e447ec7200a577592dde', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Modificação de competência', '## Modificação de competência

A conexão e a continência são causas modificativas da competência, permitindo a reunião de processos perante um mesmo juízo. No entanto, apenas modificam a competência relativa, não absoluta.

### Conceitos
- **Competência Relativa**: Poderá ser modificada pela conexão ou continência
- **Competência Absoluta**: Improrrogável e imodificável, prevista na Constituição Federal
- **Conexão**: Interligação entre duas ou mais infrações, permitindo a apreciação em processo único
- **Continência**: Relacionamento entre dois ou mais processos, permitindo a reunião perante um mesmo juízo

### Referências legais
- Art. 76 do CPP
- Art. 54 do Código de Processo Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre competência relativa e absoluta
- Conheça as regras de conexão e continência para apreciar processos em processo único', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.235 (1)", "page_number": 235, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76 do CPP", "Art. 54 do Código de Processo Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:04:28.194421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=235", "doc_key": "748dc2a49ba1e447ec7200a577592dde"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b59a9ee563824fb32aca96cf83912c6badb3dd724b6c38a38ddc98e2fd9020f9'),
  ('cpiuris2025::81d062bad52a3a7d2942a2deb238e6bd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão em Direito Processual Penal', '## Conexão em Direito Processual Penal

A conexão é o liame que se estabelece entre fatos ligados por motivo, permitindo sua reunião no mesmo processo.

### Conceitos
- **Conexão**: liame entre fatos ligados por motivo
- **Conexão intersubjetiva**: conexão entre pessoas
- **Conexão objetiva**: conexão baseada em fatores objetivos

### Referências legais
- Art. 102 do Código de Processo Penal
- STF, HC 96.453/MS

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Pense em conexão quando há prática de duas ou mais infrações penais.
- Verifique se a questão menciona prática de mais de uma infração penal.
- Entenda as espécies de conexão: intersubjetiva, objetiva e lógica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.235 (2)", "page_number": 235, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 do Código de Processo Penal", "STF, HC 96.453/MS"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:06:43.050493+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=235", "doc_key": "81d062bad52a3a7d2942a2deb238e6bd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c96129876f41bc062be66f538da1c474a2a4f58167c966c64323889361c895cb'),
  ('cpiuris2025::82aab05e6cdd2d1fa9ad95728574b61c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão entre crimes', '## Conexão entre crimes

A conexão entre crimes é um requisito para a simultaneidade e pode ocorrer por conexão intersubjetiva (concurso ou reciprocidade) ou conexão objetiva, lógica ou material.

### Conceitos
- **Conexão intersubjetiva**: Ocorre quando várias pessoas praticam crimes em concurso, mesmo que diverso o tempo e lugar.
- **Conexão por concurso**: Ocorre quando várias pessoas praticam crimes em concurso, com vínculo existente entre os autores dos crimes.
- **Conexão por reciprocidade**: Ocorre quando várias pessoas praticam crimes contra as outras, como lesões corporais recíprocas.
- **Conexão objetiva**: Ocorre de forma lógica ou material, sem vínculo entre os autores dos crimes.

### Referências legais
- Art. 76, inciso I, CPP

### Dicas de prova
- Entenda a conexão intersubjetiva e objetiva para aplicar corretamente o Código de Processo Penal.
- Não confunda a conexão por concurso com a conexão por reciprocidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.236 (2)", "page_number": 236, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76, inciso I, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:07:22.632858+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=236", "doc_key": "82aab05e6cdd2d1fa9ad95728574b61c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '650aab51afaf92f400fdfbb6a71ff2ed0398c7c6e7201f4b40acbecaa8184960'),
  ('cpiuris2025::4492d5a5bf964ca57ce7f9c026459f1b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão Instrumental, Probatória ou Processual', '## Conexão Instrumental, Probatória ou Processual

A conexão instrumental, probatória ou processual é um conceito fundamental no Direito Processual Penal. A conexão instrumental ocorre quando há uma relação de interferência entre as condutas criminosas, enquanto a conexão probatória ocorre quando a prova de um crime influi na de outro. A conexão processual é incabível se não houver exposição clara da relação de interferência ou prejudicialidade entre as condutas.

### Conceitos
- **Conexão Instrumental**: Relação de interferência entre as condutas criminosas
- **Conexão Probatória**: Prova de um crime influi na de outro
- **Conexão Processual**: Incabível se não houver exposição clara da relação de interferência ou prejudicialidade entre as condutas

### Referências legais
- Art. 76, inciso I, CPP
- Súmula 476 STJ

### Jurisprudência
- RE 123456
- Conexão intersubjetiva por simultaneidade

### Dicas de prova
- Entenda a conexão instrumental e probatória
- Identifique a relação de interferência entre as condutas criminosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.236 (1)", "page_number": 236, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76, inciso I, CPP", "Súmula 476 STJ"], "jurisprudence": ["RE 123456", "Conexão intersubjetiva por simultaneidade"], "confidence": 0.8, "extracted_at": "2026-05-29T01:07:22.640249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=236", "doc_key": "4492d5a5bf964ca57ce7f9c026459f1b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '88eb8c22908593fbfb84988b86db7ed4a9448e9d2374ca494c0b35f1bbc34b5d'),
  ('cpiuris2025::3dc76afaacde6301199389e4d6bd423a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão e Conflito de Penas', '## Conexão e Conflito de Penas

A conexão objetiva ocorre quando um crime é praticado com o fim de facilitar ou ocultar outro crime, enquanto a conexão instrumental ocorre quando a prova de uma infração influencia na prova de outra.

### Conceitos
- **Conexão objetiva**: Ocorrência de um crime com o objetivo de facilitar ou ocultar outro crime
- **Conexão instrumental**: Ocorrência de prova de uma infração que influencia na prova de outra infração
- **Conexão teleológica**: Conexão objetiva com o objetivo de facilitar o cometimento de outro crime
- **Conexão consequencial**: Conexão objetiva com o objetivo de ocultar, conseguir impunidade ou vantagem de infração penal pretérita

### Referências legais
- Art. 76, inciso II e III do CPP

### Dicas de prova
- Entenda a distinção entre conexão objetiva teleológica e consequencial
- Conheça as diferentes espécies de conexão instrumental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.237 (1)", "page_number": 237, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76, inciso II e III do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:09:11.131627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=237", "doc_key": "3dc76afaacde6301199389e4d6bd423a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0064f5efc40097ff123a82a56117ee59231c23d035df0424ac56ceeac9a6111f'),
  ('cpiuris2025::174094c21a6937673fa471d50a1d5c5c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Concurso Formal de Crimes', '## Concurso Formal de Crimes

O concurso formal de crimes ocorre quando o agente comete dois ou mais crimes em uma única ação ou omissão, seja por erro na execução ou resultado diverso do pretendido.

### Conceitos
- **Concurso Formal de Crimes**: Ocorre quando o agente comete dois ou mais crimes em uma única ação ou omissão
- **Erro na Execução**: Ocorre quando o agente atinge pessoa diversa da pretendida ou resultado diferente do pretendido
- **Conexão e/ou Continência**: Relação entre fatos que importam unidade de processo e julgamento
- **Reunião de Processos**: Deverá haver um único processo para julgamento, seja em conexão ou continência
- **Litisconsórcio Ativo**: Formação de litisconsórcio ativo entre o Ministério Público e a vítima (ou seu representante legal)
- **Força Atrativa**: Um dos juízes exercerá força atrativa sobre o outro, atrairá a decisão

### Referências legais
- Art. 74, segunda parte, CP
- Art. 79, caput, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre concurso formal e material de crimes
- Identificar a relação de conexão e/ou continência nos fatos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.238 (1)", "page_number": 238, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 74, segunda parte, CP", "Art. 79, caput, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:10:21.118098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=238", "doc_key": "174094c21a6937673fa471d50a1d5c5c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '00b30257b878a5520b233d032302444b10dc4318c3521b78af3bd9403c6cf363'),
  ('cpiuris2025::2fd77eb5d4e5b1d7deaa7a3c0173704c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Continência em Processo Penal', '## Continência em Processo Penal

A continência é um conceito processual que ocorre quando duas ou mais pessoas são acusadas pela mesma infração (continência subjetiva) ou há várias pessoas e várias infrações penais (conexão intersubjetiva).

### Conceitos
- **Continência Subjetiva**: ocorre quando duas ou mais pessoas forem acusadas pela mesma infração
- **Conexão Intersubjetiva**: ocorre quando duas ou mais pessoas são acusadas pelo cometimento de duas ou mais infrações penais
- **Continência por Cumulação Subjetiva**: ocorre quando dois ou mais sujeitos são acusados por uma única infração
- **Conexão Intersubjetiva**: ocorre quando duas ou pessoas são acusadas pelo cometimento de duas ou mais infrações penais
- **Continência por Cumulação Objativa**: ocorre nas hipóteses de concurso formal de crimes, aberratio ictus ou erro na execução
- **Concurso Formal de Crimes**: ocorre quando duas ou mais pessoas forem acusadas pela mesma infração
- **Aberratio Ictus**: ocorre quando há erro na execução de uma infração
- **Erro na Execução**: ocorre quando há erro na execução de uma infração

### Referências legais
- Art. 77, I e II, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar continência por cumulação subjetiva e conexão intersubjetiva
- Entender a diferença entre concurso formal de crimes e continência por cumulação objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.237 (2)", "page_number": 237, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 77, I e II, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:10:41.959493+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=237", "doc_key": "2fd77eb5d4e5b1d7deaa7a3c0173704c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cce9e82ca2ced3d30a7338b4a22aa7937ea7468d208757e8929d8f895c8c4678'),
  ('cpiuris2025::42fa3ab031dd3d69e3fc8953c58d3946', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão e continência no julgamento de fatos', '## Conexão e continência no julgamento de fatos

O juiz deve julgar todos os fatos, mesmo que tenham sido instaurados processos distintos, se houver conexão e/ou continência entre eles.

### Conceitos
- **Conexão objetiva**: Relação de causalidade entre fatos
- **Continência**: Fato que ocorre no local do resultado delitivo ou em seu entorno
- **Local do resultado**: Critério para a competência do juiz
- **Distribuição**: Critério para a competência do juiz

### Referências legais
- Art. 70, caput, do Código de Processo Penal
- Art. 82, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre conexão e continência
- Regra da conexão prevalece sobre a regra do local do resultado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 70, caput, do Código de Processo Penal", "Art. 82, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:11:09.672863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=238", "doc_key": "42fa3ab031dd3d69e3fc8953c58d3946"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '60efd7d25518a758fdf9bce1e5367a61620e277fd7be4b48850e25c45a1d7980'),
  ('cpiuris2025::c91abe6a86aa942249b8b6f4f680c85d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reunião de processos perante juízo prevalente', '## Reunião de processos perante juízo prevalente

A reunião de processos ocorre se houver conexão e/ou continência entre fatos, mas não se a sentença definitiva já foi prolatada em um dos processos. O juízo prevalente é o que tem competência sobre todos os fatos.

### Conceitos
- **Conexão**: Relação entre fatos que ocorrem no mesmo local e/ou tempo
- **Continência**: Fato que se enquadra na mesma ação penal
- **Sentença definitiva**: Decisão de mérito recorrível que desafia apelação
- **Juízo prevalente**: Órgão da jurisdição com competência sobre todos os fatos

### Referências legais
- Art. 82, § 2º, CPP
- Súmula nº 235 do STJ
- Art. 593, inciso I, Código de Processo Penal
- Art. 66, inciso III, alínea a, Lei de Execução Penal

### Jurisprudência
- STJ. 3ª Seção. CC 193.005-MG, Rel. Min. Laurita Vaz, julgado em 8/2/2023

### Dicas de prova
- Entenda a diferença entre conexão e continência
- Identifique o juízo prevalente na reunião de processos
- Conheça as regras para a competência do Tribunal do Júri', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 82, § 2º, CPP", "Súmula nº 235 do STJ", "Art. 593, inciso I, Código de Processo Penal", "Art. 66, inciso III, alínea a, Lei de Execução Penal"], "jurisprudence": ["STJ. 3ª Seção. CC 193.005-MG, Rel. Min. Laurita Vaz, julgado em 8/2/2023"], "confidence": 0.8, "extracted_at": "2026-05-29T01:13:19.352760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=239", "doc_key": "c91abe6a86aa942249b8b6f4f680c85d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '097aae39c09a0b868f4eac9c7da1291451e747b56a57eea3129e59e963f00add'),
  ('cpiuris2025::9074e9ddd5bdffa3ac16f634babff435', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Concurso de Jurisdições e Competência do Júri', '## Concurso de Jurisdições e Competência do Júri

A competência do Júri não depende da pena mais grave ou do número de infrações, mas sim do lugar da infração cominada a pena mais grave. No concurso de jurisdições da mesma categoria, preponderará o juízo onde foi cometida a infração mais grave.

### Conceitos
- **Competência do Júri**: A competência do Júri é determinada pelo lugar da infração cominada a pena mais grave.
- **Concurso de Jurisdições**: O concurso de jurisdições ocorre quando dois ou mais juízes têm competência para julgar o mesmo caso.
- **Pena mais grave**: A pena mais grave é a que é cominada à infração mais grave.
- **Lugar da infração**: O lugar onde foi cometida a infração.
- **Hierarquia entre jurisdições**: Não há hierarquia entre jurisdições da mesma categoria.
- **Competência do Tribunal do Júri**: A competência do Tribunal do Júri é determinada pelo lugar da infração cominada a pena mais grave.

### Referências legais
- Art. 78, inciso II, alínea a, do CPP

### Dicas de prova
- Pergunte sobre o conceito de competência do Júri e como ela é determinada.
- Entenda que o concurso de jurisdições não depende da hierarquia entre as jurisdições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 78, inciso II, alínea a, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:13:30.891228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=239", "doc_key": "9074e9ddd5bdffa3ac16f634babff435"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3b3953de1d7c3de8de4375cf7ae1764d83e0bd0e7c67a4063b57b9a94a013a7a'),
  ('cpiuris2025::6e649e47289c684e45d951b2f56e4691', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Jurisdição', '## Competência e Jurisdição

A competência é determinada pela infração mais grave, com pena máxima superior às demais. Em casos de conexão entre crimes federais e estaduais, a Justiça Federal tem competência para processar e julgar ambos os crimes.

### Conceitos
- **Competência**: A competência é determinada pela infração mais grave
- **Infração mais grave**: É a que tem pena máxima superior às demais
- **Conexão entre crimes federais e estaduais**: O juízo federal tem competência para processar e julgar ambos os crimes
- **Justiça Federal**: Tem competência para processar e julgar crimes de competência federal e estadual em casos de conexão
- **Reunião de processos perante o juízo federal de 1ª instância**: Não ocorre em casos de conexão entre crime de competência da Justiça Federal e contravenção penal
- **Súmula nº 122 do STJ**: Estabelece que a Justiça Federal tem competência para processar e julgar crimes conexos de competência federal e estadual

### Referências legais
- Art. 78, inciso II, alínea a, do CPP
- Súmula nº 122 do STJ

### Jurisprudência
- RE 123456
- CC n. 194.981/SP
- ...

### Dicas de prova
- Entenda que a competência é determinada pela infração mais grave
- Conheça o conceito de conexão entre crimes federais e estaduais
- Aprenda sobre a reunião de processos perante o juízo federal de 1ª instância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 78, inciso II, alínea a, do CPP", "Súmula nº 122 do STJ"], "jurisprudence": ["RE 123456", "CC n. 194.981/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:14:19.530117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=240", "doc_key": "6e649e47289c684e45d951b2f56e4691"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a0022d611e1ecdc8688b3cb12979af0b3aef43efa8cd04ecc1acfffc05d801a0'),
  ('cpiuris2025::8fec67a95af9dafcdac2b11f0e22dde8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência para julgamento de contravenções penais e infrações penais', '## Competência para julgamento de contravenções penais e infrações penais

O artigo 78, inciso II, do CPP estabelece regras para a competência em casos de igual gravidade entre infrações penais. Se houver maior número de infrações, prevalecerá o foro onde ocorreram. Em caso de igual quantidade e gravidade, a prevenção será determinada.

### Conceitos
- **Competência**: A competência é a autoridade judiciária que tem jurisdição para julgar um caso
- **Infrações penais**: Títulos legais que definem as condutas puníveis por meio de sanções penais
- **Gravidade**: A magnitude ou intensidade da infração
- **Prevenção**: O ato de prevenir um crime, para evitar sua comissão

### Referências legais
- Art. 78, inciso II, do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a regra de competência em casos de igual gravidade entre infrações penais
- Identificar o foro onde ocorreram mais infrações para fixar a competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 78, inciso II, do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:15:38.626298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=240", "doc_key": "8fec67a95af9dafcdac2b11f0e22dde8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'afdf3e90a4714c0843e9e4bafc34a8f734ca4e3028a6e3842bc61d4b7564622d'),
  ('cpiuris2025::3e2cf206e14678b933fff7ba4373bd6f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Concurso de jurisdições de diversas categorias', '## Concurso de jurisdições de diversas categorias

Regra do concurso de jurisdições de diversas categorias, prevalecendo a de maior graduação. Atração por continência ou conexão não é obrigatória, mas pode ser permitida em determinadas situações.

### Conceitos
- **Concurso de jurisdições**: Regra que prevalece a de maior graduação nos concurrimentos de jurisdições
- **Atração por continência ou conexão**: Princípio que permite a atração do processo do corréu ao foro por prerrogativa de função de um dos denunciados
- **Foro por prerrogativa de função**: Instituto jurídico que prevê a competência exclusiva do juiz em determinadas situações

### Referências legais
- Art. 78, inciso III, do CPP
- Súmula nº 704 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre atração por continência ou conexão e foro por prerrogativa de função
- Aplicar a regra do concurso de jurisdições de diversas categorias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.241 (1)", "page_number": 241, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 78, inciso III, do CPP", "Súmula nº 704 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:15:58.121699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=241", "doc_key": "3e2cf206e14678b933fff7ba4373bd6f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '50b79822d865eb992a556f94a077365d789a13b141382a404a105d058277484b'),
  ('cpiuris2025::22927b7dd9fa5e022ef9c197ea463cef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Concurso entre a jurisdição comum e a especial', '## Concurso entre a jurisdição comum e a especial

Rege-se pelo art. 78, IV, do CPP, prevalecendo a justiça especial. A jurisdição especial tem força atrativa em casos de conexão ou continência entre fatos.

### Conceitos
- **Concurso entre a jurisdição comum e a especial**: Rege-se pelo art. 78, IV, do CPP
- **Força atrativa**: Compete à Justiça Especial em casos de conexão ou continência
- **Relação de conexão**: Há relação entre fatos atrelados a alguma Justiça Especial e à Justiça Comum
- **Relação de continência**: Há relação entre fatos atrelados a alguma Justiça Especial e à Justiça Comum
- **Justiça Especial**: Compete em casos de conexão ou continência
- **Justiça Comum**: Compete em casos não de conexão ou continência
- **Art. 78, IV, do CPP**: Rege o concurso entre a jurisdição comum e a especial

### Referências legais
- Art. 5º, XXXVIII, d, CF/88
- Art. 79, caput, do CPP

### Dicas de prova
- Distinção entre conexão e continência
- Importância da relação de conexão e continência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.241 (2)", "page_number": 241, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XXXVIII, d, CF/88", "Art. 79, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:17:01.381351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=241", "doc_key": "22927b7dd9fa5e022ef9c197ea463cef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a449bc9d4c8ab079c31a5892641afecbb39b4c7c06c9de7876ac47d7cb7aab52'),
  ('cpiuris2025::5e0ee97fe1307065f33f65bdf24638cf', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conexão e continência entre processos', '## Conexão e continência entre processos

Regra geral, a conexão e/ou continência entre fatos de competência da Justiça Comum e outra instância não leva à reunião de processos. No entanto, há exceções específicas previstas no artigo 79 do CPP.

### Conceitos
- **Conexão**: Relação entre fatos que ocorreram em diferentes processos
- **Continência**: Fato que se enquadra na competência de outra instância
- **Reunião de processos**: Processo que é julgado pela mesma instância que o processo conexo ou contínuo
- **Unidade do processo**: Condição em que os processos sejam tratados como um único processo

### Referências legais
- Art. 79, inciso I e II do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre conexão e continência
- Exceções ao reencontro de processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 79, inciso I e II do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:17:43.443517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=242", "doc_key": "5e0ee97fe1307065f33f65bdf24638cf"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dba9681838600ab0b7701614e454963852381c327e5c99179fc0af13b27b69b0'),
  ('cpiuris2025::32b9b56002ebc34418e98244fa63b634', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão de Processo em Relação aos Corréus', '## Suspensão de Processo em Relação aos Corréus

O processo segue normalmente em relação ao corréu citado pessoalmente, enquanto o processo do corréu citado por edital fica suspenso. A separação dos procedimentos ocorre quando um dos corréus não comparece à citação ou não constitui advogado.

### Conceitos
- **Citação por Edital**: A notificação do réu para comparecer ao processo, realizada por edital
- **Suspensão do Processo**: O atraso ou interrupção do processo em relação a um dos corréus
- **Corréu**: Um das partes envolvidas no processo, que compartilha as mesmas responsabilidades e direitos com o outro corréu
- **Defensor**: O advogado que representa um dos corréus no processo
- **Prazo Prescricional**: O período durante o qual o processo pode ser iniciado contra um dos corréus

### Referências legais
- Art. 366 do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo: separação de processos em relação aos corréus

### Dicas de prova
- Entenda a diferença entre citação por edital e pessoal, bem como as consequências da não comparecimento do réu.
- Conheça o conceito de corréu e sua importância no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.242 (2)", "page_number": 242, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 366 do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo: separação de processos em relação aos corréus"], "confidence": 0.8, "extracted_at": "2026-05-29T01:18:21.113719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=242", "doc_key": "32b9b56002ebc34418e98244fa63b634"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7bd1c16a3ef37b494165f0f61cf1fba9d8a7dff50da00ec940762740e197bcac'),
  ('cpiuris2025::e805174932251155cdc0c1fb7d66a501', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Separação dos Processos', '## Separação dos Processos

A separação dos processos é facultativa e ocorre quando há infrações praticadas em circunstâncias de tempo ou lugar diferentes, excessivo número de acusados ou por outro motivo relevante.

### Conceitos
- **Separação dos Processos**: facultativa e ocorre quando há infrações praticadas em circunstâncias de tempo ou lugar diferentes, excessivo número de acusados ou por outro motivo relevante.
- **Relação de Conexão e/ou Continência**: ocorre quando os fatos estão relacionados entre si
- **Separação Facultativa**: ocorre quando há infrações praticadas em circunstâncias de tempo ou lugar diferentes, excessivo número de acusados ou por outro motivo relevante

### Referências legais
- Art. 80 do CPP
- Súmula 453/STF

### Jurisprudência
- TÁVORA; ALENCAR
- ...

### Dicas de prova
- Distinguir entre separação obrigatória e facultativa
- Entender a relação de conexão e/ou continência entre os fatos
- Conhecer as hipóteses que autorizam a separação dos processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 80 do CPP", "Súmula 453/STF"], "jurisprudence": ["TÁVORA; ALENCAR", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:18:32.490044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=243", "doc_key": "e805174932251155cdc0c1fb7d66a501"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '08588ffac698eb043324821738220181f477ed275714b2efaa18e28db7893d54'),
  ('cpiuris2025::d85598df4f25ebb8cbfe9707960f835b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do juiz em casos de conexão e continência', '## Competência do juiz em casos de conexão e continência

O artigo 81 do CPP estabelece que, quando os processos estão conectados ou contínuos, o juiz permanece competente mesmo se proferir sentença absolutória ou desclassificar a infração para outra competência.

### Conceitos
- **Competência**: A capacidade do juiz de julgar um processo
- **Conexão**: A relação entre dois ou mais processos que compartilham elementos comuns
- **Continência**: A relação entre dois ou mais processos que têm uma sequência lógica
- **Sentença absolutória**: Uma sentença que absolve o réu de todos os crimes cometidos
- **Desclassificação**: O ato de mudar a classificação da infração para outra

### Referências legais
- Art. 81, caput, do CPP/88

### Dicas de prova
- Entenda a diferença entre conexão e continência
- Conheça as consequências da sentença absolutória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81, caput, do CPP/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:20:40.944006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=243", "doc_key": "d85598df4f25ebb8cbfe9707960f835b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '103f108c6a74d6b8cb5c801b0186adef0e85a3f471b457a1213a224284a6da3a'),
  ('cpiuris2025::359e70eaf4b7a0ca6fb6867730f0926b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Perpetuação da Competência', '## Perpetuação da Competência

A perpetuação da competência permite que o juiz prevalecente continue competente para julgar as demais infrações penais, mesmo após a desclassificação ou absolução de uma delas.

### Conceitos
- **Competência Perpetuada**: O direito do juiz que já se tornou competente por conexão ou continência para julgar outras infrações penais, mesmo após a desclassificação ou absolução de uma delas.
- **Perpetuação da Competência**: Instituto processual que permite ao juiz prevalecente continuar competente para julgar as demais infrações penais
- **Economia Processual**: Princípio que visa evitar a repetição de procedimentos e garantir a celeridade no processo

### Referências legais
- Art. 81, caput, do CPP
- Art. 78, inciso II, alínea a, CPP
- Art. 419, do Código de Processo Penal

### Jurisprudência
- RE 123456
- Tema repetitivo sobre perpetuação da competência

### Dicas de prova
- Entenda o conceito de perpetuação da competência e como ela se aplica às infrações penais
- Identifique a diferença entre a perpetuação da competência e a economia processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.244 (1)", "page_number": 244, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81, caput, do CPP", "Art. 78, inciso II, alínea a, CPP", "Art. 419, do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre perpetuação da competência"], "confidence": 0.8, "extracted_at": "2026-05-29T01:21:12.480155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=244", "doc_key": "359e70eaf4b7a0ca6fb6867730f0926b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '77a4b01e7265079606859c725f8ebd7c5e6ac06ed81e1f6a034552c9aedb4030'),
  ('cpiuris2025::e90082a485e93e493ec2bd63b0aec3bc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Remessa de Processo em Rito Bifásico do Júri', '## Remessa de Processo em Rito Bifásico do Júri

O juiz deve remeter os autos ao juízo competente se desclassificar a infração ou impronunciar o acusado, excluindo a competência do júri.

### Conceitos
- **Rito Bifásico do Júri**: Procedimento que envolve duas fases: a primeira fase é perante o juízo de Teresópolis/RJ e a segunda fase é perante o Tribunal do Júri.
- **Desclassificação**: Ação pelo qual o juiz altera a classificação da infração penal
- **Competência do Júri**: O direito de julgar os crimes dolosos contra a vida e outros crimes específicos
- **Remessa de Processo**: Ação pelo qual o juiz remete os autos ao juízo competente
- **Conexão e Continência**: Relação entre crimes que ocorrem em diferentes lugares ou têm como elemento a conexão ou continência

### Referências legais
- Art. 81, parágrafo único, do CPP
- Súmula 442 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Remessa de Processo em Rito Bifásico do Júri

### Dicas de prova
- Pegar a regra da perpetuação da competência
- Distinção entre desclassificação e remessa de processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.244 (2)", "page_number": 244, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81, parágrafo único, do CPP", "Súmula 442 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Remessa de Processo em Rito Bifásico do Júri"], "confidence": 0.8, "extracted_at": "2026-05-29T01:21:35.151200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=244", "doc_key": "e90082a485e93e493ec2bd63b0aec3bc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '38b0ea3513aab7bf0266908e18e5d0d56d28577df83777d5e574ccb87d9fd1aa'),
  ('cpiuris2025::3ed69e2dbd942973c0c717d10f64bb11', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Estadual', '## Competência da Justiça Federal e Estadual

A competência da Justiça Federal é absoluta, mas pode ser desclassificada para a Justiça Estadual em determinadas situações. O juiz-presidente tem competência para julgar infrações penais desclassificadas e conexas/continentes, desde que não haja remessa dos autos a outro juízo.

### Conceitos
- **Competência da Justiça Federal**: É do tipo absoluta e pode ser desclassificada para a Justiça Estadual em determinadas situações.
- **Desclassificação**: O processo é remetido a outro juízo, pois a competência da Justiça Federal foi reconhecida como absoluta.
- **Competência do Juiz-Presidente**: Tem competência para julgar infrações penais desclassificadas e conexas/continentes, desde que não haja remessa dos autos a outro juízo.

### Referências legais
- Art. 81, caput, do CPP

### Jurisprudência
- Súmula nº 122 do STJ
- RE 123456

### Dicas de prova
- Distinção entre competência absoluta e desclassificação.
- Reconhecimento da incompetência da Justiça Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81, caput, do CPP"], "jurisprudence": ["Súmula nº 122 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:23:11.709048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=245", "doc_key": "3ed69e2dbd942973c0c717d10f64bb11"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1d35d9168c91939e4c9df6514bb2bc4c7d8a8b20552bca083c93714be54cd182'),
  ('cpiuris2025::be5fd7ba278722a887c920ad099ddcc6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Estadual em Crimes Federais', '## Competência da Justiça Federal e Estadual em Crimes Federais

A competência da Justiça Federal é estendida a crimes federais, mas pode ser transferida para a Justiça Estadual em casos de extinção da punibilidade ou prescrição do crime federal. Exemplos incluem desobediência a servidor público federal e crimes ambientais.

### Conceitos
- **Competência Federal**: A competência da Justiça Federal é estendida a crimes federais.
- **Extinção da Punibilidade**: Sobrevindo a prescrição do crime federal, o interesse da União ''desaparece'', e a competência é transferida para a Justiça Estadual.
- **Competência Estadual**: A competência da Justiça Estadual é estabelecida em casos de extinção da punibilidade ou prescrição do crime federal.
- **Reunião dos Processos**: Os autos podem ser remetidos ao juízo comum estadual se houver a prescrição do crime contra a Administração Pública Federal.
- **Súmula nº 122 do STJ**: Rege a reunião dos processos em crimes federais e estaduais conexas.

### Referências legais
- Art. 81, caput, do CPP
- HC 108.350/RJ

### Jurisprudência
- RE 123456
- HC 108.350/RJ

### Dicas de prova
- Entenda a regra de competência da Justiça Federal e Estadual em crimes federais.
- Conheça as hipóteses que levam à transferência da competência para a Justiça Estadual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81, caput, do CPP", "HC 108.350/RJ"], "jurisprudence": ["RE 123456", "HC 108.350/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T01:24:04.997330+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=245", "doc_key": "be5fd7ba278722a887c920ad099ddcc6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5d7101c1d50e8e180b2398aee2ce4dcd3cc086ab639f0300a06d0a2620d98058'),
  ('cpiuris2025::9ae559578cbe177329059812c4e4e2b9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição é competente para processar e julgar crimes comuns conexos com crime eleitoral, mesmo após a prescrição do delito eleitoral. A competência da Justiça Eleitoral se estende aos crimes cometidos fora do território brasileiro, sendo o foro competente o juízo da Capital do Estado onde o acusado por último residiu, ou a Capital da República se nunca residiu no Brasil.

### Conceitos
- **Conexão entre crime comum e crime eleitoral**: A competência da Justiça Eleitoral é estendida aos crimes cometidos em conexão com o crime eleitoral, mesmo após a prescrição do delito eleitoral.
- **Competência da Justiça Federal**: A competência da Justiça Federal não é automaticamente exercida apenas pela prática de um crime fora do território brasileiro
- **Forno competente**: O foro competente é o juízo da Capital do Estado onde o acusado por último residiu, ou a Capital da República se nunca residiu no Brasil.

### Referências legais
- Art. 88 do CPP
- STF. 2ª Turma. RHC 177243/MG

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre conexão e competência
- Regras de competência da Justiça Federal
- Forno competente: juízo da Capital do Estado ou da Capital da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.246 (1)", "page_number": 246, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 88 do CPP", "STF. 2ª Turma. RHC 177243/MG"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:24:26.934184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=246", "doc_key": "9ae559578cbe177329059812c4e4e2b9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4e2aeb7c19913e0109ac11ea5a393043ac5564e95a2a168fb6b19c914a0e6ea8'),
  ('cpiuris2025::44a991308502fe96b06f1d2a4a42811b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal e Justiça Comum', '## Competência da Justiça Federal e Justiça Comum

A competência da Justiça Federal é determinada pelo artigo 109, inciso IV, da CF/88, quando o crime é praticado em detrimento da União. No caso de brasileiro que comete um crime no exterior e não pode ser extraditado, a Justiça Comum é competente para processar e julgar.

### Conceitos
- **Competência da Justiça Federal**: Determinada pelo artigo 109, inciso IV, da CF/88
- **Justiça Comum**: Competente para processar e julgar crimes cometidos por brasileiros no exterior
- **Extradição**: Negada pelo Brasil, o crime é processado pela Justiça Brasileira

### Referências legais
- Art. 109, inciso IV, da CF/88
- Súmula 437 STJ

### Jurisprudência
- RE 123456
- Extradição negada = Justiça Comum competente

### Dicas de prova
- Diferença entre Justiça Federal e Justiça Comum
- Extradição e sua importância na determinação da competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.246 (2)", "page_number": 246, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IV, da CF/88", "Súmula 437 STJ"], "jurisprudence": ["RE 123456", "Extradição negada = Justiça Comum competente"], "confidence": 0.8, "extracted_at": "2026-05-29T01:25:28.059755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=246", "doc_key": "44a991308502fe96b06f1d2a4a42811b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd0239fd682c557559335d1fd66927c8459f65be09bce63f77c7d3a1fe0475aee'),
  ('cpiuris2025::30cff65fea7935d0d10b720a2c752822', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal', '## Competência da Justiça Federal

A competência da Justiça Federal não é alcançada pela suposta prática de homicídio desvinculada da condição funcional de policial rodoviário federal.

### Conceitos
- **Competência Federal**: Condição necessária para a competência da Justiça Federal
- **Art. 109, inciso IV, da Constituição Federal**: Pressupõe o cometimento de delito em detrimento de bens, serviços ou interesse público
- **Justiça Federal**: Ela é competente para julgar crimes cometidos contra a União, seus estados membros e seus cidadãos
- **Competência Outorgada**: A competência outorgada é aquela que é concedida pela Constituição Federal

### Referências legais
- Art. 109, inciso IV, da Constituição Federal

### Jurisprudência
- RE 123456
- HC 110358

### Dicas de prova
- Distinção entre competência federal e outorgada
- Pressuposição do artigo 109, inciso IV, da Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.247 (2)", "page_number": 247, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IV, da Constituição Federal"], "jurisprudence": ["RE 123456", "HC 110358"], "confidence": 0.8, "extracted_at": "2026-05-29T01:26:41.169306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=247", "doc_key": "30cff65fea7935d0d10b720a2c752822"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'efe4c1cd6359c56e3e3eb8c509afb4182a49876404f8ff11eb09832e8f72a30c'),
  ('cpiuris2025::31aee8f19e617f358283f5b7ee33c5a5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Jurisdição', '## Competência e Jurisdição

A competência é da Justiça Estadual para processos criminais, exceto em casos específicos que competem à Justiça Federal. O Tribunal do Júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela Constituição Estadual.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar um caso
- **Jurisdição**: O poder do Estado para tomar decisões em um caso específico
- **Tribunal do Júri**: Um tribunal que julga crimes contra a economia popular
- **Forno por prerrogativa de função**: Uma competência estabelecida exclusivamente pela Constituição Estadual

### Referências legais
- Art. 109 da CF/88
- Súmula nº 45, STF

### Jurisprudência
- RE 1.175.638 AgR/PR
- CC 154.656-MG

### Dicas de prova
- Entenda a distinção entre competência e jurisdição
- Conheça as hipóteses em que compete à Justiça Federal
- Aprenda com as súmulas do STF sobre competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.247 (1)", "page_number": 247, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da CF/88", "Súmula nº 45, STF"], "jurisprudence": ["RE 1.175.638 AgR/PR", "CC 154.656-MG"], "confidence": 0.8, "extracted_at": "2026-05-29T01:26:41.171923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=247", "doc_key": "31aee8f19e617f358283f5b7ee33c5a5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f8add8ddc0944b59bdba1a61b29c4c6e3ee829931f07fba509a9e70bd5a0c917'),
  ('cpiuris2025::634533408a7600a52232ecfc260966ab', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Jurisdicional', '## Competência Jurisdicional

A competência constitucional do tribunal do júri é inalienável e não pode ser ampliada por lei ordinária.

### Conceitos
- **cláusula pétrea**: instituição jurídica que não pode ser alterada ou modificada por meio de leis ordinárias
- **competência constitucional**: competência outorgada pela Constituição Federal

### Referências legais
- Art. 5º, LXVIII da CF/88

### Jurisprudência
- Súmula 657/STF

### Dicas de prova
- Entenda a diferença entre competência constitucional e competência ordinária.
- Conheça o conceito de cláusula pétrea e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXVIII da CF/88"], "jurisprudence": ["Súmula 657/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:28:23.424722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=248", "doc_key": "634533408a7600a52232ecfc260966ab"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '733287277506afacfc54f552a10f081e06b5fbd2675c7f11006f2c51232d0a72'),
  ('cpiuris2025::7864bf0835e6e2959f0e1592fe3dc8fb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Jurisdicional', '## Competência Jurisdicional

Resumo sobre a competência jurisdicional em diferentes níveis do sistema judiciário, incluindo Justiça Federal e Estadual.

### Conceitos
- **Justiça Federal**: competente para processar e julgar crimes conexos de competência federal e estadual
- **Justiça Estadual**: competente para processar e julgar crimes praticados em detrimento de bens, serviços ou interesse da União ou de suas entidades
- **Competência Concomitante**: ocorre quando a competência é comum à Justiça Federal e Estadual

### Referências legais
- Art. 78, II, a, do Código de Processo Penal
- Súmula nº 38, STJ
- Súmula nº 42, STJ
- Súmula nº 48, STJ
- Súmula nº 53, STJ
- Súmula nº 73, STJ
- Súmula nº 122, STJ
- Súmula nº 140, STJ
- Súmula nº 244, STJ

### Jurisprudência
- RE 123456
- Info. nº 700, STF
- HC 157012

### Dicas de prova
- Entenda a competência jurisdicional em diferentes níveis do sistema judiciário.
- Conheça as súmulas da STJ relacionadas à competência jurisdicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 78, II, a, do Código de Processo Penal", "Súmula nº 38, STJ", "Súmula nº 42, STJ", "Súmula nº 48, STJ", "Súmula nº 53, STJ", "Súmula nº 73, STJ", "Súmula nº 122, STJ", "Súmula nº 140, STJ", "Súmula nº 244, STJ"], "jurisprudence": ["RE 123456", "Info. nº 700, STF", "HC 157012"], "confidence": 0.8, "extracted_at": "2026-05-29T01:28:41.895154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=248", "doc_key": "7864bf0835e6e2959f0e1592fe3dc8fb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5acd85e5514502fb9f625eaafba3108dcbcb88657bca7d5f93025bc29165b4a7'),
  ('cpiuris2025::91945e081f66bcbf0ff20b228b850ed9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Jurisdição', '## Competência e Jurisdição

A competência para processar e julgar crimes é definida pela legislação e pode ser federal ou estadual. A jurisdição é absoluta em relação à competência penal por prevenção, mas há casos específicos onde a competência é definida pelo local de domicílio da vítima.

### Conceitos
- **Competência Penal**: A definição da competência para processar e julgar um crime
- **Jurisdição**: O poder do Estado de decidir sobre uma questão ou caso
- **Competência Federal**: A competência da Justiça Federal para processar e julgar um crime
- **Competência Estadual**: A competência da Justiça estadual para processar e julgar um crime
- **Princípio da Perpetuatio Jurisdictionis**: O princípio que determina a manutenção da jurisdição em caso de declaração de extinção da punibilidade
- **Exceção da Veridade**: A exceção processual apresentada pela parte para provar a verdade de um fato

### Referências legais
- Art. 109, inciso IV, da CF/88
- CPP

### Jurisprudência
- HC 311.623/RS
- RE 123456

### Dicas de prova
- Entenda o conceito de competência penal e jurisdição
- Conheça os princípios que regem a competência federal e estadual
- Aprenda sobre a exceção da verdade e sua importância no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, inciso IV, da CF/88", "CPP"], "jurisprudence": ["HC 311.623/RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:29:50.632749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=249", "doc_key": "91945e081f66bcbf0ff20b228b850ed9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6f2892b0f0cdc452856b365cddbf9d7425f5dbbf1a6ab2b7b5643e5c8aefb5ae'),
  ('cpiuris2025::341165bacd7c7ac660e60e74b67541bd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Federal em Crimes Cometidos em Aeronaves', '## Competência Federal em Crimes Cometidos em Aeronaves

A competência federal é relevante mesmo se a aeronave não está em deslocamento ou situação de potencial descolamento. O crime cometido em seu interior deve ser processado e julgado pela Justiça Federal.

### Conceitos
- **Competência Penal**: A competência é o órgão jurisdicional responsável por julgar um caso
- **Justiça Federal**: É a autoridade judiciária federal, que tem competência para julgar crimes federais
- **Competência Estadual**: É a competência da Justiça estadual, que tem competência para julgar crimes estaduais

### Referências legais
- Art. 76, inciso III do CPP

### Jurisprudência
- RE 123456
- Súmula 706 STF

### Dicas de prova
- Entenda a diferença entre competência penal e justiça federal.
- Conheça as regras de conexão instrumental, probatória ou processual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76, inciso III do CPP"], "jurisprudence": ["RE 123456", "Súmula 706 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:30:20.895913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=249", "doc_key": "341165bacd7c7ac660e60e74b67541bd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'da3e1c56a3d7aa0ad6d5678bcb3bc2a116e99475868f672a4d02a210aad6b550'),
  ('cpiuris2025::84cb3a73faa615e9faad9e236c1a18e3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência em processos criminais', '## Competência em processos criminais

A competência será firmada pela prevenção quando houver pluralidade de vítimas, de acordo com o artigo 70, § 4º do CPP.

### Conceitos
- **Competência**: Conceito jurídico que se refere à determinação da competência do juiz ou tribunal para processar e julgar um caso
- **Prevenção**: Instituto processual que permite a competência da prevenção, quando houver pluralidade de vítimas
- **Art. 70, § 4º do CPP**: Disposição legal que estabelece a regra para a competência em casos de pluralidade de vítimas

### Referências legais
- Art. 70, § 4º do CPP

### Dicas de prova
- Distinção entre competência e prevenção
- Importância da prevenção em casos de pluralidade de vítimas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.250", "page_number": 250, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 70, § 4º do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:30:38.555187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=250", "doc_key": "84cb3a73faa615e9faad9e236c1a18e3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c333b13bda9f2d359510a70dc26c2e11126517ea266ab670389608d5889b3c2f'),
  ('cpiuris2025::c8534ddc5c0e2182d5364c7dd426b41b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questões Prejudiciais e Preliminares', '## Questões Prejudiciais e Preliminares

Questões prejudiciais são resolvidas pelo juízo penal ou pelo juízo cível, mas não podem ser resolvidas somente pelo juízo penal. São autônomas, vinculadas ao processo e absolutamente dependentes.

### Conceitos
- **Questões Prejudiciais**: São questões processuais que dizem respeito ao próprio processo e seu regular desenvolvimento.
- **Questões Preliminares**: São questões que dizem respeito a determinada elementar/tipicidade do crime que deve ser resolvida.
- **Homogênea/Comum/Imperfeita/Não Devolutiva**: É aquela em que a sua resolução pertence ao mesmo ramo do direito.
- **Heterogênea/Incomum/Perfeita/Devolutiva/Extrapenais/Jurisdicionais**: É aquela em que a sua resolução pertence a outro ramo do direito.

### Referências legais
- Art. 92 a 94, CPP

### Dicas de prova
- Diferenciar entre questões prejudiciais e preliminares.
- Entender a classificação das questões prejudiciais (homogênea/heterogênea).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.252", "page_number": 252, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 92 a 94, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:31:49.111522+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=252", "doc_key": "c8534ddc5c0e2182d5364c7dd426b41b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1102b98b50248577e9f103ef63f2885e960189f1d7d49f62abcf07ef6c6b257f'),
  ('cpiuris2025::4ca1eb78562ec3be8f5c78be23a6e0b4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questões Prejudiciais Heterogêneas', '## Questões Prejudiciais Heterogêneas

As questões prejudiciais heterogêneas são divididas em duas espécies: obrigatória e facultativa. A obrigatória suspende o curso do processo criminal até que a questão seja resolvida no juízo cível, enquanto a facultativa pode ser suspensa apenas se for de difícil solução e não versar sobre direito cuja prova a lei civil limite.

### Conceitos
- **Prejudicialidade Obrigatória**: Suspensão obrigatória do processo criminal até que a questão seja resolvida no juízo cível
- **Prejudicialidade Facultativa**: Suspensão facultativa do processo criminal, apenas se for de difícil solução e não versar sobre direito cuja prova a lei civil limite
- **Suspensão do Processo**: Prazo indeterminado até que haja decisão transitada em julgado no juízo cível a respeito da questão prejudicial
- **Prescrição**: Fica suspensa

### Referências legais
- Art. 92, CPP
- Art. 93, CPP
- Art. 116, inciso I, CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre prejudicialidade obrigatória e facultativa
- Entender a suspensão do processo criminal e sua duração indefinida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.253", "page_number": 253, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 92, CPP", "Art. 93, CPP", "Art. 116, inciso I, CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:31:56.217158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=253", "doc_key": "4ca1eb78562ec3be8f5c78be23a6e0b4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8862957adc2f363e84e6219696a70d34a38b6d27330cfddc0f5bacf8d4d2921c'),
  ('cpiuris2025::a6653be1fab4c32585415507bf3e4663', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questão Prejudicial Heterogênea Facultativa', '## Questão Prejudicial Heterogênea Facultativa

A questão prejudicial heterogênea facultativa é apresentada quando o processo criminal será suspenso pelo juiz, exceto em casos de ação pública e crime extrapenal não relacionado com o estado civil das pessoas.

### Conceitos
- **Questão Prejudicial Heterogênea Facultativa**: Processo criminal suspenso por questão prejudicial
- **Suspensão do Processo**: Prazo determinado para o juiz cível proferir a decisão
- **Competência Plena**: O juiz criminal retoma a competência para resolver toda a matéria
- **Cosa Julgada**: Decisão definitiva proferida pelo juízo cível faz coisa julgada no juízo penal

### Referências legais
- Art. 93, §1º, do CPP
- Art. 94, do CPP
- Art. 116, I, CP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinguir entre questão prejudicial heterogênea facultativa e total
- Entender a competência plena do juiz criminal após a suspensão do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.254", "page_number": 254, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93, §1º, do CPP", "Art. 94, do CPP", "Art. 116, I, CP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:34:24.999945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=254", "doc_key": "a6653be1fab4c32585415507bf3e4663"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2339e50e4340a03cd36ac2a7bc8d2e62f65462836cff8736e9d15a2a7e0d49dd'),
  ('cpiuris2025::81d733d0d57010d6a2722a55ee7156dc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questões Prejudiciais Externas Facultativas', '## Questões Prejudiciais Externas Facultativas

A existência de decisão administrativa ou judicial favorável ao contribuinte pode caracterizar questão prejudicial externa facultativa que autoriza a suspensão do processo penal.

### Conceitos
- **Questão Prejudicial Externa**: Questão que afeta a decisão do processo penal
- **Facultativa**: Autoriza suspensão do processo penal, mas não é obrigatória
- **Suspensão do Processo Penal**: Prazo para realizar ação ou procedimento que possa afetar o processo penal

### Referências legais
- Art. 93 do CPP
- REsp 1.413.829-CE

### Jurisprudência
- {''term'': ''HC 99.740-RJ'', ''definition'': ''Julgamento do HC 99.740-RJ''}
- {''term'': ''REsp 1.413.829-CE'', ''definition'': ''Recurso Especial nº 1.413.829-CE''}

### Dicas de prova
