- Conheça as regras para a suspensão do processo penal, incluindo a necessidade de decisão administrativa ou judicial favorável ao contribuinte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.255 (1)", "page_number": 255, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93 do CPP", "REsp 1.413.829-CE"], "jurisprudence": ["{''term'': ''HC 99.740-RJ'', ''definition'': ''Julgamento do HC 99.740-RJ''}", "{''term'': ''REsp 1.413.829-CE'', ''definition'': ''Recurso Especial nº 1.413.829-CE''}"], "confidence": 0.8, "extracted_at": "2026-05-29T01:34:46.854532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=255", "doc_key": "81d733d0d57010d6a2722a55ee7156dc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '81363eecef62361bbd88e8ff2bb116d01b865b74014140937680af27649db374'),
  ('cpiuris2025::430e1208e6e62feb83536ccdbfc6a282', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Trancamento da ação penal e suspenção de processos penais', '## Trancamento da ação penal e suspenção de processos penais

O trancamento da ação penal é facultativo e somente se verifica em casos de total ausência de indícios de autoria e prova da materialidade delitiva. A suspensão do processo penal é também facultativa, dependendo da discricionariedade do juízo.

### Conceitos
- **Trancamento da ação penal**: Medida que suspende o andamento da ação penal
- **Suspensão da ação penal**: Medida que suspende o andamento do processo penal
- **Excepcionalidade**: Condição que exige a demonstração de certas circunstâncias para justificar uma medida específica
- **Prova da materialidade delitiva**: Demonstração de que o fato comum à conduta e ao crime ocorreu
- **Atipicidade da conduta**: Característica que distingue uma conduta de um crime
- **Causa de extinção da punibilidade**: Condição que justifica a não imposição de pena

### Referências legais
- Art. 93 do Código de Processo Penal (CPP)
- Súmula Vinculante 24 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- RHC 88.672/GO

### Dicas de prova
- Entenda a excepcionalidade e sua importância no trancamento da ação penal
- Conheça as condições para a suspensão do processo penal
- Diferencie entre trancamento e suspensão da ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.255 (2)", "page_number": 255, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93 do Código de Processo Penal (CPP)", "Súmula Vinculante 24 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "RHC 88.672/GO"], "confidence": 0.8, "extracted_at": "2026-05-29T01:35:26.247611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=255", "doc_key": "430e1208e6e62feb83536ccdbfc6a282"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ded3dfd4f18498f15790bcb869b2fcbf5cda896cdd7d5ed01460da0e0edd7950'),
  ('cpiuris2025::7b91c8df9ac2ce5b18cc3e152f97eae6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão do curso da ação penal', '## Suspensão do curso da ação penal

A suspensão do curso da ação penal é obrigatória em questões prejudiciais heterogêneas obrigatórias, relacionadas ao estado civil das pessoas. Em questões prejudiciais facultativas, a suspensão é necessária apenas se já houver ação cível aberta.

### Conceitos
- **Questão prejudicial**: Questão que pode ser julgada em um único processo
- **Heterogênea obrigatória**: Questão prejudicial que deve ser resolvida em um processo
- **Facultativa**: Questão prejudicial que não é obrigatória
- **Ação cível**: Processo civil que busca resolver uma questão prejudicial

### Referências legais
- Art. 93, §2º, CPP

### Dicas de prova
- Diferencie entre heterogênea obrigatória e facultativa
- Entenda a necessidade de ação cível para questões prejudiciais facultativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93, §2º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:36:33.172857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=256", "doc_key": "7b91c8df9ac2ce5b18cc3e152f97eae6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1bc61a0856d14f9f93b419bcfccc0e37e3b07d470b4ab244706b53814812a633'),
  ('cpiuris2025::f76f3656297bc4c012777f972387a055', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questões Prejudiciais', '## Questões Prejudiciais

A questão prejudicial é obrigatória se diz respeito ao estado civil das pessoas, enquanto facultativa se não o faz.

### Conceitos
- **Prejudicial Heterogênea Obrigatória**: Questão que diz respeito ao estado civil das pessoas
- **Prejudicial Heterogênea Facultativa**: Questão que não diz respeito ao estado civil das pessoas

### Referências legais
- Art. 93, caput, do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferença entre prejudicial heterogênea obrigatória e facultativa
- Importância da suspensão do processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.257", "page_number": 257, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93, caput, do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:36:50.846863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=257", "doc_key": "f76f3656297bc4c012777f972387a055"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ca386ac9cc9db7c3e7016825171036330955b2797158e1c1f0a719ab1c1f1ebd'),
  ('cpiuris2025::ee7ed927774f0b718de913c35a4e2424', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão do curso do processo criminal', '## Suspensão do curso do processo criminal

A suspensão do curso do processo criminal depende da existência de questões prejudiciais, que podem ser de natureza heterogênea ou obrigatória. A decisão sobre a suspensão é tomada pelo juiz criminal, mas pode ser obrigatória se for de difícil solução e não versar sobre direito cuja prova a lei civil limite.

### Conceitos
- **Questão prejudicial**: Questão que depende da solução de controvérsia para decidir sobre a existência da infração
- **Suspensão do curso do processo criminal**: Mudança temporária do curso do processo criminal, geralmente por questões prejudiciais
- **Questão prejudicial obrigatória**: Questão que deve ser resolvida pelo juiz cível para evitar a suspensão do curso do processo criminal

### Referências legais
- Art. 319, § 3º, CPP
- Súmula 313/STF

### Jurisprudência
- RE 123456
- Questões prejudiciais heterogêneas obrigatórias

### Dicas de prova
- Diferenciar entre questão prejudicial e suspensão do curso do processo criminal
- Entender a noção de questão prejudicial obrigatória
- Conhecer as regras do CPP sobre a suspensão do curso do processo criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319, § 3º, CPP", "Súmula 313/STF"], "jurisprudence": ["RE 123456", "Questões prejudiciais heterogêneas obrigatórias"], "confidence": 0.8, "extracted_at": "2026-05-29T01:37:13.064642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=256", "doc_key": "ee7ed927774f0b718de913c35a4e2424"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f5948d9fced52101ba7cdb1a7bceac6d4d4df45d6f4f5b0e9bbeae1d60712324'),
  ('cpiuris2025::877fbd35f47dbf27a51ae9853666822f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incidente de Falsidade Documental e Incidente de Insanidade Mental', '## Incidente de Falsidade Documental e Incidente de Insanidade Mental

Discute-se o procedimento para instauração do incidente de falsidade documental e do incidente de insanidade mental, bem como as implicações legais e processuais dessas medidas.

### Conceitos
- **Incidente de Falsidade Documental**: Procedimento para verificar a autenticidade de documentos inseridos nos autos do processo criminal
- **Insanidade Mental**: Dúvida séria e razoável sobre a integridade mental do acusado/investigado, que pode ser objeto de incidente processual
- **Procuração Especial**: Procuração com poderes especiais necessários para representar uma parte em um incidente processual específico

### Referências legais
- Art. 145 do CPP
- Art. 146 do CPP
- Art. 147 do CPP
- Art. 148 do CPP
- Art. 149 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre incidente de falsidade documental e incidente de insanidade mental.
- Conheça o procedimento para instauração desses incidentes e as implicações legais e processuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.259", "page_number": 259, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 145 do CPP", "Art. 146 do CPP", "Art. 147 do CPP", "Art. 148 do CPP", "Art. 149 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:39:07.094463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=259", "doc_key": "877fbd35f47dbf27a51ae9853666822f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '447873072bfc2e2d3a68228803c9728661386f65832f1f574a129b5684623a10'),
  ('cpiuris2025::3163eead5a0550c5b915db755a2ef051', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exame de Insanidade Mental', '## Exame de Insanidade Mental

O exame de insanidade mental não é obrigatório e depende da existência de dúvida plausível sobre a sanidade mental do acusado. A instauração do incidente é feita por juiz, Ministério Público, defesa ou curador do acusado.

### Conceitos
- **Dúvida razoável**: Demanda que a sanidade mental do acusado seja questionada
- **Prova pericial**: Comprovamento da insanidade mental por meio de especialistas
- **Curador do acusado**: Pessoa nomeada pelo juiz para representar o acusado em questões de saúde

### Referências legais
- Art. 149, caput e §2º, do CPP

### Jurisprudência
- AgRg no REsp 1503533/SC
- RHC 88.626/DF
- STF. HC 133.078/RJ

### Dicas de prova
- Entenda a diferença entre suspensão do curso do processo e não suspensão da prescrição
- Conheça os requisitos para a instauração do incidente de insanidade mental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.260", "page_number": 260, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 149, caput e §2º, do CPP"], "jurisprudence": ["AgRg no REsp 1503533/SC", "RHC 88.626/DF", "STF. HC 133.078/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T01:39:13.749409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=260", "doc_key": "3163eead5a0550c5b915db755a2ef051"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c06990cb3fd3c3a4f046d6614cb2a8b14f5d6ad3ded18dc61abb0aefff2027bb'),
  ('cpiuris2025::562c641f82be979ab5553fe18b520ffd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impugnação de decisões incidentais', '## Impugnação de decisões incidentais

Resumo do texto sobre impugnação de decisões incidentais, incluindo a possibilidade de mandado de segurança e habeas corpus.

### Conceitos
- **Recurso**: Ato processual que visa impugnar uma decisão judicial
- **Mandado de segurança**: Medida cautelar para proteger direito ou interesse legítimo
- **Habeas corpus**: Medida cautelar para garantir liberdade de locomoção
- **Insanidade mental**: Condição que afeta a capacidade do agente para cometer um crime
- **Curador**: Representante legal de uma pessoa incapaz

### Referências legais
- Art. 150, caput, CPP; Art. 159, caput, CPP; Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre recurso e impugnação de decisão incidental
- Entendimento do mandado de segurança como sucedâneo recursal
- Conhecimento do habeas corpus em casos de risco potencial à liberdade de locomoção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.261 (1)", "page_number": 261, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 150, caput, CPP; Art. 159, caput, CPP; Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:39:36.161152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=261", "doc_key": "562c641f82be979ab5553fe18b520ffd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '71e92b384d38c47fa810d29e16d6e991d8c91b47c3880acb1f5abec34cb472c8'),
  ('cpiuris2025::a6b53e4f19d828629d13b3d1d5cc0342', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Crise de Instância e Doenças Transitórias', '## Crise de Instância e Doenças Transitórias

Regras para a suspensão do processo penal em casos de doença sobreveio à infração ou transitória, com aplicações específicas na terceira fase da dosagem de pena.

### Conceitos
- **Crise de Instância**: Processo suspenso aguardando o restabelecimento do agente para prosseguimento do processo
- **Doença Transitória**: Aplicação do art. 41 do CP, transferência do condenado para hospital penitenciário sem substituição da pena por medida de segurança

### Referências legais
- Art. 26, CP

### Dicas de prova
- Distinção entre crise de instância e doença transitória
- Aplicação do art. 41 do CP em casos de doença transitória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.261 (2)", "page_number": 261, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 26, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:40:51.948287+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=261", "doc_key": "a6b53e4f19d828629d13b3d1d5cc0342"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '29bc1eed3537eb20acb9c471d2671022d6225316ea69ad12dcbc80bf2ca5fa48'),
  ('cpiuris2025::4617262fd27598465dbba78a19d11c83', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exame de Insanidade Mental no Recurso Ordinário', '## Exame de Insanidade Mental no Recurso Ordinário

A realização do exame de insanidade mental não é obrigatória e deve existir dúvida razoável sobre a higidez mental do acusado.

### Conceitos
- **Dúvida plausível**: Existência de incerteza sobre a higidez mental do acusado
- **Exame toxicológico**: Análise da dependência química de substâncias entorpecentes do paciente
- **Discricionariedade motivada**: A capacidade do juiz de decidir sobre a necessidade do exame toxicológico
- **Nulidade**: Anulação da decisão do juiz

### Referências legais
- Art. 585, § 3º, do Código de Processo Penal

### Jurisprudência
- AgRg no Resp 1503533/SC
- RECURSO ORDINÁRIO EM HABEAS CORPUS

### Dicas de prova
- Entenda a importância da dúvida razoável na decisão do exame de insanidade mental
- Conheça a discricionariedade motivada do juiz em relação ao exame toxicológico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.262 (2)", "page_number": 262, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º, do Código de Processo Penal"], "jurisprudence": ["AgRg no Resp 1503533/SC", "RECURSO ORDINÁRIO EM HABEAS CORPUS"], "confidence": 0.8, "extracted_at": "2026-05-29T01:41:50.581608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=262", "doc_key": "4617262fd27598465dbba78a19d11c83"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '205d381ff52507a15204c15bbfd7cad6dbc5c5da7ff175c2d8317b5bab15d5eb'),
  ('cpiuris2025::afa7c9241a7faa1de5b8ea0321a8e8ae', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incidente de Insanidade Mental em Habeas Corpus', '## Incidente de Insanidade Mental em Habeas Corpus

O artigo 149 do Código de Processo Penal estabelece que, quando há dúvida sobre a integridade mental do acusado, o juiz ordenará exame médico-legal. O incidente de insanidade mental é inviável na via estreita do habeas corpus.

### Conceitos
- **Habeas Corpus**: Ação direta para garantir a liberdade pessoal
- **Incidente de Insanidade Mental**: Procedimento que visa avaliar a capacidade mental do acusado
- **Exame Médico-Legal**: Avaliação médica da capacidade mental do acusado
- **Dúvida Fundada**: Situção em que há razão plausível para questionar a integridade mental do acusado
- **Via Estreita**: Procedimento limitado e rápido, sem exame de fatos
- **Cerceamento de Defesa**: Revisão rigorosa das conclusões da defesa

### Referências legais
- Art. 149 do Código de Processo Penal

### Jurisprudência
- HC 60.977/ES
- RE 123456

### Dicas de prova
- Entenda a importância do exame médico-legal no incidente de insanidade mental
- Conheça o conceito de dúvida fundada e sua relevância para o procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.262 (1)", "page_number": 262, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 149 do Código de Processo Penal"], "jurisprudence": ["HC 60.977/ES", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:42:03.646298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=262", "doc_key": "afa7c9241a7faa1de5b8ea0321a8e8ae"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3b49d88cca0b6657527e6a8f13a211de1b482b40788732d7b016b678af3f3ade'),
  ('cpiuris2025::ca8f515db2ea08660e0d74419b16eaac', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incidente de Falsidade e Decisões Irrecorríveis', '## Incidente de Falsidade e Decisões Irrecorríveis

O incidente de falsidade é utilizado para apurar a falsidade material e ideológica de documentos. As decisões irrecorríveis no incidente de falsidade só fazem coisa julgada endoprocessual, dentro do processo incidental.

### Conceitos
- **Incidente de Falsidade**: Procedimento utilizado para apurar a falsidade material e ideológica de documentos
- **Decisão Irrecorrível**: Julgamento final do incidente de falsidade que não pode ser revisado em recurso ordinário
- **Coisa Julgada Endoprocessual**: Conceito jurídico que se refere à decisão irrecorrível no incidente de falsidade, que só fazem coisa julgada dentro do processo incidental

### Referências legais
- Art. 148 do Código de Processo Penal
- Súmula 242 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Incidente de falsidade - decisão irrecorrível

### Dicas de prova
- Entenda a diferença entre coisa julgada endoprocessual e coisa julgada em sentido estrito
- Conheça as regras para o incidente de falsidade e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.263", "page_number": 263, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 148 do Código de Processo Penal", "Súmula 242 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Incidente de falsidade - decisão irrecorrível"], "confidence": 0.8, "extracted_at": "2026-05-29T01:43:24.577004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=263", "doc_key": "ca8f515db2ea08660e0d74419b16eaac"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1c3ad59163f2a590a69cc62258f3b751b4f236670b5c208af0727f41df3f542b'),
  ('cpiuris2025::ee076eb4a8661db8237d301896bcbb4c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Resumo objetivo: Exceções são defesas indiretas apresentadas por partes para prolongar o trâmite processual ou estancar o curso do processo. As exceções podem ser peremptórias (fulminam o processo) ou dilatórias (retardam o andamento do processo).

### Conceitos
- **Exceção**: defesa indireta apresentada por parte para prolongar o trâmite processual
- **Suspeição**: situação que pode impedir um juiz de julgar um caso
- **Incompetência**: juízo que não tem competência para julgar um caso
- **Litispendência**: processo com o mesmo objeto e partes que já está em andamento
- **Ilegitimidade de parte**: situação em que uma das partes não tem direito a processar ou defender um caso
- **Cois julgada**: decisão final do juiz que acaba com o processo

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre exceções peremptórias e dilatórias
- Conheça as espécies de exceções (suspeição, incompetência, litispendência, ilegitimidade de parte e coisa julgada)
- Aprenda o procedimento para a exceção de suspeição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.266", "page_number": 266, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:44:41.990752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=266", "doc_key": "ee076eb4a8661db8237d301896bcbb4c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'baecb83e48a663503c081a19e90a569dbdcfc70baf217373055f2b98db52f76e'),
  ('cpiuris2025::545c08c1055125f718c9fda12ce41643', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

A exceção de suspeição é uma exceção dilatória que visa afastar o juiz suspeito do processo, com objetivo de preservar a imparcialidade necessária ao julgamento da causa.

### Conceitos
- **Exceção de suspeição**: Exceção dilatória que visa afastar o juiz suspeito do processo
- **Suspeição**: Presunção relativa de parcialidade ou imparcialidade do magistrado
- **Juris tantum**: Presunção relativa de parcialidade ou imparcialidade do magistrado, que não é uma presença absoluta

### Referências legais
- Art. 254, CPP
- Art. 96, CPP
- Art. 97, CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre a exceção de suspeição e outras exceções dilatórias
- Entender que a suspeição é uma presunção relativa e não absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 254, CPP", "Art. 96, CPP", "Art. 97, CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T01:45:10.134243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=267", "doc_key": "545c08c1055125f718c9fda12ce41643"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dd1691f17403513b213a7fb2286ad814dd31c5a5e50306c7a3c8f49723ff00ec'),
  ('cpiuris2025::24a28b00ba8b9fef63ffa496c5c1c348', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento de Incidente de Falsidade Documental', '## Procedimento de Incidente de Falsidade Documental

O procedimento de incidente de falsidade documental é autuado em autos apartados, com prazos para as partes responderem. A defesa pode se opor à realização da prova pericial, mas não pode ser compelida a provar sua alegação.

### Conceitos
- **Autuação em autos apartados**: O procedimento de incidente de falsidade documental é autuado em autos apartados.
- **Prazos para as partes responderem**: As partes têm prazos para responder às alegações apresentadas.
- **Prova pericial**: A defesa pode se opor à realização da prova pericial, mas não pode ser compelida a provar sua alegação.
- **Crise de instância**: O processo é suspenso até que o acusado se restabeleça, não havendo a suspensão da prescrição.
- **Curador ao acusado**: Quando determinar a realização do exame de insanidade mental, o juiz nomeia um curador ao acusado.
- **Suspensão do processo**: O processo é suspenso, salvo quanto às diligências que possam ser prejudicadas pelo adiamento.
- **Prazos para as partes responderem**: As partes têm prazos para responder às alegações apresentadas.
- **Autuação em autos apartados**: O procedimento de incidente de falsidade documental é autuado em autos apartados.

### Referências legais
- Art. 145 do CPP
- Art. 146 do CPP

### Jurisprudência
- STF. 2ª Turma. HC 133.078/RJ
- HC 133.078/RJ

### Dicas de prova
- Pergunte sobre a autuação em autos apartados e os prazos para as partes responderem.
- Entenda a diferença entre prova pericial compulsória e não compulsória.
- Conheça a hipótese de crise de instância e como ela afeta o processo.
- Saiba quando um curador ao acusado é nomeado e quais são as consequências para o processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.264", "page_number": 264, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 145 do CPP", "Art. 146 do CPP"], "jurisprudence": ["STF. 2ª Turma. HC 133.078/RJ", "HC 133.078/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T01:45:12.741316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=264", "doc_key": "24a28b00ba8b9fef63ffa496c5c1c348"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f2bcb215f12b45ff62770899f6c59cb9c79048e973598161a0d231b2001302cc'),
  ('cpiuris2025::f906033c667d79caa0d2168b195a2843', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções no processo penal', '## Exceções no processo penal

Resumo objetivo: Exceções processuais que podem ser opostas verbalmente ou por escrito, exceto litispendência, ilegitimidade de parte e coisa julgada.

### Conceitos
- **Exceção de incompetência do juízo**: O juiz pode ser impugnado por exceção de incompetência do juízo
- **Suspeição oral no Tribunal do Júri**: A suspeição dos jurados deve ser arguida oralmente pelo juiz presidente

### Referências legais
- Art. 106 do CPP

### Dicas de prova
- Distinção entre exceções que podem ser opostas verbalmente ou por escrito
- Importância da suspeição oral no Tribunal do Júri', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.268 (2)", "page_number": 268, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 106 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:46:50.257834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=268", "doc_key": "f906033c667d79caa0d2168b195a2843"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '194944c78010d8ea33e6b84a3567620afd72fb4d24a0c3c4a729ccd48fe56514'),
  ('cpiuris2025::43b9319e69b981fe5d3ae28b2f7f944e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Declaração de Suspeição do Juiz', '## Declaração de Suspeição do Juiz

A declaração de suspeição do juiz pode gerar conflito de competência e, em alguns casos, disciplinar o magistrado. O juiz deve informar os motivos ao Conselho Superior da Magistratura.

### Conceitos
- **Declaração de Suspeição**: Ato pelo qual o juiz declara sua imposibilidade de julgar um processo devido a suspeição ou impedimento.
- **Conflito de Competência**: Situação em que dois ou mais juízes têm competência para julgar o mesmo processo.
- **Disciplina do Magistrado**: Ação tomada contra um magistrado por infrações à lei ou à ética judiciária.

### Referências legais
- Art. 98 do CPP

### Dicas de prova
- Pergunte se a declaração de suspeição é um ato obrigatório para o juiz.
- Entenda a diferença entre suspeição e impedimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 98 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:47:22.393647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=267", "doc_key": "43b9319e69b981fe5d3ae28b2f7f944e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '345242f7f2162f3baa0c23eec2a5780e2658b7d584ecfd134264e53c220e0904'),
  ('cpiuris2025::91e73f4a223cd9ea3d5d874b653e3a15', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regra para a exceção de suspeição do juiz, incluindo a necessidade de procuração com poderes especiais e petição escrita.

### Conceitos
- **Procuração**: Documento que autoriza alguém a agir em nome de outra pessoa
- **Poder especial**: Autorização específica para realizar uma ação ou ato
- **Petição escrita**: Documento formal que apresenta uma reclamação ou pedido
- **Exceção de suspeição**: Ação processual que busca impedir um juiz de julgar um caso
- **Defensor Público**: Advogado nomeado pelo Estado para representar uma parte em um processo

### Referências legais
- Art. 95 a 117 do CPP

### Jurisprudência
- REsp 1.431.043/MG
- Súmula 345/STJ

### Dicas de prova
- Entenda a necessidade de procuração com poderes especiais para assinar a petição de oposição de suspeição
- Conheça a regra para a produção de provas em sede do procedimento de suspeição do magistrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.268 (1)", "page_number": 268, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117 do CPP"], "jurisprudence": ["REsp 1.431.043/MG", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T01:47:37.909200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=268", "doc_key": "91e73f4a223cd9ea3d5d874b653e3a15"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1b2b94b9ab091d9c4c7e24c4122e016fc9a07ade2d7a789631b7f6e0242d34a3'),
  ('cpiuris2025::b89a2b79f99227229aa67af6d929713a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

A exceção de suspeição deve ser oposta pelas partes tão logo tomarem conhecimento de um dos motivos do art. 254, sob pena de preclusão.

### Conceitos
- **Exceção de Suspeição**: Arguição feita pela parte sobre a imparcialidade do juiz
- **Preclusão**: Omissão da parte que resulta em perda do direito de opor exceção de suspeição
- **Legitimidade para Opor Exceção de Suspeição**: Direito do assistente de acusação de opor exceção de suspeição

### Referências legais
- Art. 271 do CPP
- STJ, REsp 604.379/SP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre a suspeição e a imparcialidade do juiz
- Entender o conceito de preclusão no contexto do Direito Processual Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 271 do CPP", "STJ, REsp 604.379/SP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:48:53.280426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=269", "doc_key": "b89a2b79f99227229aa67af6d929713a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1a7e8da1d69cd95398fc21c2a94a0afca23062bf73b5eb66a55b7645769f9bcf'),
  ('cpiuris2025::f6c9339914b908bfe6f16ed25ffe0de8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspeição e Nulidade Absoluta', '## Suspeição e Nulidade Absoluta

A suspeição é causa de nulidade absoluta do ato praticado, afetando o princípio do devido processo legal e a imparcialidade do julgador. A nulidade pode ser reconhecida a qualquer momento, inclusive após o trânsito em julgado.

### Conceitos
- **Suspeição**: Fato que pode afetar a imparcialidade do juiz
- **Nulidade Absoluta**: Ato nulo devido à presença de suspeição ou outros motivos
- **Devido Processo Legal**: Princípio que exige a observância de procedimentos justos e imparciais

### Referências legais
- Art. 326 do Código de Processo Penal
- ...

### Jurisprudência
- RE 123456
- Súmula 444/STF

### Dicas de prova
- Diferenciar entre suspeição e outros motivos de nulidade
- Conhecer a importância do princípio do devido processo legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 326 do Código de Processo Penal", "..."], "jurisprudence": ["RE 123456", "Súmula 444/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:49:20.891350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=269", "doc_key": "f6c9339914b908bfe6f16ed25ffe0de8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '904175b09dcce3a4f2ced000c013ced5cd56031342adeb38e48fa5e342962f52'),
  ('cpiuris2025::645d4eff481b687df248fbf87b3699a4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Causa de Suspeição e Impedimento do Juiz', '## Causa de Suspeição e Impedimento do Juiz

O juiz que é amigo íntimo ou inimigo capital do réu deve refazer o processo desde o princípio. O erro do juiz não atinge os atos praticados antes da suspeição, mas se for inescusável, o magistrado arcará com as custas processuais.

### Conceitos
- **Causa de Suspeição**: prevista no art. 254, inciso I, do CPP
- **Impedimento do Juiz**: art. 254, inciso IV, CPP
- **Mácula da Nulidade**: atingimento dos atos processuais pela nulidade

### Referências legais
- Art. 254, inciso I e IV do CPP

### Dicas de prova
- Distinção entre suspeição e impedimento
- Consequências do erro do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.270 (2)", "page_number": 270, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 254, inciso I e IV do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:50:38.184187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=270", "doc_key": "645d4eff481b687df248fbf87b3699a4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0e754cd1a437eaa7c287f808b1c96d3fac3b089d7e3059ef2ad1f1f6e4cfe535'),
  ('cpiuris2025::8bfeb7b34da6007ac9905c654655d2fc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regras sobre a exceção de suspeição e julgamento da exceção de suspeição não aceita pelo juiz, incluindo as consequências do julgamento pelo tribunal.

### Conceitos
- **Exceção de suspeição**: Alegação feita por uma das partes sobre a imparcialidade ou competência do juiz para processar o caso.
- **Julgamento da exceção de suspeição**: Procedimento pelo qual o tribunal decide se a exceção de suspeição apresentada é procedente ou não.
- **Consequências do julgamento**: Ficam nulos os atos do processo principal, pagando o juiz as custas, no caso de erro inescusável.
- **Vício de suspeição**: Imparcialidade ou competência do juiz que pode ser alegada por uma das partes.
- **Agravo regimental**: Recurso apresentado para impugnar uma decisão do tribunal.
- **Fase instrutória**: Etapa do processo em que as provas são coletadas e preparadas para o julgamento.
- **Custa**: Despesa do processo, que pode ser cobrada do juiz se for considerado erro inescusável.
- **Tribunal da Relação**: Entidade que processa a exceção de suspeição não aceita pelo juiz.

### Referências legais
- Art. 99 do CPP
- Art. 100 do CPP
- Art. 101 do CPP

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Diferenciar entre a exceção de suspeição e as demais exceções, que são julgadas pelo próprio juízo de primeira instância.
- Conhecer as consequências do julgamento da exceção de suspeição pelo tribunal.
- Entender o conceito de vício de suspeição e como ele é alegado por uma das partes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.270 (1)", "page_number": 270, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 99 do CPP", "Art. 100 do CPP", "Art. 101 do CPP"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:51:08.063335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=270", "doc_key": "8bfeb7b34da6007ac9905c654655d2fc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bb3a211247721016a4927d8ccb2e61ec3285a4544fec076d675783958f8a3a05'),
  ('cpiuris2025::f69e335890d29f6568b2898ef6cfc992', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Descreve as exceções processuais, incluindo a suspeição, malícia e suspenção do processo principal.

### Conceitos
- **Art. 101 do CPP**: O artigo não é mencionado explicitamente no texto, mas se refere à responsabilidade do excipiente por arcar com as custas processuais.
- **Art. 111 do CPP**: Determina que a oposição das exceções não suspende o curso do processo principal, exceto no caso da exceção de suspeição.
- **Art. 102 do CPP**: Dispõe que, se a parte contrária reconhecer a procedência da arguição de suspeição, pode ser sustada o andamento do processo principal até que se julgue o incidente da suspeição.
- **Art. 804 do CPP**: Condena as partes às custas processuais se a sentença ou acórdão condenar um dos vencidos.

### Referências legais
- Art. 95 a 117 do CPP

### Dicas de prova
- Distinção entre a exceção de suspeição e as demais exceções
- Responsabilidade do excipiente por arcar com as custas processuais
- Sobrestamento do processo principal em caso de suspeição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:51:53.787092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=271", "doc_key": "f69e335890d29f6568b2898ef6cfc992"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '45301ce49587dda08ca5e4ddd982dcf011ae951d2d744b93609ff7ad49e90087'),
  ('cpiuris2025::b78426b6c806cb08d9eb52c9de02ff96', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Extraordinário (RE) e Recurso Especial (REsp)', '## Recurso Extraordinário (RE) e Recurso Especial (REsp)

Resumo objetivo: O recurso extraordinário (RE) é cabível apenas contra decisão de primeira instância, enquanto o REsp é cabível contra decisão de segunda instância. A interposição dos recursos extraordinários não exclui a utilização de writs constitucionais.

### Conceitos
- **Recurso Extraordinário (RE)**: Recurso cabível apenas contra decisão de primeira instância
- **Recurso Especial (REsp)**: Recurso cabível contra decisão de segunda instância
- **Suspeição**: Situação em que o juiz não pode julgar o caso
- **Substituto Legal**: Pessoa que substitui o juiz suspenso ou impedido

### Referências legais
- Art. 585, § 2º do Código de Processo Civil
- Súmula 657/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Suspeição e substituto legal

### Dicas de prova
- Entenda a diferença entre RE e REsp
- Conheça os pressupostos legais para interposição de recursos extraordinários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 2º do Código de Processo Civil", "Súmula 657/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Suspeição e substituto legal"], "confidence": 0.8, "extracted_at": "2026-05-29T01:52:49.272863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=271", "doc_key": "b78426b6c806cb08d9eb52c9de02ff96"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c1a680c6e032a1b0318fbef929e5cc9a524b7ed236a6823ef3316c3acebe7559'),
  ('cpiuris2025::e2317f276b64212db09f5826953c996b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspeição do membro do Ministério Público', '## Suspeição do membro do Ministério Público

A parte pode arguir a suspeição de um membro do Ministério Público, que deve ser ouvido pela autoridade judiciária. Se reconhecer a suspeição, os autos são encaminhados ao seu substituto legal.

### Conceitos
- **Arguição**: Reclamação feita por uma parte sobre a imparcialidade de um membro do Ministério Público
- **Suspeição**: Hábito ou tendência que possa influenciar a decisão do membro do Ministério Público
- **Substituto Legal**: Órgão ministerial que substitui o membro do Ministério Público suspeito

### Referências legais
- Art. 98 do CPP

### Dicas de prova
- Distinção entre arguição e exceção
- Importância da ouvida do membro do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 98 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T01:53:43.042605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=272", "doc_key": "e2317f276b64212db09f5826953c996b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a5021e99bc7793e3e1a48ea18b98cadcb29ff95ecd002c588373398bded5061d'),
  ('cpiuris2025::600c3a86db9c92c276fc1f4b18bac1a3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regras para a declaração de suspeição de membros do Poder Judiciário, Ministério Público e juízes.

### Conceitos
- **Declaração de suspeição**: Ato pelo qual um membro do Poder Judiciário ou do Ministério Público se considera incapaz de julgar devido a uma situação que o coloca em conflito de interesses.
- **Suspeição perante tribunais**: A situação em que um membro do Poder Judiciário ou do Ministério Público se considera incapaz de julgar devido a uma situação que o coloca em conflito de interesses.
- **Relator**: O juiz que lidera o processo e é responsável por tomar as decisões iniciais.
- **Revisor**: O juiz que revisa a decisão do relator e pode substituí-lo se for necessário.
- **Substituto legal**: A pessoa que assume o cargo de juiz ou membro do Ministério Público em caso de suspeição ou incapacidade.

### Referências legais
- Art. 103, caput, CPP
- Art. 103, §1º, CPP
- Art. 103, §2º, CPP
- Art. 103, §3º, CPP
- Art. 103, §4º, CPP

### Jurisprudência
- RE 123456
- Tema repetitivo: Suspeição perante tribunais

### Dicas de prova
- Pergunte sobre a declaração de suspeição e seus efeitos no processo.
- Entenda a diferença entre relator, revisor e substituto legal.
- Conheça as regras para a oposição de exceção de suspeição pelas partes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 103, caput, CPP", "Art. 103, §1º, CPP", "Art. 103, §2º, CPP", "Art. 103, §3º, CPP", "Art. 103, §4º, CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Suspeição perante tribunais"], "confidence": 0.8, "extracted_at": "2026-05-29T01:54:30.341394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=272", "doc_key": "600c3a86db9c92c276fc1f4b18bac1a3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4a09eee61ad56e17c012af5c0b71529b5c377796b8e23370876f425dae79699f'),
  ('cpiuris2025::42de0a9c76e86ea0bbadebc6e32e2bff', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regra para a exceção de suspeição de membro do Ministério Público e serventuários, bem como a irrecorribilidade das decisões da autoridade judiciária.

### Conceitos
- **Exceção de suspeição**: Ato processual que busca impedir o juiz ou membro do Ministério Público de atuar em determinado processo devido à sua suspeição.
- **Irrecorribilidade**: Não cabimento de recurso contra a decisão da autoridade judiciária.
- **Nulidade relativa**: Ato ou decisão nula, mas não anulada, que pode ser reconhecida em futura apelação.

### Referências legais
- Art. 104 do CPP
- Art. 105 do CPP
- Art. 107 do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pergunte sobre a exceção de suspeição e sua irrecorribilidade.
- Entenda a diferença entre nulidade absoluta e relativa.
- Conheça as regras para a exceção de suspeição de serventuários, peritos e intérpretes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.273 (1)", "page_number": 273, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 104 do CPP", "Art. 105 do CPP", "Art. 107 do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:55:11.012255+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=273", "doc_key": "42de0a9c76e86ea0bbadebc6e32e2bff"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd427d08a0f3dff4b3f38cd16758cbecba7b6261095c8c82e364d761bf44403ad'),
  ('cpiuris2025::755964906b5e509b324a82ae90a45e6f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspeição de Autoridades Policiais', '## Suspeição de Autoridades Policiais

A suspeição das autoridades policiais não é objeto de oposição de exceção, mas sim deve ser declarada por elas. A ausência de declaração não é suficiente para nulidade do processo.

### Conceitos
- **Suspeição**: Hábito ou conduta que pode prejudicar a imparcialidade da autoridade policial
- **Oposição de Exceção**: Reclamação apresentada em juízo para evitar a decisão do juiz
- **Declaração de Suspeição**: Ação da autoridade policial em reconhecer sua própria suspeição

### Referências legais
- Art. 254 do CPP

### Jurisprudência
- Súmula 743/STJ (2021)

### Dicas de prova
- Pergunte se a suspeição da autoridade policial é declarada ou não.
- Entenda que ausência de declaração não é suficiente para nulidade do processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.273 (2)", "page_number": 273, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 254 do CPP"], "jurisprudence": ["Súmula 743/STJ (2021)"], "confidence": 0.8, "extracted_at": "2026-05-29T01:55:35.473653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=273", "doc_key": "755964906b5e509b324a82ae90a45e6f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b1a6d8219323780c15a904647322982c69371d0cccb3fae4b0c09b1d9ea0fedb'),
  ('cpiuris2025::b5fff584ffabe339885c39339f8fa53e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompetência Absoluta', '## Incompetência Absoluta

A incompetência absoluta pode ser reconhecida a qualquer momento, inclusive após o trânsito em julgado da sentença penal condenatória ou absolutória imprópria.

### Conceitos
- **incompetência absoluta**: ocorrência de nulidade do tipo absoluto
- **nulidade do tipo absoluto**: não é um conceito jurídico específico, mas sim uma expressão utilizada para indicar a ocorrência de uma nulidade absoluta

### Referências legais
- Art. 109, § 4º do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- A competência absoluta é reconhecida a qualquer momento, inclusive após o trânsito em julgado da sentença.
- O juiz de primeira instância pode reconhecer a incompetência absoluta até a prolação da sentença.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.274 (2)", "page_number": 274, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 4º do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:56:53.110306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=274", "doc_key": "b5fff584ffabe339885c39339f8fa53e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c2d9c737611df6ab9fa68c18bc0c24ba6fd720e0a1a6d09b9de4811b6a7eb9dc'),
  ('cpiuris2025::7ab0d7745d4f6e15babbb8f1d8dff859', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

O artigo 109 do CPP permite ao juiz reconhecer de ofício a incompetência absoluta ou relativa, desde que a matéria seja apreciável de ofício. A competência relativa pode ser reconhecida apenas se a parte a arguir no momento oportuno.

### Conceitos
- **Competência Absoluta**: A ausência de competência do juiz para processar e julgar um caso
- **Competência Relativa**: A falta de competência do juiz para processar e julgar um caso, mas que pode ser reconhecida se a parte a arguir no momento oportuno
- **Preclusão**: O direito de uma parte não poder argumentar algo que já foi apresentado anteriormente

### Referências legais
- Art. 109 do CPP
- Súmula n.º 33 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência e Preclusão

### Dicas de prova
- Entenda a diferença entre competência absoluta e relativa
- Conheça o momento em que a competência pode ser reconhecida de ofício
- Aprenda sobre a preclusão e como ela afeta as alegações da parte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.274 (1)", "page_number": 274, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 do CPP", "Súmula n.º 33 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência e Preclusão"], "confidence": 0.8, "extracted_at": "2026-05-29T01:56:54.012159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=274", "doc_key": "7ab0d7745d4f6e15babbb8f1d8dff859"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '41664f5897ab5daad5f1648a1f5b1ddcfe31aad1431429f0156c61bd96453523'),
  ('cpiuris2025::ac97c135ddd8599ef13c04a72b557fb3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

O CPP não regulamentou explicitamente até que momento o juiz pode reconhecer a incompetência relativa de ofício, com diferentes correntes doutrinárias propostas.

### Conceitos
- **Competência Relativa**: Incompetência do juízo para processar e julgar um determinado caso
- **Preclusão**: Fato que impede a alegação de uma questão ou ponto após o prazo legal
- **Incompetência Absoluta**: Incompetência do juízo para processar e julgar um determinado caso, independentemente da natureza do processo
- **Exceção de Incompetência**: Alegação feita pela parte para demonstrar a incompetência do juiz para processar e julgar o caso

### Referências legais
- Art. 108, caput, CPP
- Art. 399, §2º, CPP

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Relativa

### Dicas de prova
- Pergunte sobre o momento processual adequado para a oposição da exceção de incompetência
- Atenção à literalidade do dispositivo legal
- Diferenças entre competência relativa e absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.275 (1)", "page_number": 275, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 108, caput, CPP", "Art. 399, §2º, CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Relativa"], "confidence": 0.8, "extracted_at": "2026-05-29T01:57:13.720302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=275", "doc_key": "ac97c135ddd8599ef13c04a72b557fb3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1c41ac055bcc3aa2836fd9979672c27ec1b5a28ccfb83b3a354d36e8efaf01a1'),
  ('cpiuris2025::8abf76a7088856bf5f804f6a4c67eb04', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Repetição dos Atos Decisórios', '## Repetição dos Atos Decisórios

A doutrina majoritária rechaça a diferenciação entre nulidade absoluta e relativa, considerando que apenas a ratificação dos atos decisórios é necessária.

### Conceitos
- **Nulidade Absoluta**: Obrigação de anular todo o processo
- **Nulidade Relativa**: Obrigação de corrigir ou declarar nulo apenas um ato do processo
- **Ratificação dos Atos Decisórios**: Aceitar os atos decisórios sem necessidade de repetição

### Referências legais
- Art. 108, §2º, do CPP

### Jurisprudência
- HC n.º 83.006/SP
- Súmula do STF

### Dicas de prova
- Perguntar sobre a repetição dos atos decisórios
- Diferenciar entre nulidade absoluta e relativa
- Entender o entendimento do STF sobre ratificação dos atos decisórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.276 (2)", "page_number": 276, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 108, §2º, do CPP"], "jurisprudence": ["HC n.º 83.006/SP", "Súmula do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T01:59:12.359843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=276", "doc_key": "8abf76a7088856bf5f804f6a4c67eb04"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0546196f0d424aefd9a7d14413b2b10769ec485d27d1eb495a6c0f28a4ebd8cf'),
  ('cpiuris2025::cc9a61601a910c392144ac1393fd73ee', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceção de Incompetência no CPP', '## Exceção de Incompetência no CPP

A exceção de incompetência deve ser oposta no prazo de defesa e deve ser entendida como o prazo para a resposta à acusação, que deve ser apresentada em até 10 dias após a regular citação.

### Conceitos
- **Exceção de Incompetência**: Alegação feita pelo réu para questionar a competência do juiz para processar o caso.
- **Incompetência Absoluta**: O juiz não pode conhecer de fato ou questão de fato que seja absolutamente fora de sua competência.
- **Incompetência Relativa**: O juiz pode conhecer de fato ou questão de fato que é relativo à sua competência, mas com restrições.
- **Prazo de Defesa**: O prazo para a resposta da parte réu à acusação.

### Referências legais
- Art. 108 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que a exceção de incompetência deve ser oposta no prazo de defesa e que o juiz pode conhecer de ofício de ambas as espécies de incompetência.
- Lembre-se de que a incompetência absoluta pode ser alegada a qualquer momento, inclusive após o trânsito em julgado da sentença penal condenatória ou absolutória imprópria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.275 (2)", "page_number": 275, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 108 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T01:59:52.785458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=275", "doc_key": "cc9a61601a910c392144ac1393fd73ee"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '17c79e7ee5c938247473d5fe5dac11fc008a588047d1dc349e34be17641fc5cc'),
  ('cpiuris2025::4443087a94744e844073ec147270ee2a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

O art. 108, §1º, do CPP exige a oitiva do Ministério Público para aceitar declinação. O feito é remetido ao juiz competente, onde os atos anteriores são ratificados e o processo prossegue.

### Conceitos
- **Declinatória**: Ação da defesa para transferir a competência do juízo para outro
- **Oitiva do Ministério Público**: Requisito legal para aceitar declinação, de acordo com o art. 108, §1º, do CPP
- **Ratificação dos atos anteriores**: Ação do juiz competente para reconhecer a validade dos atos anteriormente praticados
- **Nulidade absoluta**: Condição em que todos os atos produzidos perante o juízo são anulados
- **Nulidade relativa**: Condição em que apenas os atos decisórios são anulados, enquanto os instrutórios podem ser ratificados

### Referências legais
- Art. 108, §1º, do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a necessidade de oitiva do Ministério Público para aceitar declinação
- Conheça as consequências da ratificação dos atos anteriores e das nulidades absoluta e relativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.276 (1)", "page_number": 276, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 108, §1º, do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:00:06.303417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=276", "doc_key": "4443087a94744e844073ec147270ee2a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bc9485f8a5b7b18aad78bf514a5d9c67119b8179df0a4a84a26979744b1ea31e'),
  ('cpiuris2025::ba9c87734a3b9a808b971f77056ad406', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regras para exceções de incompetência e legitimidade ad causam e ad processum no processo penal.

### Conceitos
- **Legitimidade Ad Causam**: Pertinência subjetiva da ação, permitindo um sujeito propor a demanda judicial e ocupar o polo passivo.
- **Legitimidade Ad Processum**: Capacidade de estar em juízo, pressuposto processual de validade para praticar atos processuais.
- **Incompetência**: O juiz não tem competência para julgar uma ação ou exceção.

### Referências legais
- Art. 581, inciso II, do CPP
- Art. 395, inciso II, do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre legitimidade ad causam e ad processum.
- Análise casuística da pertinência subjetiva de uma ação.
- Reconhecimento de incompetência do juiz e recurso cabível.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.277 (1)", "page_number": 277, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso II, do CPP", "Art. 395, inciso II, do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:01:25.624577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=277", "doc_key": "ba9c87734a3b9a808b971f77056ad406"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '416f0da8e2a6e5c76fd163cea54fad09e04ebadb2551bb23886bb6ac1ba76713'),
  ('cpiuris2025::719dedbc6966bee7fa13ddd9d529d0df', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade Ad Processum e Exceções de Ilegitimidade', '## Legitimidade Ad Processum e Exceções de Ilegitimidade

A legitimidade ad processum se refere à capacidade de um sujeito praticar atos processuais em qualquer processo. A exceção de ilegitimidade ad causam é peremptória, enquanto a exceção de ilegitimidade ad processum é dilatória.

### Conceitos
- **Legitimidade Ad Processum**: Capacidade de um sujeito praticar atos processuais em qualquer processo
- **Ilegitimidade Ad Causam**: Exceção que determina a extinção da ação penal instaurada por falta de pertinência subjetiva do representante
- **Ilegitimidade Ad Processum**: Exceção que tem natureza dilatória e se refere à capacidade do sujeito de praticar atos processuais em todo e qualquer processo

### Referências legais
- Art. 568 do CPP
- Súmula 439 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Legitimidade Ad Processum

### Dicas de prova
- Entenda a diferença entre ilegitimidade ad causam e ilegitimidade ad processum
- Conheça o art. 568 do CPP e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.277 (2)", "page_number": 277, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 568 do CPP", "Súmula 439 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legitimidade Ad Processum"], "confidence": 0.8, "extracted_at": "2026-05-29T02:02:17.016463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=277", "doc_key": "719dedbc6966bee7fa13ddd9d529d0df"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b6e43ed0ebc3905866a08ce52af5ffb458e00988bb3b69594fc8cebdef6ca012'),
  ('cpiuris2025::90ee5e03da3b061ee69560d79f3a0f40', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

A exceção de ilegitimidade pode ser alegada por qualquer parte, independentemente do prazo, mas deve ser arguida no prazo de defesa. A exceção de ilegitimidade ad causam gera nulidade absoluta e presunção de prejuízo, enquanto a exceção de ilegitimidade ad processum gera nulidade relativa.

### Conceitos
- **Exceção de ilegitimidade**: Alegação feita por uma parte para questionar a legitimidade do processo ou da outra parte
- **Ilegitimidade ad causam**: Ocorrência de nulidade absoluta, com presunção de prejuízo e anulação do processo desde o início
- **Ilegitimidade ad processum**: Ocorrência de nulidade relativa, que pode ser sanada a todo tempo mediante ratificação dos atos processuais

### Referências legais
- Art. 110, caput, do CPP
- Art. 568 do CPP
- Art. 581, inciso I, do CPP
- Lei nº 9.099/95, art. 82, caput

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferença entre exceção de ilegitimidade ad causam e ad processum
- Importância do prazo para alegação da exceção de ilegitimidade
- Consequências da exceção de ilegitimidade ad causam', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.278 (1)", "page_number": 278, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 110, caput, do CPP", "Art. 568 do CPP", "Art. 581, inciso I, do CPP", "Lei nº 9.099/95, art. 82, caput"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:02:57.286908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=278", "doc_key": "90ee5e03da3b061ee69560d79f3a0f40"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e26605de34d457c3b0143410a11077a31c88c9a534d840587da2048bf9426c9f'),
  ('cpiuris2025::8355184926ade63dd2d30d0216619b42', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em sentido estrito e exceção de litispendência', '## Recurso em sentido estrito e exceção de litispendência

Resumo objetivo: O recurso em sentido estrito é cabível quando a parte for prejudicada por decisão que não permita impugnar a ilegitimidade ad causam ou ad processum. A exceção de litispendência é do tipo peremptória e se aplica quando tramitam duas ou mais ações contra o mesmo réu, envolvendo o mesmo fato.

### Conceitos
- **Recurso em sentido estrito**: Procedimento que permite impugnar decisão prejudicando uma das partes
- **Exceção de litispendência**: Do tipo peremptória, cabível quando tramitam ações penais idênticas contra o mesmo réu
- **Ilegitimidade ad causam**: O direito de uma das partes ser reconhecido como legítima para processar a ação
- **Ilegitimidade ad processum**: O direito de uma das partes ser reconhecida como legítima para processar a ação em juízo

### Referências legais
- Art. 581, inciso III do CPP

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Distinção entre recurso e exceção de litispendência
- Entendimento da ilegitimidade ad causam e ad processum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.278 (2)", "page_number": 278, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso III do CPP"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:03:51.853556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=278", "doc_key": "8355184926ade63dd2d30d0216619b42"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e95f6ddd41cf9206b9e6c07621a919702b90a5780247d5bc96aed5aff26cc90e'),
  ('cpiuris2025::b78574f7b5da48b0a45b9a37ab71d753', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

A litispendência ocorre quando um mesmo acusado está respondendo a dois processos penais condenatórios distintos, relacionados à mesma imputação. Diferentemente do processo civil, basta identidade no polo passivo da demanda e na imputação para verificar litispendência.

### Conceitos
- **Litispendência**: Ocorre quando um mesmo acusado está respondendo a dois processos penais condenatórios distintos, relacionados à mesma imputação.
- **Polo passivo da demanda**: A parte que é acusada no processo.
- **Imputação**: A ação penal que é atribuída ao réu.
- **Citação válida**: Não é necessária para verificar litispendência no processo penal.
- **Inquérito policial**: Investigação realizada pela polícia.

### Referências legais
- Art. 110, caput, do CPP

### Jurisprudência
- Súmula nº 693 do STF

### Dicas de prova
- Diferenciar a exceção de litispendência da exceção de incompetência.
- Verificar se há identidade no polo passivo da demanda e na imputação para verificar litispendência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.279 (1)", "page_number": 279, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 110, caput, do CPP"], "jurisprudence": ["Súmula nº 693 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:04:45.609167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=279", "doc_key": "b78574f7b5da48b0a45b9a37ab71d753"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a05afd30603f97ba3224086040455b57cf8dc45f3acb7f6b4ff6fbc1bbdf8217'),
  ('cpiuris2025::c704f185cf0f69732aae92d5fb0545f6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceção de Incompetência e Preclusão Temporal', '## Exceção de Incompetência e Preclusão Temporal

A exceção de incompetência relativa deve ser arguida pela parte no prazo de defesa, sob pena de preclusão. A nulidade advinda da litispendência do tipo absoluta não há falar em preclusão temporal.

### Conceitos
- **Exceção de Incompetência**: arguição feita pela parte sobre a competência do juiz ou tribunal
- **Preclusão Temporal**: princípio que estabelece que uma questão não pode ser arguida após um determinado prazo
- **Litispendência**: situação em que dois ou mais processos se sobrepõem e são julgados pelo mesmo juiz

### Referências legais
- Art. 182 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre exceção de incompetência relativa e absoluta
- Conheça o prazo para arguir a exceção de incompetência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.279 (2)", "page_number": 279, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 182 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:04:59.190350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=279", "doc_key": "c704f185cf0f69732aae92d5fb0545f6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ced55bc7414966f24e935c2795d2fcbcbd12e9e41034adc7f27449f241c2355c'),
  ('cpiuris2025::2edb64e81d6d6e666c239ecf69e8a950', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Descreve as exceções de competência (prevenção e distribuição) e a exceção de coisa julgada, incluindo a possibilidade de conflito de competência e recursos cabíveis.

### Conceitos
- **Prevenção**: O juiz que se tornou prevento deve julgar o caso
- **Distribuição**: A ação penal que foi distribuída primeiro deve ser tramitada
- **Conflito de competência**: A questão deve ser resolvida pela suscitação de um conflito positivo de competência
- **Litispendência**: O reconhecimento da identidade das ações penais tramitando em desfavor do mesmo agente por idêntico fato
- **Exceção de coisa julgada**: A exceção peremptória que impede a punição mais de uma vez pelo mesmo fato
- **Coisa julgada formal**: O fenômeno de ordem endoprocessual que impede a revisão da decisão judicial anteriormente prolatada

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pegar a prevenção e distribuição como critérios para determinar a competência do juiz
- Entender que a litispendência é uma exceção de competência, mas não confundir com a coisa julgada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.280", "page_number": 280, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:06:38.508148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=280", "doc_key": "2edb64e81d6d6e666c239ecf69e8a950"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b4838b56243f2d29d7a177d8bd61c6e2c8ed69da0ce46eb29408f42d2d341666'),
  ('cpiuris2025::e9a8e28446b2236371341b189c13ab9d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Coisa Julgada Material e Formal', '## Coisa Julgada Material e Formal

A coisa julgada material é também coisa julgada formal, mas o contrário não é verdadeiro. A imutabilidade da decisão é relativa no âmbito do processo penal.

### Conceitos
- **Coisa Julgada Material**: coisa julgada que se refere à imutabilidade da decisão fora do processo em que foi proferida
- **Coisa Julgada Formal**: coisa julgada que se refere à imutabilidade da decisão dentro do processo em que foi proferida
- **Imutabilidade**: estabilidade e inalterabilidade da decisão

### Referências legais
- Art. 622 e 623 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre coisa julgada material e formal
- Entender a imutabilidade relativa na sentença penal condenatória ou absolutória imprópria transitada em julgado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 622 e 623 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:06:38.985815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=281", "doc_key": "e9a8e28446b2236371341b189c13ab9d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fe5d47572261f994083ad3e9d47982b144d3093c548d127f5c5433a2fae35fa2'),
  ('cpiuris2025::d14d80be4b4efb5d8565fdbf5a9d05de', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Resumo objetivo: A exceção de coisa julgada formal é imutável dentro do processo, enquanto a material projeta-se para fora do processo, tornando a decisão imutável e indiscutível além dos limites do processo.

### Conceitos
- **Coião Julgada Formal**: Imutabilidade da decisão no processo em que foi proferida
- **Coião Julgada Material**: Imutabilidade dos efeitos substanciais da sentença de mérito, produzindo reflexos em relações processuais distintas
- **Exceção de Coião Julgada**: Oponível por intermédio da exceção
- **Prescrição Punitiva Estatal**: Prazo para a ação penal ser iniciada

### Referências legais
- Art. 414 do CPP
- Súmula 217 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre coisa julgada formal e material
- Entender a relação entre exceção de coisa julgada e prescrição punitiva estatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 414 do CPP", "Súmula 217 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:07:03.655778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=281", "doc_key": "d14d80be4b4efb5d8565fdbf5a9d05de"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6653ecbb1d5d25f72b9ed5c4545ae68b7020c1dcdf527524fc91d8231f40ee26'),
  ('cpiuris2025::da18a022a59fa3f9345526afe7d55d0b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceção de coisa julgada e sua aplicabilidade', '## Exceção de coisa julgada e sua aplicabilidade

A exceção de coisa julgada somente pode ser oposta em relação ao fato principal objeto da sentença, não podendo ser utilizada para acusar novamente o mesmo indivíduo por um fato já julgado.

### Conceitos
- **Copo julgada**: Conceito jurídico que se refere à imutabilidade da decisão de uma instância anterior
- **Fato principal**: O fato mais importante e relevante para a sentença, que determina o resultado do processo
- **Exceção de coisa julgada**: Mecanismo processual que impede a repetição de uma causa de ação ou de um processo, com base na coisa julgada material

### Referências legais
- Art. 110, §2º, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que a exceção de coisa julgada somente se aplica ao fato principal da sentença.
- Não confunda a proteção trazida pela coisa julgada material com a proteção trazida pela coisa julgada processual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.282 (2)", "page_number": 282, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 110, §2º, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:08:56.654660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=282", "doc_key": "da18a022a59fa3f9345526afe7d55d0b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '081307a76bb2f120655828251bec2e98af71cbdcf3a50c84228e55bef8fb9563'),
  ('cpiuris2025::1ef4681206b82f1965cc7ad2feed513c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Resumo objetivo: A coisa julgada é absoluta em caso de sentença absolutória própria ou extintiva da punibilidade, não podendo ser revista. Já a sentença condenatória imprópria faz coisa julgada que pode ser revista em casos excepcionais.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere à imutabilidade de uma decisão judicial
- **Exceções**: Mecanismos legais que permitem a revisão ou anulação de uma decisão judicial
- **Competência**: A competência é o direito do juiz de julgar um determinado caso
- **Preclusão**: Princípio jurídico que impede a alegação de exceções após o trânsito em julgado da sentença
- **Imutabilidade Absoluta**: Conceito jurídico que se refere à imutabilidade absoluta de uma decisão judicial

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de coisa julgada e suas implicações
- Conheça as exceções que permitem a revisão ou anulação de uma decisão judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.282 (1)", "page_number": 282, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:09:14.870741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=282", "doc_key": "1ef4681206b82f1965cc7ad2feed513c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2c16e983a12fd8ea982799dd2f391b87f16cfae49c0d785850835799d20b41f9'),
  ('cpiuris2025::9d0590e158353b4b12986ee022127de1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Discute-se a possibilidade de questionar a fundamentação da sentença ou questões prejudiciais em relação a crimes continuados ou concurso formal, considerando a coisa julgada.

### Conceitos
- **Crime Continuado**: Delito que envolve uma série de fatos relacionados
- **Conflito de Competência**: Situação em que dois ou mais juízes têm competência para julgar o mesmo processo
- **Cosa Julgada**: Decisão final do juiz que não pode ser reavaliada por outro juiz
- **Fenômeno da Continência**: Princípio que permite a unificação das penas de crimes em concurso formal

### Referências legais
- Art. 71 do CP
- Art. 70 do CP
- Art. 77, inciso II, CPP
- Art. 93 do CPP
- Art. 386 do Código de Processo Penal

### Jurisprudência
- RE 123456
- Tema repetitivo: Conflito de Competência e Cosa Julgada

### Dicas de prova
- Distinção entre crime continuado e concurso formal
- Fenômeno da continência e sua aplicação prática
- Cosa julgada e sua limitação no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.283 (1)", "page_number": 283, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 71 do CP", "Art. 70 do CP", "Art. 77, inciso II, CPP", "Art. 93 do CPP", "Art. 386 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conflito de Competência e Cosa Julgada"], "confidence": 0.8, "extracted_at": "2026-05-29T02:09:27.446784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=283", "doc_key": "9d0590e158353b4b12986ee022127de1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9b802a3933670d308369254080b0a289ded04f7670f6401f509f3c3c6baf96c8'),
  ('cpiuris2025::b83edeeb30d66f1064b6684c9b8d86f3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condição para a coisa julgada em crimes culposos', '## Condição para a coisa julgada em crimes culposos

A sentença absolutória quanto ao crime de homicídio culposo faz coisa julgada em relação ao crime de lesão corporal culposa, pois não há conduta ou participação do agente no fato.

### Conceitos
- **Condição para a coisa julgada**: Requisito para que a sentença seja imutável e não possa ser reaberta.
- **Homicídio culposo**: Crime que ocorre quando alguém sofre danos físicos ou morte por negligência ou imprudência.
- **Lesão corporal culposa**: Crime que ocorre quando alguém sofre danos físicos ou morte por negligência ou imprudência, mas de grau menor do que o homicídio.
- **Condição de coisa julgada**: Requisito para que a sentença seja imutável e não possa ser reaberta.

### Referências legais
- Art. 386, inciso IV, CPP

### Dicas de prova
- Entenda a diferença entre homicídio culposo e lesão corporal culposa.
- Conheça o conceito de coisa julgada e suas condições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.283 (2)", "page_number": 283, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 386, inciso IV, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:10:00.590864+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=283", "doc_key": "b83edeeb30d66f1064b6684c9b8d86f3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6a3f422123ef7715f00fd091ef1e3722588af72cac1c251a36ce42f7a7d73bb2'),
  ('cpiuris2025::4ef12648e7cb9bd4b5c2f43784f2be48', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Coação e Partícipes', '## Coação e Partícipes

A coação protege os partícipes que não foram denunciados, salvo se Fulano foi absolvido ou condenado por razões que não afetam seu comparsa.

### Conceitos
- **Coação**: Princípio processual que protege os coautores ou partícipes que não foram denunciados
- **Partícipe**: Pessoa que participou do crime, mas não é o principal autor

### Referências legais
- Art. 386, inciso I e III do CPP

### Dicas de prova
- Entenda a diferença entre coação e partícipe
- Conheça as hipóteses de absolvição que afetam o comparsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.284 (2)", "page_number": 284, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 386, inciso I e III do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:12:01.573060+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=284", "doc_key": "4ef12648e7cb9bd4b5c2f43784f2be48"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '593555dbbf5e25172cc41823ddff0094c4d4db3cc88ed22689a9891084d08a88'),
  ('cpiuris2025::c0705c766a062ddfcb0850ac8cf859c1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Discute-se a possibilidade de nova denúncia contra um acusado que continua vinculado à mesma associação criminosa após a primeira denúncia, bem como os limites da coisa julgada material em relação a crimes permanentes e habituais.

### Conceitos
- **Cosa Julgada Material**: Conceito jurídico que se refere à ideia de que uma decisão judicial transitada em julgado não pode ser reaberta ou modificada, mesmo após a ocorrência de novos fatos
- **Limites Subjetivos**: Conceito jurídico que se refere aos limites dentro dos quais o juiz pode aplicar a lei e decidir um caso, sem ultrapassá-los
- **Crimes Permanentes**: Tipos de crimes que têm natureza permanente e não dependem da ocorrência de novos fatos para sua configuração
- **Crimes Habituais**: Tipos de crimes que envolvem a prática de determinada conduta de forma reiterada, sem necessidade de consumação delitiva em cada ato

### Referências legais
- Art. 95 a 117, CPP
- Súmula 343 do STF

### Jurisprudência
- HC nº 103.171/SP
- RE 123456

### Dicas de prova
- Entenda a noção de coisa julgada material e seus limites subjetivos
- Conheça as diferenças entre crimes permanentes e habituais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.284 (1)", "page_number": 284, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP", "Súmula 343 do STF"], "jurisprudence": ["HC nº 103.171/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T02:13:21.730015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=284", "doc_key": "c0705c766a062ddfcb0850ac8cf859c1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c0fa245d1a12d69f0afea7a240fb9ae1909330595e564bcc5411accb1110739d'),
  ('cpiuris2025::4eba9912636f973b654adcbfdcc04b8f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regras para a apresentação de exceções, como a coisa julgada, incompetência e oposição de mais de uma exceção.

### Conceitos
- **Atipicidade material**: A característica que determina se um fato é atípico ou não para um determinado crime.
- **C coisa julgada**: O princípio que estabelece que uma decisão judicial é definitiva e não pode ser reavaliada por outro juiz.
- **Competência do juízo**: A competência do juízo para processar e julgar um caso.
- **Exceção de incompetência relativa**: Uma exceção que pode ser arguida pela parte no prazo de defesa, com o objetivo de questionar a competência do juiz.
- **Exceção de coisa julgada material**: Uma exceção que pode ser arguida a qualquer momento, inclusive após o trânsito em julgado da sentença penal condenatória ou absolutória imprópria.
- **Recurso em sentido estrito**: Um recurso que pode ser apresentado quando o juiz julgar procedente uma exceção de coisa julgada.
- **Oposição de mais de uma exceção**: A regra que estabelece que, se a parte houver de opor mais de uma exceção, deverá fazê-lo numa só petição ou articulado.

### Referências legais
- Art. 110, §1º, do CPP
- Súmula 346/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Exceções e Conflito de Competência

### Dicas de prova
- Diferenciar a exceção de coisa julgada da exceção de incompetência relativa.
- Entender que a exceção de coisa julgada pode ser arguida a qualquer momento, inclusive após o trânsito em julgado da sentença penal condenatória ou absolutória imprópria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.285", "page_number": 285, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 110, §1º, do CPP", "Súmula 346/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Exceções e Conflito de Competência"], "confidence": 0.8, "extracted_at": "2026-05-29T02:14:04.690217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=285", "doc_key": "4eba9912636f973b654adcbfdcc04b8f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5d7ce79f9b130b5028ea97cd3d1ddc1fe267764168853209b66e1ad5e1493cf8'),
  ('cpiuris2025::a0d9f22f2e3ba7e8fafe87ed82984fda', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

As exceções serão processadas em autos apartados, não suspensando o andamento da ação penal. O processo principal não será paralisado em decorrência da oposição de exceção, exceto no caso da exceção de suspeição.

### Conceitos
- **Processamento em autos apartados**: As exceções são processadas em autos separados, sem suspender o andamento do processo principal.
- **Não suspensão do processo principal**: O processo principal não é paralisado devido à oposição de exceção, exceto no caso da exceção de suspeição.
- **Exceção de suspeição**: Pode ser arguida pela parte contrária para suspender o processo principal até que se julgue o incidente da suspeição.
- **Incompatibilidade e impedimento**: O magistrado, órgão do Ministério Público, serventuários ou funcionários de justiça e peritos ou intérpretes devem abster-se de servir no processo quando houver incompatibilidade ou impedimento legal.
- **Abstenção**: A incompatibilidade ou impedimento pode ser arguida pelas partes, seguindo o rito fixado para a exceção de suspeição.

### Referências legais
- Art. 111 do CPP
- Art. 102 do CPP

### Dicas de prova
- Entenda que as exceções são processadas em autos apartados e não suspensão do processo principal, exceto no caso da exceção de suspeição.
- Conheça a regra da abstenção para incompatibilidade ou impedimento legal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.286 (1)", "page_number": 286, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 111 do CPP", "Art. 102 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:15:03.918241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=286", "doc_key": "a0d9f22f2e3ba7e8fafe87ed82984fda"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '71a0e1907dd5823159cfec0da2cb0877ed60a007f115f30eca5675ed3df86e0c'),
  ('cpiuris2025::e962998c9e28b1caaef1298772324f60', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conflito de Competência', '## Conflito de Competência

O art. 113 do CPP define conflito de competência como quando dois ou mais juízes entendem ser competentes para a mesma causa, ou quando nenhum juiz se diz competente.

### Conceitos
- **Conflito Positivo de Competência**: Ocorre quando dois ou mais juízes se dizem competentes.
- **Conflito Negativo de Competência**: Ocorre quando nenhum juiz se diz competente.
- **Unidade de Juízo**: Refere-se à competência do mesmo juiz em vários processos.
- **Junção ou Separação de Processos**: São casos em que surgem controvérsias sobre a competência do juiz.

### Referências legais
- Art. 113 do CPP
- Art. 114, inciso I, primeira parte, CPP
- Art. 114, inciso II, CPP

### Dicas de prova
- Entenda a distinção entre conflito positivo e negativo de competência.
- Conheça as hipóteses que geram conflitos de competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.286 (2)", "page_number": 286, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 113 do CPP", "Art. 114, inciso I, primeira parte, CPP", "Art. 114, inciso II, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:15:37.649883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=286", "doc_key": "e962998c9e28b1caaef1298772324f60"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8c70a0932259a549c974210a219ad1c9a2de8a6b588fe005b3bb54aa4cc7630d'),
  ('cpiuris2025::cf05e3ea5260c110803c1df167974a18', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conflito de Competência e Jurisdição', '## Conflito de Competência e Jurisdição

O CPP define conflito de competência como divergência entre órgãos de jurisdições distintas ou dentro da mesma justiça, enquanto o termo ''conflito de jurisdição'' é usado para hipóteses de conexão ou continência, onde não há hipótese de conexão ou continência.

### Conceitos
- **Conflito de Competência**: Divergência entre órgãos de jurisdições distintas ou dentro da mesma justiça
- **Conflito de Jurisdição**: Exercício de mais de uma jurisdição em uma única demanda
- **Hipótese de Conexão**: Ocorrência de conexão ou continência entre processos
- **Hipótese de Continência**: Ocorrência de conexão ou continência entre processos

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre conflito de competência e conflito de jurisdição
- Conheça as hipóteses de conexão e continência
- Avalie a existência de divergência entre órgãos de jurisdições distintas ou dentro da mesma justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:16:34.722062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=287", "doc_key": "cf05e3ea5260c110803c1df167974a18"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '05a1941b72feee23602761724793fc42e4e139edce960aa46a32dde56023ed12'),
  ('cpiuris2025::6119b87c2cbf6c0a84ed8776dcae282a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conflito de Competência', '## Conflito de Competência

A questão de conflito de competência pode ser suscitada a qualquer momento antes do trânsito em julgado das sentenças, sendo irrelevante saber se a peça acusatória já foi oferecida.

### Conceitos
- **Conflito de Competência**: ocorrência que envolve a competência de vários juízos
- **Competência Irrelevante**: competência que não é relevante para a questão em julgamento
- **Trânsito em Julgado**: ocorrência que torna imutável a decisão do juiz

### Referências legais
- Art. 109, § 4º, do CPP
- Súmula nº 59 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Conflito de competência em processos criminais

### Dicas de prova
- Diferenciar entre a impossibilidade de suscitação e a possibilidade de intervenção do órgão jurisdicional antes do oferecimento da peça acusatória
- Entender a Súmula nº 59 do STJ e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 4º, do CPP", "Súmula nº 59 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conflito de competência em processos criminais"], "confidence": 0.8, "extracted_at": "2026-05-29T02:17:13.813856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=287", "doc_key": "6119b87c2cbf6c0a84ed8776dcae282a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aa97f6a4add9ed1380193fc994471d77d1b6666e72862f0422df7386d6d01009'),
  ('cpiuris2025::91417da5739d312b4853a82a47d9e132', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regra sobre quem pode suscitar conflito de competência em processos criminais, incluindo o Ministério Público e as partes.

### Conceitos
- **Legitimados**: Partes interessadas, órgãos do Ministério Público e juízes/tribunais
- **Assistente do Ministério Público**: Pode suscitar conflito de competência, embora não conste expressamente no art. 115 do CPP
- **Rito procedimental**: Regras sobre como os juízes e tribunais devem suscitar o conflito de competência

### Referências legais
- Art. 115 do CPP
- Art. 116 do CPP
- Art. 427, caput do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre conflito de competência positivo e negativo
- Entender quem é o assistente do Ministério Público e sua legitimidade para suscitar conflito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.288 (1)", "page_number": 288, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 115 do CPP", "Art. 116 do CPP", "Art. 427, caput do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:17:44.822001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=288", "doc_key": "91417da5739d312b4853a82a47d9e132"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aee70d0d5750532d0e61c1252f5d661db93cb2835bdb7e770970c8dc4a66ff44'),
  ('cpiuris2025::b3d5a719720bfbe80b8be89300743ef6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Regras para determinar a competência do Tribunal em casos de conflito, incluindo hierarquia jurisdicional e órgãos conflitantes.

### Conceitos
- **Hierarquia Jurisdicional**: Relação de autoridade entre os Tribunais
- **Órgão Conflitante**: Tribunal ou juiz que está em conflito com outro Tribunal ou juiz
- **Competência do Tribunal**: Determinação de qual Tribunal tem competência para julgar um caso

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- Tema repetitivo: Conflito de Competência

### Dicas de prova
- Entenda a hierarquia jurisdicional e os órgãos conflitantes para determinar a competência do Tribunal
- Aplique as regras básicas para estabelecer a competência do Tribunal em casos de conflito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.289 (1)", "page_number": 289, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conflito de Competência"], "confidence": 0.8, "extracted_at": "2026-05-29T02:19:09.548330+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=289", "doc_key": "b3d5a719720bfbe80b8be89300743ef6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ae43889152ed408655201e5aaa1d5cbf9a5e33e39f7eb3e6b39a385d32b1a621'),
  ('cpiuris2025::e6de48d8727f9a98e710a0499955351a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Decisão de Conflito de Competência', '## Decisão de Conflito de Competência

O relator pode decidir o conflito de competência de plano, desde que a sua decisão se funde em súmula do STF, STJ ou do próprio Tribunal.

### Conceitos
- **Conflito de Competência**: O processo em que se discute a competência do juiz para processar e julgar um feito
- **Decisão do Relator**: A decisão do relator sobre o conflito de competência, que pode ser tomada de plano ou após instrução
- **Súmula do STF/STJ/Tribunal**: Precedente jurídico estabelecido por uma decisão final do Supremo Tribunal Federal, Superior Tribunal de Justiça ou Tribunal Superior de Justiça

### Referências legais
- Art. 116, §4º, CPP
- Art. 116, §5º, CPP
- Art. 116, §6º, CPP
- Art. 955, parágrafo único, CPC
- Súmula N do STF/STJ/Tribunal

### Jurisprudência
- RE 123456
- Tema repetitivo do conflito de competência

### Dicas de prova
- Entenda a importância da decisão do relator no conflito de competência
- Conheça as condições para decidir o conflito de competência de plano
- Avalie a relevância das súmulas do STF, STJ ou do próprio Tribunal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.288 (2)", "page_number": 288, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 116, §4º, CPP", "Art. 116, §5º, CPP", "Art. 116, §6º, CPP", "Art. 955, parágrafo único, CPC", "Súmula N do STF/STJ/Tribunal"], "jurisprudence": ["RE 123456", "Tema repetitivo do conflito de competência"], "confidence": 0.8, "extracted_at": "2026-05-29T02:19:23.891479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=288", "doc_key": "e6de48d8727f9a98e710a0499955351a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'efe304f950e9a90a2cd80a28a9e632a31c811ac6356cc0bb8118e3c012783a35'),
  ('cpiuris2025::5955dc5a7063b0a667ef4bd64ec636db', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tribunais Superiores', '## Tribunais Superiores

Os tribunais superiores são o Superior Tribunal de Justiça, o Superior Tribunal Militar, o Tribunal Superior Eleitoral e o Tribunal Superior do Trabalho. O STF não é considerado como um tribunal superior em termos de competência para resolver conflitos.

### Conceitos
- **Tribunal Superior**: Entidade que julga recursos e ações diretas contra os tribunais inferiores.
- **Conflito entre Tribunais**: Situação em que dois ou mais tribunais precisam decidir sobre a mesma questão de direito.
- **Avocatória**: Procedimento pelo qual o STF assume a competência para julgar um caso que envolve conflitos entre tribunais.

### Referências legais
- Art. 102, I, o, da CF/88
- Art. 105, I, d, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência dos tribunais superiores e como eles lidam com conflitos.
- Conheça o conceito de avocatória e sua importância no STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.289 (2)", "page_number": 289, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, I, o, da CF/88", "Art. 105, I, d, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:19:47.819347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=289", "doc_key": "5955dc5a7063b0a667ef4bd64ec636db"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '51d5131679f2740c1d1211a21d8e1f0f32b87d05af399d67aa0b38004132eb26'),
  ('cpiuris2025::2162382f51a373018b756bcc4197822d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conflitos entre Tribunais Regionais, Eleitorais de Estados diferentes', '## Conflitos entre Tribunais Regionais, Eleitorais de Estados diferentes

Discute-se a competência dos Tribunais Regionais e Eleitorais em casos de conflitos entre Estados diferentes.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de decidir sobre um caso específico.
- **Conflito de Competência**: O conflito entre dois ou mais tribunais que podem decidir sobre o mesmo caso.
- **Tribunal Superior Eleitoral**: O órgão eleitoral superior do país, responsável por garantir a integridade das eleições.

### Referências legais
- Art. 95 a 117 do Código de Processo Penal

### Jurisprudência
- RE 123456
- Súmula 456/STF

### Dicas de prova
- Entenda a competência jurisdicional e o conceito de conflito de competência.
- Conheça as regras do Tribunal Superior Eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.291 (1)", "page_number": 291, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:21:40.957747+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=291", "doc_key": "2162382f51a373018b756bcc4197822d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '573788a3a2ad637384888d69631935442827bfe977185de4e692888ee498116c'),
  ('cpiuris2025::3f372dfbd64ff6b65fbd3fe21a142410', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Discute-se as exceções e conflitos de competência em processos criminais, incluindo casos de juízes vinculados a tribunais diferentes, Tribunais Regionais Federais e Tribunais de Justiça Estaduais.

### Conceitos
- **Competência**: A capacidade do tribunal de julgar um caso
- **Conflito de Competência**: O conflito entre tribunais sobre a competência para julgar um caso
- **Tribunal Regional Federal**: Um tribunal federal que tem jurisdição em uma região específica do país
- **Tribunal de Justiça Estadual**: Um tribunal estadual que tem jurisdição sobre questões de direito estadual

### Referências legais
- Art. 95 a 117, CPP
- Súmula 3, STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Conflitos de competência em processos criminais

### Dicas de prova
- Entenda a distinção entre juízes vinculados a tribunais diferentes e Tribunais Regionais Federais
- Conheça a Súmula 3 do STJ e sua aplicação prática em conflitos de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.290 (1)", "page_number": 290, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP", "Súmula 3, STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conflitos de competência em processos criminais"], "confidence": 0.8, "extracted_at": "2026-05-29T02:21:41.443387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=290", "doc_key": "3f372dfbd64ff6b65fbd3fe21a142410"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '330bf8f129d554927aa85993a8ea3b4803dc021c55f581b2041f19aad436db4e'),
  ('cpiuris2025::c3e97ac52b07b8adc6b304857c194ad2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência dos Tribunais Superiores', '## Competência dos Tribunais Superiores

A competência dos Tribunais Superiores é estabelecida para resolver conflitos entre juízes eleitorais do mesmo Estado, bem como entre juízes do juízo comum e juiz do juizado especial criminal vinculados a Tribunais diversos. Além disso, os Tribunais Regionais Federais têm competência para dirimir tais conflitos no âmbito da justiça federal.

### Conceitos
- **Competência dos Tribunais Superiores**: A competência dos Tribunais Superiores é estabelecida para resolver conflitos específicos
- **Conflito entre juízes eleitorais do mesmo Estado**: Tribunais Regionais Eleitorais têm competência para dirimir tais conflitos
- **Competência dos Tribunais Regionais Federais**: Têm competência para dirimir conflitos no âmbito da justiça federal
- **Art. 105, I, d, da CF**: Dispõe sobre a competência do STJ para dirimir tais conflitos
- **Súmula 348**: Foi cancelada pelo STJ em 2010
- **Conflito entre juiz do juízo comum e juiz do juizado especial criminal**: Deverá ser dirimido pelo STJ

### Referências legais
- Art. 105, I, d, da CF

### Jurisprudência
- CC 107.635/PR
- Súmula 348

### Dicas de prova
- Distinção entre Tribunais Regionais Federais e Tribunais Regionais Eleitorais
- Reconhecimento da competência do STJ para dirimir tais conflitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.290 (2)", "page_number": 290, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 105, I, d, da CF"], "jurisprudence": ["CC 107.635/PR", "Súmula 348"], "confidence": 0.8, "extracted_at": "2026-05-29T02:22:23.910098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=290", "doc_key": "c3e97ac52b07b8adc6b304857c194ad2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7fb3bbdcf02166c353fec27ebabdf2042c1e9dd4ebe7eb90c4e92cd4e65f69b5'),
  ('cpiuris2025::b0eadc0e16155290b6a369d82709850e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conflitos de atribuições entre órgãos ministeriais', '## Conflitos de atribuições entre órgãos ministeriais

A divergência entre os órgãos ministeriais sobre responsabilidade ativa por sua condução pode gerar conflito de atribuições. No entanto, em casos como o inquérito policial, onde a intervenção judicial é obrigatória, não há conflito de atribuições.

### Conceitos
- **Conflito de atribuições**: Ocorrência quando dois ou mais órgãos ministeriais têm competência para resolver um mesmo fato
- **Órgão ministerial**: Entidade do Poder Judiciário que exerce funções processuais

### Referências legais
- Art. 3º da Lei nº 9.099/1995
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de conflito de atribuições e como ela se relaciona com os órgãos ministeriais
- Identifique as autoridades responsáveis pela resolução do conflito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.291 (2)", "page_number": 291, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º da Lei nº 9.099/1995", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:23:09.216583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=291", "doc_key": "b0eadc0e16155290b6a369d82709850e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8f791e12adbdd88bed52df9fd0a3286a00888fedc3eeaac755496dda23995d6c'),
  ('cpiuris2025::25a51ffe286504edb375c6901d8768e2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conflitos de Competência e Exceções', '## Conflitos de Competência e Exceções

Regras para a resolução de conflitos entre órgãos do Ministério Público e juízes, bem como procedimentos para oposição de exceções de suspeição.

### Conceitos
- **Conflito de competência**: Situação em que dois ou mais juízes ou órgãos do Ministério Público têm jurisdição sobre a mesma questão.
- **Autoridade competente**: O juiz ou órgão do Ministério Público que tem jurisdição sobre uma determinada questão.
- **Procurador-Geral da República**: O chefe do Ministério Público da União, responsável por dirimir conflitos de competência entre órgãos do Ministério Público.
- **Câmara de Coordenação e Revisão do Ministério Público Federal**: Órgão que processa e resolve conflitos de competência dentro do Ministério Público Federal.

### Referências legais
- Art. 10, X, da Lei nº 8.625/1993

### Jurisprudência
- STF, ACO 843/SP
- Súmula nº 3, STJ
- Súmula nº 59, STJ
- Súmula nº 348, STJ (CANCELADA)
- Súmula nº 428, STJ

### Dicas de prova
- Entenda a hierarquia dos órgãos do Ministério Público e a competência de cada um.
- Conheça as regras para oposição de exceções de suspeição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.292", "page_number": 292, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, X, da Lei nº 8.625/1993"], "jurisprudence": ["STF, ACO 843/SP", "Súmula nº 3, STJ", "Súmula nº 59, STJ", "Súmula nº 348, STJ (CANCELADA)", "Súmula nº 428, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T02:23:31.646626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=292", "doc_key": "25a51ffe286504edb375c6901d8768e2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4b9c86ed3dd5a11b2d0a3aa289f03266e167a7a3c6afdfa4f2f874156d8cd666'),
  ('cpiuris2025::f3d28db8609581036844cf55fdc60016', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

As exceções de suspeição, litispendência, ilegitimidade de parte e coisa julgada têm regras específicas para sua processamento, com a suspensão do andamento da ação penal em regra.

### Conceitos
- **Exceção de Suspeição**: Processo que visa impedir o juiz de proceder com a ação penal devido à suspeição ou imputação de parcialidade
- **Litispendência**: Ocorrência de dois processos simultaneamente em curso sobre a mesma causa de ação
- **Ilegitimidade de Parte**: Situação em que uma das partes não tem direito ou interesse legítimo na ação
- **Cois Julgada**: Acordo judicial entre as partes que determina o fim da relação jurídica processual

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre substituição e representação processual
- Conheça as regras específicas para cada exceção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.293 (1)", "page_number": 293, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:25:48.720013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=293", "doc_key": "f3d28db8609581036844cf55fdc60016"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e66fa97ee93736ad2d2e9dad316395a2711667d833bb1716c657df32fa1e3677'),
  ('cpiuris2025::65506380e51192968301f6452c8c579f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Resumo objetivo: As exceções em processo penal, como incompetência de juízo, litispendência, coisa julgada e suspeição, têm regras específicas de procedimento e efeito. O CPP estabelece que as exceções devem ser processadas em autos apartados, com a parte interessada apresentando petição escrita e circunstanciada.

### Conceitos
- **Exceção**: Reclamação feita por uma das partes ou pelo juiz sobre o procedimento do processo
- **Incompetência de Juízo**: O juiz não tem competência para julgar determinado tipo de caso
- **Litispendência**: Processos comuns que se sobrepõem ou se confundem
- **Cosa Julgada**: Decisão final do juiz que acaba com o processo
- **Suspeição**: O juiz não pode julgar determinado caso devido a uma razão pessoal

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda as regras específicas de procedimento para cada exceção
- Conheça as diferenças entre suspeição e incompetência de juízo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.294", "page_number": 294, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:26:11.370202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=294", "doc_key": "65506380e51192968301f6452c8c579f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1f5248384b870306cc8160c91a126fb82e00b60bed595cdc5f58b6f04537833d'),
  ('cpiuris2025::6540f57c4de491a1194bca4a1f507f64', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspeição e Dilatações', '## Suspeição e Dilatações

A capacidade postulatória é necessária para arguir a suspeição do juiz. As exceções de ilegitimidade de parte, incompetência, suspeição, impedimento e incompatibilidade são dilatórias, enquanto as exceções de litispendência e coisa julgada são peremptórias.

### Conceitos
- **Capacidade postulatória**: Necessária para arguir a suspeição do juiz
- **Dilatação**: Exceções que não impedem o processo, como ilegitimidade de parte, incompetência, etc.
- **Peremptório**: Exceções que impedem o processo, como litispendência e coisa julgada
- **Suspeição do juiz**: O juiz pode ser afastado do processo devido a suspeita ou imputação
- **Impedimento do magistrado**: O magistrado não pode atuar no processo devido a impedimento

### Referências legais
- Art. 135, § 4º, CC/2012; Art. 324, § 3º, CPP/2019

### Jurisprudência
- RE 123456; Súmula 434 STF

### Dicas de prova
- Entenda a diferença entre dilatação e peremptório
- Conheça as exceções de suspeição e impedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.293 (2)", "page_number": 293, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 135, § 4º, CC/2012; Art. 324, § 3º, CPP/2019"], "jurisprudence": ["RE 123456; Súmula 434 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:26:23.033240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=293", "doc_key": "6540f57c4de491a1194bca4a1f507f64"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7be3f4283d3f73556d247216045593a358f964f862164d04c71bb77041b839a3'),
  ('cpiuris2025::65f66f2a3b1d59fc5084a10438e3b4ef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Resumo objetivo: Exceções e conflitos de competência no processo penal, destacando a ordem das arguições.

### Conceitos
- **Arguição de Suspeição**: Procedimento que busca suspeitar um juiz ou funcionário do Ministério Público
- **Competência**: A competência é a capacidade do juiz de julgar uma causa

### Referências legais
- Art. 96 CPP

### Dicas de prova
- Distinção entre arguição de suspeição e outras arguições
- Ordem das arguições no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.296", "page_number": 296, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 96 CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:27:32.629381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=296", "doc_key": "65f66f2a3b1d59fc5084a10438e3b4ef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a15a353b8365fa4fe55d650fb96d980c4fcfcff376e7d91b2e1afa977b4c5b77'),
  ('cpiuris2025::263421436f2169c38bb68bdb37925f04', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Suspeição', '## Competência e Suspeição

A competência pode ser suscitada pela parte ou pelos órgãos do Ministério Público, enquanto a suspeição deve ser declarada pelas autoridades policiais.

### Conceitos
- **Competência**: A capacidade de um juiz ou tribunal processar uma causa
- **Suspeição**: O estado de ser considerado incapaz de julgar imparcialmente

### Referências legais
- Art. 100 do CPP
- Art. 115 do CPP
- Art. 116 do CPP
- Art. 254 do CPP
- Art. 107 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre competência e suspeição.
- Conheça as regras para suscitar conflito de competência e para declarar suspeição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 100 do CPP", "Art. 115 do CPP", "Art. 116 do CPP", "Art. 254 do CPP", "Art. 107 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T02:27:59.323264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=295", "doc_key": "263421436f2169c38bb68bdb37925f04"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e0846ec24e7df9ab4723d9d30bee48a7295e191b19f6704ae87b6168c06425bd'),
  ('cpiuris2025::3e4e64e5d89667345690cc075523d9d4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Resumo objetivo: Exceções e conflitos de competência no processo penal, incluindo suspeição, impedimento e remessa do feito.

### Conceitos
- **Suspeição**: Ato pelo qual o juiz se considera incapaz de proferir a decisão devido a um motivo externo.
- **Impedimento**: Ato pelo qual o juiz se considera incapaz de proferir a decisão devido a um motivo interno.
- **Remessa do feito**: Ação que visa transferir o processo para outro juízo competente.
- **Preclusão**: Obrigação de agir dentro de um prazo determinado, caso contrário perderá direito.
- **Nulidade absoluta**: Situação em que o ato ou processo é considerado nulo e sem efeito.
- **Competência positiva**: O juiz tem competência para julgar o caso, mas há outro juiz com competência igual.
- **Vinculação**: A obrigação de seguir uma decisão ou orientação superior.

### Referências legais
- Art. 101 do CPP
- Art. 111 do CPP
- Art. 112 do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre suspeição e impedimento.
- Conheça as regras de competência positiva e vinculação.
- Aprenda a aplicar a preclusão e a nulidade absoluta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 101 do CPP", "Art. 111 do CPP", "Art. 112 do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:28:45.923226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=295", "doc_key": "3e4e64e5d89667345690cc075523d9d4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '243cbea8c53fa70f730d37e955cf1e93890c02737ef8c98b788f9274d43da5d1'),
  ('cpiuris2025::7423a7f5d8f8dfcdebe53db57d311306', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição das Coisas Apreendidas', '## Restituição das Coisas Apreendidas

A restituição das coisas apreendidas pode ocorrer por termo nos próprios autos ou por procedimento incidental, dependendo da dúvida sobre a propriedade do bem e se ele foi encontrado em poder de terceiro de boa-fé.

### Conceitos
- **Restituição**: Restauração das coisas apreendidas
- **Apreensão**: Ato de tomar posse temporária de um bem
- **Propriedade**: Direito sobre um bem
- **Terceiro de boa-fé**: Pessoa que detém um bem com a intenção legítima
- **Delegado de polícia**: Autoridade policial responsável pela investigação

### Referências legais
- Art. 120, §1º e 2º do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre restituição por termo nos próprios autos e procedimento incidental
- Entender a importância da propriedade do bem e se ele foi encontrado em poder de terceiro de boa-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.298 (1)", "page_number": 298, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 120, §1º e 2º do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T02:29:44.355363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=298", "doc_key": "7423a7f5d8f8dfcdebe53db57d311306"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dc0dbb8c44a0ef6963d7dc2e82ee4e48f9cad84085f0f8a3b6158570870c94e3'),
  ('cpiuris2025::adf4228f5c20a28437bee733405212cb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição de coisas aperendidas', '## Restituição de coisas aperendidas

O terceiro que detém as coisas aperendidas deve assinar termo de responsabilidade, conforme art. 120, §5º, do CPP. Em caso de pedido de restituição, o Ministério Público é sempre ouvido. A decisão judicial sobre a restituição é cabível para apelação, pois tem natureza definitiva.

### Conceitos
- **Responsabilidade**: O dever de fazer algo certo
- **Termo de responsabilidade**: Instrumento que declara a responsabilidade do terceiro detentor das coisas aperendidas
- **Ministério Público**: Autoridade que representa o Estado na investigação e punição dos crimes
- **Apelação**: Recurso contra decisão judicial definitiva

### Referências legais
- Art. 120, §5º, do CPP

### Dicas de prova
- Distinção entre responsabilidade e termo de responsabilidade
- Importância do Ministério Público na restituição de coisas aperendidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.298 (2)", "page_number": 298, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 120, §5º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:30:02.298276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=298", "doc_key": "adf4228f5c20a28437bee733405212cb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '683b34e250f614a7a482892997ec300a3310d5b853026a8549d1aa0debf1ae37'),
  ('cpiuris2025::d8108564666e092d1188329294076ad0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recolhimento de dinheiro apurado em crimes', '## Recolhimento de dinheiro apurado em crimes

O dinheiro apurado em infrações penais é recolhido aos cofres públicos, exceto se houver previsão diversa em lei especial. O que sobrar é destinado ao Fundo Penitenciário Nacional.

### Conceitos
- **producta sceleris**: produto direto da infração
- **fructus sceleris**: frutos da infração
- **proventos**: proveito da infração

### Referências legais
- Art. 133, §1º do CPP

### Dicas de prova
- Entenda a distinção entre produto direto e indireto da infração
- Conheça as regras de recolhimento de dinheiro apurado em crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.299 (2)", "page_number": 299, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 133, §1º do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:31:21.513011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=299", "doc_key": "d8108564666e092d1188329294076ad0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f95d2d4c35b7dde4d1c4848057c1e71440a813b2d0f81dd0263114712209bfe5'),
  ('cpiuris2025::87fc671ac7691e4679da7195a9b13dc8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição das coisas apreendidas', '## Restituição das coisas apreendidas

As coisas apreendidas não podem ser restituídas enquanto interessarem ao processo, salvo se pertencerem ao lesado ou a terceiro de boa-fé.

### Conceitos
- **Restituição das coisas apreendidas**: Proibição de devolver objetos apreendidos enquanto o processo estiver em curso
- **Coisas apreendidas**: Bens confiscados ou adquiridos ilegalmente
- **Interesse ao processo**: Relação entre o bem e a causa de que ele faz parte
- **Lesado**: Parte prejudicada pelo crime
- **Terceiro de boa-fé**: Pessoa que não tem interesse em manter o bem apreendido

### Referências legais
- Art. 118 do CPP
- Art. 119 do CPP
- Art. 91, inciso II, alínea a do CP
- Art. 121 do CPP
- Art. 133 do CPP

### Dicas de prova
- Entenda a noção de interesse ao processo e como ela afeta a restituição das coisas apreendidas
- Conheça as exceções para a restituição, como o caso do lesado ou terceiro de boa-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.299 (1)", "page_number": 299, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 118 do CPP", "Art. 119 do CPP", "Art. 91, inciso II, alínea a do CP", "Art. 121 do CPP", "Art. 133 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:31:28.275371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=299", "doc_key": "87fc671ac7691e4679da7195a9b13dc8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '604bbe5c9bf7fb0f08bac344eeecef9cb4dfc69d2d0fec6029cd2f1f13e115aa'),
  ('cpiuris2025::8a678b1f45b713736a63fd4d6a50c604', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição e Confisco de Coisas Apreendidas', '## Restituição e Confisco de Coisas Apreendidas

Descreve as regras para a restituição e o confisco de coisas apreendidas, incluindo os prazos e condições para cada caso.

### Conceitos
- **Confisco**: A transferência do domínio das coisas apreendidas para a União
- **Restituição**: O devolvimento das coisas apreendidas ao proprietário legítimo
- **Prazo de 90 dias**: O período durante o qual o juiz espera para decidir sobre a restituição ou confisco de uma coisa apreendida

### Referências legais
- Art. 118 do CPP
- Art. 120 do CPP
- Art. 133 do CPP
- Art. 133-A do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo da restituição e confisco de coisas apreendidas

### Dicas de prova
- Diferenciar entre a restituição e o confisco
- Entender o prazo de 90 dias e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.300 (1)", "page_number": 300, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 118 do CPP", "Art. 120 do CPP", "Art. 133 do CPP", "Art. 133-A do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo da restituição e confisco de coisas apreendidas"], "confidence": 0.8, "extracted_at": "2026-05-29T02:32:17.834230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=300", "doc_key": "8a678b1f45b713736a63fd4d6a50c604"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ddd1938807b6f403e1eb5f2f010b451edc1dc3befaa81a455414f2e009278ce1'),
  ('cpiuris2025::6aa087a4dcd2a821cdbe7c6e2dbc98a9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição de coisas apreendidas', '## Restituição de coisas apreendidas

O juiz pode determinar a transferência definitiva da propriedade de bens apreendidos para órgão público, ressalvando o direito do lesado ou terceiro de boa-fé. Em casos de obras de arte ou bens de relevante valor cultural ou artístico, a destinação a museus públicos é cabível se o crime não tiver vítima determinada.

### Conceitos
- **Restituição**: Restauração do patrimônio do lesado ou terceiro de boa-fé
- **Apreensão**: Retirada de bens suspeitos de serem produto do crime
- **Perdimento**: Decisão do juiz que determina a perda da propriedade do bem apreendido
- **Destinação a museu**: Transferência definitiva da propriedade de bens para órgão público

### Referências legais
- Art. 118 A 124-A, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre restituição e perdimento
- Entender a hipótese de destinação a museu público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.301 (1)", "page_number": 301, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 118 A 124-A, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:33:43.595398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=301", "doc_key": "6aa087a4dcd2a821cdbe7c6e2dbc98a9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4472e1e0a1b1e18f58a2684206a3e9e55d8d701d9cbf6d7657f48565c533fe6f'),
  ('cpiuris2025::17d8d22bcc9eadda40fea91f838121c8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Destinação de bens apreendidos', '## Destinação de bens apreendidos

Regra sobre a destinação dos bens apreendidos, incluindo prioridade para órgãos de segurança pública e possibilidade de outros órgãos públicos receberem os bens em caso de interesse público demonstrado.

### Conceitos
- **Apreensão**: ato processual que visa obter provas ou objetos relacionados a infração penal
- **Bem apreendido**: objeto ou valor que é objeto de ação de aperensão
- **Destinação**: decisão do juiz sobre o destino do bem apreendido
- **Interesse público**: motivo pelo qual um órgão público pode receber um bem apreendido
- **Órgão de segurança pública**: instituição responsável pela manutenção da ordem pública e segurança
- **Órgão público**: instituição do Estado que atua em interesse público

### Referências legais
- Art. 340 do Código de Processo Penal

### Dicas de prova
- Entenda a distinção entre órgãos de segurança pública e outros órgãos públicos.
- Conheça a importância da destinação dos bens apreendidos em processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.300 (2)", "page_number": 300, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 340 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:33:55.530641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=300", "doc_key": "17d8d22bcc9eadda40fea91f838121c8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a70138be21fcc3cdd9ffb0639700449f662194dacb4b1cd026a26396448b5be3'),
  ('cpiuris2025::7a75c1e4d3a1eff5b975c7d0dbd679c0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceção de Prazo para Busca e Apreensão', '## Exceção de Prazo para Busca e Apreensão

A busca e apreensão realizada há mais de 7 anos não atende aos requisitos legais, pois excede o prazo recomendável. O princípio da razoabilidade impede que situações como essa sejam chanceladas pelo Poder Judiciário.

### Conceitos
- **Prazo Recomendável**: O período de tempo considerado adequado para a realização de uma medida de busca e apreensão
- **Razoabilidade**: Princípio constitucional que impede situações in razão do Estado de Direito
- **Exceção de Prazo**: Requisito para a realização de uma medida de busca e apreensão

### Referências legais
- Art. 240 e seguintes do CPP

### Jurisprudência
- REsp 788.301/PA
- RMS 21.453/DF

### Dicas de prova
- Distinção entre busca e apreensão
- Importância da razoabilidade no processo penal
- Exceções ao prazo recomendável para buscas e apreensões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.301 (2)", "page_number": 301, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 240 e seguintes do CPP"], "jurisprudence": ["REsp 788.301/PA", "RMS 21.453/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:34:28.433853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=301", "doc_key": "7a75c1e4d3a1eff5b975c7d0dbd679c0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ebd9c0ae6154e26b5e9aa223c404985f0dc1d9bb048415056e2c8f872f94d899'),
  ('cpiuris2025::cfb481f68172bbfc3ba9f180876915c6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição de coisas apreendidas', '## Restituição de coisas apreendidas

A restituição de coisas apreendidas dispensa a prévia manifestação do Ministério Público no incidente, mas não é cabível em todos os casos.

### Conceitos
- **apelação**: recurso contra decisão final
- **previa manifestação**: requerida do Ministério Público no incidente
- **propriedade**: direito sobre um bem
- **apreendido em poder de terceiro de boa-fé**: situação em que o bem é apreendido de alguém que não é o proprietário, mas tem direito legítimo ao mesmo

### Referências legais
- Art. 593, II, do CPP

### Dicas de prova
- Distinguir entre casos em que a restituição é cabível e não é.
- Entender a diferença entre propriedade e direito legítimo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.302 (2)", "page_number": 302, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, II, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:35:14.432168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=302", "doc_key": "cfb481f68172bbfc3ba9f180876915c6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '92b2528c83efe410262f792ecf9b80615a5505d837089b387128e444dccbbf6e'),
  ('cpiuris2025::10c530365a8aa02bf401b17b190cd29a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição de Coisas Apreendidas', '## Restituição de Coisas Apreendidas

A restituição de coisas apreendidas é regulamentada pelos arts. 118 a 124-A do CPP. O magistrado não está adstrito a determinar a constrição com base na Lei que trata somente de um dos delitos em apuração, o que configura constrangimento ilegal ao oferecer a denúncia após transcorrido mais de sete anos do bloqueio.

### Conceitos
- **Recurso cabível**: A apelação é o recurso cabível contra a decisão judicial tomada no incidente de restituição de coisas apreendidas.
- **Restituição somente pelo juiz**: A restituição, quando cabível, poderá ser ordenada somente pelo juiz, mediante termo nos autos, desde que não exista dúvida quanto ao direito do reclamante.
- **Decisão sobre o proprietário verdadeiro**: O juiz deverá decidir sobre a qual parte cabe o direito de propriedade e determinar a restituição em favor desta, em autos apartados, após ouvido o Ministério Público.
- **Uso dos instrumentos do crime**: Os instrumentos do crime, se a perda for decretada em favor da União, bem como as demais coisas confiscadas, deverão ser inutilizados, sendo vedado que tais instrumentos ou coisas recebam qualquer outra destinação.
- **Restituição dos bens apreendidos**: Os bens apreendidos com terceiro de boa-fé poderão ser restituídos pela autoridade policial quando não for necessária sua retenção para o esclarecimento dos fatos.
- **Trânsito em julgado**: A restituição de coisas apreendidas não pode ocorrer antes do trânsito em julgado enquanto interessarem ao processo.

### Referências legais
- Art. 118 a 124-A do CPP

### Jurisprudência
- REsp 865.163/CE
- Súmula N STF

### Dicas de prova
- Pergunta 1: O recurso cabível contra a decisão judicial tomada no incidente de restituição de coisas apreendidas é a apelação.
- Pergunta 2: A restituição, quando cabível, poderá ser ordenada somente pelo juiz, mediante termo nos autos, desde que não exista dúvida quanto ao direito do reclamante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.302 (1)", "page_number": 302, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 118 a 124-A do CPP"], "jurisprudence": ["REsp 865.163/CE", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:35:54.597666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=302", "doc_key": "10c530365a8aa02bf401b17b190cd29a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'de4d66679e8df06e4bf715643fb10cf3bb332558bbf5e5ca5eaa3ee38ea533b3'),
  ('cpiuris2025::f84c426bc2db2b29ba4fb7ff32ed4d1a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Assecuratórias', '## Medidas Assecuratórias

As medidas assecuratórias são providências de cunho patrimonial que visam garantir a recomposição do patrimônio lesado e a reparação do dano causado à vítima.

### Conceitos
- **Sequestro**: Medida assecuratória que visa garantir a reparação do dano causado pela infração penal
- **Hipoteca legal especializada**: Medida assecuratória que visa proteger o patrimônio da vítima
- **Arresto**: Medida assecuratória que visa garantir a recomposição do patrimônio lesado

### Referências legais
- Art. 125 do CPP
- Art. 91, I e II do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre sequestro e hipoteca legal especializada
- Conheça os requisitos necessários para a decretação do sequestro dos imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.305", "page_number": 305, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125 do CPP", "Art. 91, I e II do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T02:37:59.959732+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=305", "doc_key": "f84c426bc2db2b29ba4fb7ff32ed4d1a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aad5479feb40f42de366e5e1b4e3d0caa01c494bceadcae9c31f90fb8385d00f'),
  ('cpiuris2025::bd872dc771eb37878b12677aef5029c1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição das coisas apreendidas', '## Restituição das coisas apreendidas

A restituição das coisas apreendidas depende de vários fatores, incluindo a pessoa que as detém e o interesse do processo. O juiz pode não restituir os bens se estiverem em favor de terceiro de boa-fé ou se forem relevantes para o deslinde da causa.

### Conceitos
- **Restituição das coisas apreendidas**: A devolução dos bens apreendidos ao proprietário ou a terceiros legítimos
- **Terceiro de boa-fé**: Pessoa que não tem interesse em manter os bens apreendidos para si mesma
- **Juiz cível**: Juiz responsável por processos civis, diferente do juiz criminal

### Referências legais
- Art. 118 do CPP
- Art. 120 do CPP
- Art. 124 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre terceiro de boa-fé e terceiro que detém o bem
- Entender a importância da restituição das coisas apreendidas no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.303", "page_number": 303, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 118 do CPP", "Art. 120 do CPP", "Art. 124 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:38:15.951612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=303", "doc_key": "bd872dc771eb37878b12677aef5029c1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f3343200f8f0881d2b66dc4b96a37d5b95beacc6e25f698ce807af3c3fd89978'),
  ('cpiuris2025::8201354ada2e45b040620e55ae5b9af9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimados para decretação do sequestro', '## Legitimados para decretação do sequestro

O artigo 127 do CPP permite ao juiz decreter o sequestro com ou sem a intervenção do Ministério Público ou do ofendido, mas a Lei n.º 13.964/19 derrogou a possibilidade de decretação de ofício pelo juiz.

### Conceitos
- **Legitimados**: Pessoas que podem solicitar o sequestro
- **Ministério Público**: Entidade responsável por investigar crimes e solicitar medidas cautelares
- **Ofendido**: Pessoa que sofreu um dano e pode solicitar o sequestro
- **CPI**: Comissão Parlamentar de Inquérito, que pode solicitar o sequestro com a intervenção do Poder Judiciário

### Referências legais
- Art. 127 do CPP
- Art. 3º-A da Lei n.º 1.579/52
- Lei n.º 13.964/19

### Jurisprudência
- AVENA, 2017, p. 275

### Dicas de prova
- Diferenciar entre o sequestro de bens imóveis e a decretação de ofício pelo juiz
- Entender a cláusula de reserva de jurisdição para o sequestro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.306 (1)", "page_number": 306, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 127 do CPP", "Art. 3º-A da Lei n.º 1.579/52", "Lei n.º 13.964/19"], "jurisprudence": ["AVENA, 2017, p. 275"], "confidence": 0.8, "extracted_at": "2026-05-29T02:38:39.681552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=306", "doc_key": "8201354ada2e45b040620e55ae5b9af9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4e1feb9ed3344874b02b391320c9f6a58015c6d18b2dbdc10eca7e2ca48a5403'),
  ('cpiuris2025::8b05d917f6fb019cdbfb1d5ec7247aa2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Embargos no Sequestro', '## Embargos no Sequestro

O terceiro estranho ao processo não pode embargar o sequestro. O acusado e o terceiro adquirente a título oneroso podem embargar, mas com fundamentos específicos.

### Conceitos
- **Sequestro**: Ato de detenção ilegal de imóveis ou bens móveis
- **Embargos**: Reclamação apresentada por terceiro contra o sequestro de seu bem
- **Acusado**: Parte que é acusada de cometer infração penal
- **Terceiro adquirente a título oneroso**: Pessoa que adquiriu o bem com conhecimento da situação do sequestro

### Referências legais
- Art. 130 do CPP

### Dicas de prova
- Diferenciar entre terceiro estranho e terceiro adquirente a título oneroso
- Conhecer os fundamentos para o embargamento do sequestro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.306 (2)", "page_number": 306, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 130 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:39:58.202522+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=306", "doc_key": "8b05d917f6fb019cdbfb1d5ec7247aa2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2fdc3646deec698cb3b0e525c90b2fda28ae26b1165aec1db3c63f9f650fb2d8'),
  ('cpiuris2025::642d5a122289c3879b22ac494d5956dc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedência dos embargos e sequestro de bens móveis', '## Procedência dos embargos e sequestro de bens móveis

A procedência dos embargos acarreta o levantamento do sequestro, seja porque o bem não foi adquirido pelo acusado com os proventos da infração penal, ou porque o terceiro comprou o bem sequestrado do acusado de boa-fé.

### Conceitos
- **Sequestro**: levantamento do bem móvel adquirido com os proventos da infração penal
- **Procedência dos embargos**: decisão que acarreta o levantamento do sequestro

### Referências legais
- Art. 126 do CPP
- Art. 131 do CPP
- Art. 134 do CPP
- Art. 137 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a relação entre procedência dos embargos e sequestro de bens móveis.
- Identifique a boa-fé como um elemento relevante no sequestro de bens móveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.307 (2)", "page_number": 307, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 126 do CPP", "Art. 131 do CPP", "Art. 134 do CPP", "Art. 137 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:40:32.884321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=307", "doc_key": "642d5a122289c3879b22ac494d5956dc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '99184abdaf58b60c6f1cc6d95bd40bb81c87c1033826d7283a6455c95140e094'),
  ('cpiuris2025::b0b9da820a42955d5de27096e18152bd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Levantamento do Sequestro', '## Levantamento do Sequestro

O sequestro é levantado quando a ação penal não for intentada dentro de 60 dias, ou quando o terceiro que recebeu os bens for capaz de garantir a aplicação do art. 91, ii, b, do CP.

### Conceitos
- **Levantamento do Sequestro**: Medida cautelar que é levantada quando não há cumprimento dos prazos legais para a intentação da ação penal ou quando o terceiro que recebeu os bens for capaz de garantir a aplicação do art. 91, ii, b, do CP.
- **Prazo de Intentação**: 60 dias contados da data em que ficar concluída a diligência
- **Razoabilidade**: Princípio que admite dilação em casos complexos e/ou quando houver pluralidade de acusados

### Referências legais
- Art. 131 do CPP
- Art. 91, ii, b, do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de levantamento do sequestro e as razões que o determinam.
- Conheça o prazo de intentação e a razoabilidade como princípios que influenciam a decisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.307 (1)", "page_number": 307, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 131 do CPP", "Art. 91, ii, b, do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:40:45.943454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=307", "doc_key": "b0b9da820a42955d5de27096e18152bd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '39c7f75e3115103a3f2dd6746a4a864515d9310f84340732d480f8747aef9b1e'),
  ('cpiuris2025::0f1f09d2550e792c3338c843e07488a5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Destinação dos bens apreendidos', '## Destinação dos bens apreendidos

A destinação dos bens apreendidos não é exclusiva dos órgãos de segurança pública, podendo ser objeto de provas concursais.

### Conceitos
- **Bem apropriado**: bem que pode ser destinatário do bem apreendido
- **Órgão público**: instituição pública que pode receber o bem apreendido
- **Interesse público**: motivo pelo qual outro órgão público pode receber o bem apreendido
- **Medida assecuratória**: medida tomada para proteger o bem apreendido

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Destinatário do bem apreendido
- Interesse público
- Medida assecuratória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.308 (2)", "page_number": 308, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:42:17.680019+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=308", "doc_key": "0f1f09d2550e792c3338c843e07488a5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fe42fc33486a2f39502d9f39887e218892d1112820d9b5c3dcc9b1aa4d724062'),
  ('cpiuris2025::b87b54065ce41e179500c06d9cd0f1ce', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca e Apreensão de Bens Sequestrados', '## Busca e Apreensão de Bens Sequestrados

O produto direto da infração (producta sceleris) é objeto de busca e apreensão, enquanto o proveito da infração (fructus sceleris) é objeto de sequestro. Os bens sequestrados podem ser utilizados pelo poder público com autorização do juiz.

### Conceitos
- **Producta sceleris**: O produto direto da infração, objeto de busca e apreensão
- **Fructus sceleris**: O proveito da infração, objeto de sequestro
- **Sequestro de bens móveis**: Aplicação das disposições do sequestro de bens imóveis com algumas exceções

### Referências legais
- Art. 240 e seguintes do CPP
- Art. 133 do CPP
- Art. 128 do CPP
- Lei n.º 13.964/19 (Pacote Anticrime)

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre producta sceleris e fructus sceleris
- Entender a destinação dos bens sequestrados com base no art. 133 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.308 (1)", "page_number": 308, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 240 e seguintes do CPP", "Art. 133 do CPP", "Art. 128 do CPP", "Lei n.º 13.964/19 (Pacote Anticrime)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T02:42:28.761541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=308", "doc_key": "b87b54065ce41e179500c06d9cd0f1ce"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b1e3a332e1847c692caff3deac0133f57a33491679b9861b5a793ca3420d191e'),
  ('cpiuris2025::b2a7acb39769de185a380e13a6806a12', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Hipoteca Legal', '## Hipoteca Legal

A hipoteca legal recai sobre bens imóveis de origem lícita e propriedade do réu, com o objetivo de garantir a indenização aos ofendidos e pagamento das despesas judiciais.

### Conceitos
- **Hipoteca Legal**: Garantia de dívida para compensar danos causados pela infração penal
- **Bens Imóveis**: Objeto da hipoteca legal
- **Ofendido**: Pessoa que sofreu o dano e tem direito à indenização
- **Ministério Público**: Entidade que pode requerer a hipoteca legal em casos de sequestro
- **Delegado de Polícia**: Pessoa que pode requerer a hipoteca legal em casos de infração penal

### Referências legais
- Art. 134 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre hipoteca legal e sequestro
- Entender a finalidade da hipoteca legal (garantia de dívida)
- Conhecer os requisitos para a hipoteca legal (prova de materialidade do fato criminoso e indícios de autoria)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.309 (1)", "page_number": 309, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 134 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T02:43:04.811914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=309", "doc_key": "b2a7acb39769de185a380e13a6806a12"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '18fed9992b6e48415d4ff18f5d3ba6972ff7151ac2a363ccdee63e0fd146e449'),
  ('cpiuris2025::6599ceb3d02818d5cbac09ad3b262b8e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Caução pelo réu no sequestro', '## Caução pelo réu no sequestro

A caução pelo réu é uma medida que pode evitar a inscrição da hipoteca legal em caso de sequestro, desde que oferecida suficiente. No entanto, o réu não pode evitá-la com a caução no sequestro, pois recai sobre bens de origem ilícita.

### Conceitos
- **caução**: medida que evita a inscrição da hipoteca legal
- **hipoteca legal**: recai sobre o patrimônio lícito do réu
- **sequestro**: medida destinada a garantir o confisco em favor da União

### Referências legais
- Art. 135, §6º, do CPP

### Dicas de prova
- Diferencie entre sequestro e caução pelo réu
- Entenda a diferença entre hipoteca legal em sequestro e caução pelo réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.309 (2)", "page_number": 309, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 135, §6º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:44:07.651381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=309", "doc_key": "6599ceb3d02818d5cbac09ad3b262b8e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1de32023660eda392698f4f2ccef5204ee64d18142a94869acd3cc27852c31c5'),
  ('cpiuris2025::034b4906223826dc562d6577375d5a78', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arresto prévio e subsidiário', '## Arresto prévio e subsidiário

O legislador processual penal previu dois tipos de arresto: prévio (ou preventivo) e subsidiário. O arresto prévio é uma medida preparatória da inscrição da hipoteca legal, destinada a tornar os bens imóveis do acusado inalienáveis durante o lapso temporal necessário à tramitação do pedido de registro do gravame real.

### Conceitos
- **Arresto prévio**: Medida preparatória da inscrição da hipoteca legal, destinada a tornar os bens imóveis do acusado inalienáveis.
- **Arresto subsidiário**: Medida destinada a assegurar os bens móveis suscetíveis de penhora, nos termos em que é facultada a hipoteca legal dos imóveis.
- **Hipoteca legal**: Direito real que permite ao Estado se tornar proprietário de um bem em caso de não pagamento do crédito

### Referências legais
- Art. 136 do CPP
- Art. 137 do CPP

### Dicas de prova
- Entenda a diferença entre o arresto prévio e o arresto subsidiário.
- Conheça a finalidade da hipoteca legal e como ela se relaciona com os dois tipos de arresto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.310 (1)", "page_number": 310, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 136 do CPP", "Art. 137 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:44:56.505144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=310", "doc_key": "034b4906223826dc562d6577375d5a78"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1830dac6c0215cd8bcedde678ebf1a71061dfb467d0e17d79868f02bcf76e813'),
  ('cpiuris2025::e331f4fd1f89f0b09884cd4a735196aa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arresto Subsidiário', '## Arresto Subsidiário

O arresto subsidiário recai sobre bens móveis de origem lícita pertencentes ao acusado, visando garantir a indenização e o pagamento das despesas judiciais.

### Conceitos
- **Arresto Subsidiário**: Mudança do locais de detenção de um acusado para garantir a indenização e o pagamento das despesas judiciais.
- **Bens Móveis**: Propriedade que pode ser transportada ou movida.
- **Indenização**: Pagamento feito pelo acusado para compensar os danos causados pela infração penal.
- **Despesas Judiciais**: Gastos realizados durante o processo judicial.
- **Lícita Origem**: Bens que foram adquiridos de forma legal e ética.
- **Sequestro de Bens Móveis**: Ato ilegal de confisco de bens móveis.

### Referências legais
- Art. 134 do CPP

### Dicas de prova
- Diferenciar o arresto subsidiário do sequestro de bens móveis.
- Entender a diferença entre bens móveis e coisas fungíveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.310 (2)", "page_number": 310, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 134 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:45:29.459136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=310", "doc_key": "e331f4fd1f89f0b09884cd4a735196aa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c668e619eb9d9487f9e6efcc4766fe6d0ad7518410a239562ed40118fbc18c13'),
  ('cpiuris2025::50298d3239e03158e6301fcb5dd09ec1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Assecutórias e Remessa dos Autos ao Juiz Cível', '## Medidas Assecutórias e Remessa dos Autos ao Juiz Cível

Discute-se a remessa dos autos do processo criminal para o juiz cível após a sentença condenatória, bem como a venda antecipada de bens sequestrados ou hipotecados.

### Conceitos
- **Defensoria Pública**: instituição que representa os presos
- **Ministério Público**: instituição responsável pela fiscalização do cumprimento das leis
- **Legitimidade prevista no art. 142 do CPP**: direito do Ministério Público de agir em um processo criminal

### Referências legais
- Art. 68 do CPP
- Art. 125-A do CPP
- Art. 142 do CPP
- Art. 143 do CPP
- Art. 144-A do CPP

### Dicas de prova
- Entenda a noção de legitimidade prevista no art. 142 do CPP e como ela se relaciona com a atuação do Ministério Público em um processo criminal.
- Conheça as regras para a venda antecipada de bens sequestrados ou hipotecados, especialmente o §3º do art. 144-A do CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.312 (1)", "page_number": 312, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 68 do CPP", "Art. 125-A do CPP", "Art. 142 do CPP", "Art. 143 do CPP", "Art. 144-A do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:47:15.304133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=312", "doc_key": "50298d3239e03158e6301fcb5dd09ec1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '23fb43da15067abbf8818e6595252095c36c22b989b4848ec71b7019f7dc38be'),
  ('cpiuris2025::26c8b54d5a4250650f5aec7fca7c6cb0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arresto Subsidiário de Bens Móveis', '## Arresto Subsidiário de Bens Móveis

O arresto subsidiário de bens móveis é uma medida processual que pode ser aplicada ao indiciado, com o objetivo de garantir sua manutenção e da de sua família. Apenas bens suscetíveis de penhora podem ser objeto do arresto, e não podem ser recaídos sobre bem móvel de família.

### Conceitos
- **Arresto Subsidiário**: Medida processual que garante a manutenção do indiciado e da sua família
- **Bens Móveis Suscetíveis de Penhora**: Bens móveis que podem ser penhorados em processo judicial
- **Hipoteca Legal**: Hipoteca que é automaticamente registrada no Registro Civil do Imóvel
- **Arresto Prévio**: Medida processual que penhora bens móveis antes da sentença
- **Sequestro**: Medida processual que penhora todos os bens do réu

### Referências legais
- Art. 137, §2º, CPP
- Art. 138, CPP
- Art. 140, CPP
- Art. 141, CPP
- Art. 142, CPP
- Lei nº 8.009/90, art. 1º, parágrafo único

### Jurisprudência
- RE 123456
- Tema repetitivo: Arresto Subsidiário de Bens Móveis

### Dicas de prova
- Diferenciar entre arresto subsidiário e hipoteca legal
- Entender a diferença entre bens móveis suscetíveis de penhora e impenhoráveis
- Conhecer as garantias do ressarcimento do dano em processo de especialização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.311", "page_number": 311, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 137, §2º, CPP", "Art. 138, CPP", "Art. 140, CPP", "Art. 141, CPP", "Art. 142, CPP", "Lei nº 8.009/90, art. 1º, parágrafo único"], "jurisprudence": ["RE 123456", "Tema repetitivo: Arresto Subsidiário de Bens Móveis"], "confidence": 0.8, "extracted_at": "2026-05-29T02:47:35.073114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=311", "doc_key": "26c8b54d5a4250650f5aec7fca7c6cb0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e70267338c117eb90f165992347234c414ba9d0eb08b77ce53667baf6ebce052'),
  ('cpiuris2025::30ab594f7f2c6480a1f42ed67abcf465', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Disposições sobre a alienação de bens no processo criminal', '## Disposições sobre a alienação de bens no processo criminal

O juiz determinará a conversão do numerário apreendido em moeda nacional corrente e o depósito das correspondentes quantias em conta judicial, além de regularizar o registro e licenciamento de veículos, embarcações ou aeronaves.

### Conceitos
- **Alienação de bens**: A transferência de propriedade de um bem para outra pessoa
- **Disposições do juiz**: As ordens e determinações emitidas pelo juiz no processo criminal
- **Conversão de valores**: A conversão de moeda estrangeira em moeda nacional corrente
- **Depósito em conta judicial**: O depósito das quantias apreendidas em conta judicial
- **Registro e licenciamento**: A expedição de certificado de registro e licenciamento para veículos, embarcações ou aeronaves
- **Execução fiscal**: A cobrança de tributos e encargos por parte do Estado
- **Dívidas existentes**: As dívidas que o antigo proprietário tem com o Estado

### Referências legais
- Art. 112 do Código de Processo Penal
- §4º da Lei nº 9.449/1997

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Pergunte sobre a conversão de valores e depósito em conta judicial
- Entenda a noção de registro e licenciamento de veículos, embarcações ou aeronaves
- Conheça as disposições sobre execução fiscal e dívidas existentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.312 (2)", "page_number": 312, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 112 do Código de Processo Penal", "§4º da Lei nº 9.449/1997"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:48:06.220540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=312", "doc_key": "30ab594f7f2c6480a1f42ed67abcf465"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ffc93513e4279b1c22fa43831338592c12b89bb41f34c08240ab342c90308b3b'),
  ('cpiuris2025::efbcdf865cb337f1f0fe959c4d239d2f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Assecuratórias em Ato de Corrupção', '## Medidas Assecuratórias em Ato de Corrupção

O Ministério Público pode requerer medidas assecuratórias para reparar danos causados por atos de corrupção, incluindo a pena de multa. Para decretação do arresto, devem ser verificados indícios de materialidade e autoria, estimativa do dano e perigo na demora.

### Conceitos
- **Legitimidade do Ministério Público**: O Ministério Público possui legitimidade para requerer medidas assecuratórias
- **Plausibilidade do direito**: Verificação de indícios de materialidade e autoria, estimativa do dano e perigo na demora
- **Dano moral coletivo**: Reparação de danos causados por atos de corrupção
- **Pena de multa**: Pagamento da pena pecuniária a ser imposta em caso de condenação

### Referências legais
- Art. 127, I, da CF
- Art. 129, caput, da CF
- Art. 134 do CPP
- Art. 142 do CPP

### Jurisprudência
- RE 4506
- Pet 7069 AgR

### Dicas de prova
- Distinção entre danos morais coletivos e individuais
- Importância da plausibilidade do direito para decretação do arresto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.313 (1)", "page_number": 313, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 127, I, da CF", "Art. 129, caput, da CF", "Art. 134 do CPP", "Art. 142 do CPP"], "jurisprudence": ["RE 4506", "Pet 7069 AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T02:48:35.736438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=313", "doc_key": "efbcdf865cb337f1f0fe959c4d239d2f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9a8af9abca3c8939a3e1ae2032bf4cf921f325e41263dbefcaf3722a8ce8ba47'),
  ('cpiuris2025::3cea5ca6e9cf0bd762a1f35c573f8093', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questões e processos incidentes', '## Questões e processos incidentes

Resumo objetivo: Questões sobre processos incidentes, incluindo hipoteca legal, sequestro, arguição de falsidade e mandado de segurança.

### Conceitos
- **Hipoteca Legal**: Direito real que confere ao credor o direito de exigir a devolução do imóvel em caso de inadimplemento do contrato.
- **Sequestro**: Medida processual que visa proteger bens móveis ou imóveis, advindos de infração penal, e garantir sua restituição ao Estado.
- **Arguição de Falsidade**: Procedimento jurídico pelo qual o procurador, em nome do Estado, busca provar a falsidade de atos ou declarações feitas por um dos litigantes.
- **Mandado de Segurança**: Ordem judicial que visa proteger direito ou interesse legítimo de uma parte, e impede o ato ilegal do outro.

### Referências legais
- Art. 318 do CPP
- Súmula 313/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunta sobre hipoteca legal: distinção entre requerimento pelo ofendido e pelo indiciado.
- Pergunta sobre sequestro: necessidade de indícios seguros de autoria criminosa.
- Pergunta sobre arguição de falsidade: poderes especiais do procurador.
- Pergunta sobre mandado de segurança: direito ou interesse legítimo da parte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.314 (2)", "page_number": 314, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 318 do CPP", "Súmula 313/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:51:20.264347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=314", "doc_key": "3cea5ca6e9cf0bd762a1f35c573f8093"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '49cf9359d70aeea4077edf0fadf92d67a1c654894b2f6909295644ae1a6205b4'),
  ('cpiuris2025::6617a21f7a40423fe2a9f24f69aa79c7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recepção da Constituição Federal de 1988 e medidas de sequestro para garantir ressarcimento de prejuízo', '## Recepção da Constituição Federal de 1988 e medidas de sequestro para garantir ressarcimento de prejuízo

A Constituição Federal de 1988 recebeu o Decreto-Lei n. 3.240/1941, que estabelece a possibilidade de sequestro de bens para garantir o ressarcimento do prejuízo causado e não apenas sobre os produtos ou proveito do crime.

### Conceitos
- **Recepção**: A adesão da Constituição Federal de 1988 ao Decreto-Lei n. 3.240/1941
- **Sequestro**: Medida processual para garantir o ressarcimento do prejuízo causado
- **Ressarcimento de prejuízo**: Compensação pelo dano causado ao erário
- **Boa-fé**: Condição necessária para que terceiro possa defender alheio à prática da infração penal

### Referências legais
- Art. 4º do Decreto-Lei n. 3.240/1941
- Súmula 7/STJ

### Jurisprudência
- RE 123456
- RMS 67.164-MG

### Dicas de prova
- Distinção entre sequestro de bens e produtos ou proveito do crime
