  ('cpiuris2025::5a84dfb0e26a54504fe1e5760b13d2a3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Assecuratórias e Sequestro de Bens', '## Medidas Assecuratórias e Sequestro de Bens

Resumo do texto sobre medidas assecuratórias e sequestro de bens, incluindo questões de concursos.

### Conceitos
- **Art. 125 a 144-A**: Lei que regula as medidas assecuratórias em processos criminais
- **Súmula 211**: Enunciado da Corte que afirma a existência de supressão de instância em casos de atraso no oferecimento da denúncia
- **Alienação antecipada de bens**: Permissão para alienar bens antes do julgamento, com base na dificuldade de manter os bens ou em caso de perecimento
- **Trânsito em julgado da sentença condenatória**: Exigência necessária para o julgamento de embargos opostos ao sequestro, exceto para terceiros estranhos ao fato
- **Sequestro de bens imóveis**: Medida assecuratória que visa proteger os bens do réu em caso de condenação

### Referências legais
- Art. 125 a 144-A, CPP

### Jurisprudência
- Súmula 211

### Dicas de prova
- Entenda o conceito de alienação antecipada de bens e sua aplicabilidade nos processos criminais
- Conheça a Súmula 211 e sua relação com a supressão de instância em casos de atraso no oferecimento da denúncia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.314 (1)", "page_number": 314, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125 a 144-A, CPP"], "jurisprudence": ["Súmula 211"], "confidence": 0.8, "extracted_at": "2026-05-29T02:51:37.244460+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=314", "doc_key": "5a84dfb0e26a54504fe1e5760b13d2a3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ec6a8d583b3a1f09f6b024f3ecd85c148b8756634ba66b8af4987ce965f5831c'),
  ('cpiuris2025::0e99218a4dcf0e27d44d3ea1b6d0db75', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Hipoteca Legal no Processo Penal', '## Hipoteca Legal no Processo Penal

Regras para a hipoteca legal, incluindo quem pode requerê-la e as consequências do não cumprimento do prazo de inscrição.

### Conceitos
- **Art. 134 do CPP**: Quem pode requerer a hipoteca legal
- **Art. 142 do CPP**: Condições para o Ministério Público requerer a hipoteca legal em caso de pobreza
- **Arresto prévio (ou preventivo)**: Consequência do não cumprimento do prazo de inscrição da hipoteca legal
- **Leilão público**: Mecanismo para avaliar e vender bens em caso de perda de patrimônio

### Referências legais
