  ('cpiuris2025::c0d8273fcdb1a12ccae7ce973ca06ac2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sequestro de bens nos crimes de corrupção e lavagem de dinheiro', '## Sequestro de bens nos crimes de corrupção e lavagem de dinheiro

O juiz pode decreter o sequestro dos bens do acusado, desde que haja indícios veementes da proveniência ilícita dos bens. O sequestro não é aplicável a terceiros estranhos ao fato.

### Conceitos
- **Sequestro**: medida cautelar para proteger o patrimônio do Estado
- **Bens ilícitos**: bens provenientes de crimes, como corrupção e lavagem de dinheiro
- **Patrimônio lícito**: patrimônio que pode ser compatibilizado com o rendimento do acusado
- **Rendimento lícito**: renda ou patrimônio que pode ser compatibilizado com a atividade do acusado

### Referências legais
- Art. 125, CPP; Art. 130, parágrafo único, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre sequestro e hipoteca legal
- Conheça as regras para o sequestro de bens nos crimes de corrupção e lavagem de dinheiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.315 (1)", "page_number": 315, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125, CPP; Art. 130, parágrafo único, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T02:53:53.819537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=315", "doc_key": "c0d8273fcdb1a12ccae7ce973ca06ac2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd7546c1f538d120b2eda43c057df3fb6248a6e3603aa78de4a692fbe59256883'),
  ('cpiuris2025::c992021fef3cdac1b567ed0c337bbe07', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sequestro de Bens', '## Sequestro de Bens

Resumo objetivo: O sequestro de bens é uma medida asseguratória que pode ser aplicada em casos de infrações penais, com o objetivo de garantir a reparação do dano causado e confiscar os bens em favor da União. A decretação do sequestro não exige indícios seguros da autoria, mas sim veementes da proveniência ilícita dos bens.

### Conceitos
- **Sequestro de Bens**: Medida asseguratória que pode ser aplicada em casos de infrações penais
- **Reparação do Dano**: Garantir a reparação do dano causado pela infração penal
- **Confisco de Bens**: Levantamento dos bens em favor da União

### Referências legais
- Art. 125 do CPP
- Art. 126 do CPP
- Art. 131 do CPP
- Art. 134 do CPP

### Jurisprudência
- {''RE'': ''RMS n. 53.637/PE'', ''Data'': ''16/5/2017'', ''Relator'': ''Ministro ROGERIO SCHIETTICRUZ''}

### Dicas de prova
- Entenda a diferença entre sequestro e confisco de bens
- Conheça as condições para a decretação do sequestro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.316", "page_number": 316, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125 do CPP", "Art. 126 do CPP", "Art. 131 do CPP", "Art. 134 do CPP"], "jurisprudence": ["{''RE'': ''RMS n. 53.637/PE'', ''Data'': ''16/5/2017'', ''Relator'': ''Ministro ROGERIO SCHIETTICRUZ''}"], "confidence": 0.8, "extracted_at": "2026-05-29T02:54:15.356251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=316", "doc_key": "c992021fef3cdac1b567ed0c337bbe07"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cada212b635d59101dded83170be89062bd8b26a00e8cae50696ae43aa28fe57'),
  ('cpiuris2025::884316b8172a7f4ced22bc4ca0663296', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prova e Teoria Geral da Prova', '## Prova e Teoria Geral da Prova

A prova é a informação ou conjunto de informações trazidas aos autos com o objetivo de reconstruir a dinâmica fática e formar o convencimento do magistrado. O contraditório é um princípio aplicável, garantindo que a parte contrária seja ciada sobre as provas e tenha direito à informação e à participação.

### Conceitos
- **Contraditório**: Princípio que garante ao acusado o direito de se informar sobre as provas apresentadas pelo Estado e de se opor a elas.
- **Imediatidade**: Princípio que exige que o juiz tenha contato físico com as provas no momento de sua obtenção para valorá-las com maior exatidão.

### Referências legais
- Art. 155, CPP
- Art. 5º, LIV, da CF/88

### Dicas de prova
- Entenda o conceito de prova e como ela se relaciona com o contraditório.
- Conheça os princípios aplicáveis à prova, incluindo a imediatidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.318", "page_number": 318, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 155, CPP", "Art. 5º, LIV, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T02:55:49.525803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=318", "doc_key": "884316b8172a7f4ced22bc4ca0663296"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6dd050d7978dda71141c119d541c8b881dec26870e2546edc192e95940c67802'),
  ('cpiuris2025::1ab4ce95dd6372e632218a7228afddc8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema da íntima convicção do julgador', '## Sistema da íntima convicção do julgador

A aplicação do sistema da íntima convicção do julgador é feita nos casos de Jurados do Tribunal do Júri, enquanto o juiz-presidente ainda segue a regra da persuasão racional.

### Conceitos
- **Sistema da íntima convicção**: aplicação do sistema em casos de Jurados do Tribunal do Júri
- **Persuasão racional**: regra aplicada ao juiz-presidente
- **Contraditório judicial**: prova produzida em juízo, sob crivo do contraditório real
- **Investigação policial**: coleta de elementos de informação fora do juízo
- **Convencimento pela livre apreciação**: fundamentação do magistrado nas provas produzidas em juízo

### Referências legais
- Art. 486 do CPP
- Art. 155, caput, do CPP

### Dicas de prova
- Diferenciar entre o sistema da íntima convicção e a persuasão racional
