  ('cpiuris2025::6fa45749b236ccb19f2e6a579ce8c19d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios para produção probatória', '## Princípios para produção probatória

Os princípios da imediatidade, concentração e comunhão regem a produção probatória no processo penal. A imediatidade exige que as provas sejam colhidas diretamente pel o juiz em contato com as partes. A concentração determina que as provas sejam produzidas em uma única audiência ou, ao menos, em um número mínimo de audiências. A comunhão permite que as provas sejam utilizadas por todas as partes e o juiz após serem colhidas.

### Conceitos
- **Imediatidade**: Princípio que exige a produção direta de provas pelo juiz em contato com as partes
- **Concentração**: Princípio que determina a concentração das provas em uma única audiência ou, ao menos, em um número mínimo de audiências
- **Comunhão**: Princípio que permite a utilização das provas por todas as partes e o juiz após serem colhidas

### Referências legais
- Art. 81 da Lei 9.099/1995
- Lei 11.719/2008, arts. 400, 411 e 431
- Art. 155, caput, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da concentração das provas em uma única audiência.
- Conheça o princípio da comunhão e como ele afeta a utilização das provas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.319 (1)", "page_number": 319, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81 da Lei 9.099/1995", "Lei 11.719/2008, arts. 400, 411 e 431", "Art. 155, caput, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T02:56:48.604897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=319", "doc_key": "6fa45749b236ccb19f2e6a579ce8c19d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd4c1473fccaf01a1df031b6750b5cbdf05b6031225c78b179a1dd4d32a3fff19'),
  ('cpiuris2025::ec99e9f0408c9868cfb8aed082276e17', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acessibilidade aos autos do inquérito policial após a Lei n.º 13.964/19', '## Acessibilidade aos autos do inquérito policial após a Lei n.º 13.964/19

O artigo 3º-C, § 3º, do CPP disciplina que os autos de competência do juiz das garantias ficarão acautelados na secretaria desse juízo, sem acesso ao inquérito policial.

### Conceitos
- **Acessibilidade aos autos**: O direito de acessar e examinar os autos de um processo
- **Lei n.º 13.964/19**: Pacote Anticrime, que alterou o CPP
- **Investigação policial**: A fase iniciais da investigação de um crime
- **Substratos**: Os fatos e elementos de informação que fundamentam a decretação de medidas cautelares
- **Análise determinada**: O poder do juiz de analisar os substratos para decidir sobre absolvição sumária

### Referências legais
- Art. 3º-C, § 3º, do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo da STJ

### Dicas de prova
- Entenda a diferença entre acessibilidade aos autos e análise determinada
- Conheça o Pacote Anticrime e suas alterações no CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.320 (1)", "page_number": 320, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-C, § 3º, do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo da STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T02:58:20.505273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=320", "doc_key": "ec99e9f0408c9868cfb8aed082276e17"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f123399adc415675dc2b5c27ec225d44b146d68771f05ca37b9e5f88ab4a97ea'),
  ('cpiuris2025::55f71eac8d8ae273ce436991a2b75917', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas Cautelares, Não Repetíveis ou Antecipadas', '## Provas Cautelares, Não Repetíveis ou Antecipadas

São provas que podem ser produzidas em momento processual distinto do legalmente previsto, com observância do contraditório real. Existem três espécies: cautelares não repetíveis, antecipadas e diferdidas.

### Conceitos
- **Prova Cautelar**: Prova produzida em momento processual distinto do legalmente previsto
- **Prova Não Repetível**: Prova que não pode ser novamente coletada ou produzida
- **Prova Antecipada**: Prova produzida com observância do contraditório real, antes do início do processo
- **Contraditório Diferido**: Diferimento do contraditório em relação à prova

### Referências legais
- Art. 225 do CPP
- Lei n.º 9.296/96

### Jurisprudência
- Súmula nº 74 do STJ

### Dicas de prova
- Entenda a diferença entre provas cautelares, não repetíveis e antecipadas
- Conheça as espécies de contraditório em relação às provas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.321 (1)", "page_number": 321, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 225 do CPP", "Lei n.º 9.296/96"], "jurisprudence": ["Súmula nº 74 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T02:58:56.542215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=321", "doc_key": "55f71eac8d8ae273ce436991a2b75917"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cb6ed7b08439af8e3b017e9f27645976974f831cf5d7e9f60e1dcbb0977886ab'),
  ('cpiuris2025::04a00b72d29310205be18508fc14d91d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recebimento de denúncia ou queixa e medidas cautelares', '## Recebimento de denúncia ou queixa e medidas cautelares

O STF declarou a inconstitucionalidade do termo ''recebimento'' e dos §§ 3º e 4º do art. 3º-C, atribuindo interpretação conforme para entender que o juiz da instrução e julgamento receberá os autos de competência. O juiz pode fundamentar sua decisão exclusivamente nos elementos de informação colhidos na investigação, desde que sejam provas cautelares não repetíveis ou antecipadas.

### Conceitos
- **interpretação conforme**: interpretação ampla e favorável ao texto legal
- **inconstitucionalidade**: declaração do STF de que uma lei é incompatível com a Constituição
- **recebimento**: ato do juiz que aceita a denúncia ou queixa
- **medidas cautelares**: ações tomadas pelo juiz para proteger os direitos dos litigantes

### Referências legais
- Art. 3º-C, §2º e §3º do CPP
- Súmula 416 do STF

### Jurisprudência
- HC 105837 - RS
- AREsp 446385 - RJ

### Dicas de prova
- Entenda a diferença entre interpretação literal e interpretação conforme
- Conheça as regras de inconstitucionalidade do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.320 (2)", "page_number": 320, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-C, §2º e §3º do CPP", "Súmula 416 do STF"], "jurisprudence": ["HC 105837 - RS", "AREsp 446385 - RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T02:58:57.021532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=320", "doc_key": "04a00b72d29310205be18508fc14d91d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd553cba4465732c7a3f11a4b21f8bfdb0dfcea3c258327883f52a2b5c28b110f'),
  ('cpiuris2025::1dbf42b4926ba79a35d4b95c9f2fd553', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prova da menoridade do réu', '## Prova da menoridade do réu

A prova da menoridade do réu não se limita à certidão de nascimento ou à identidade civil, podendo ser comprovada por outros documentos oficiais.

### Conceitos
- **Menoridade do réu**: Condição jurídica que afeta a capacidade processual e penal do réu
- **Prova da menoridade**: Demonstração de que o réu é menor de idade

### Referências legais
- Art. 40, § 2º, do CP

### Jurisprudência
- HC 363.054/MG
- Súmula 484/STJ

### Dicas de prova
- Distinção entre certidão de nascimento e declaração perante autoridade pública
- Importância de outros documentos oficiais na comprovação da menoridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.321 (2)", "page_number": 321, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 40, § 2º, do CP"], "jurisprudence": ["HC 363.054/MG", "Súmula 484/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T02:59:58.906388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=321", "doc_key": "1dbf42b4926ba79a35d4b95c9f2fd553"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd1665ed4222bf5238224306a8c545a553c0dad532ac60cb7326fc30ddf2c7757'),
  ('cpiuris2025::fbaa2ef9053731c082c2ef2b230231db', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ônus probatório', '## Ônus probatório

O ônus probatório é definido como o encargo das partes de provar a verdade das suas alegações. A acusação deve provar a existência do fato imputado e sua autoria, enquanto a defesa deve provar causas excludentes de ilicitude e culpabilidade.

### Conceitos
- **Ônus probatório**: encargo das partes de provar a verdade das suas alegações
- **Acusação**: parte que deve provar a existência do fato imputado e sua autoria
- **Defesa**: parte que deve provar causas excludentes de ilicitude e culpabilidade

### Referências legais
- Art. 156, caput, primeira parte, do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distribuição do ônus da prova entre a acusação e a defesa
- Conheça as regras para a produção antecipada de provas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.322 (1)", "page_number": 322, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 156, caput, primeira parte, do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:01:06.884535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=322", "doc_key": "fbaa2ef9053731c082c2ef2b230231db"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'de452828653895faf9b59753aab92b621297e853b327501138283c2bc7632f68'),
  ('cpiuris2025::063d9be9a997f11ed15328832e00e9de', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Inadmissibilidade das provas ilegais', '## Inadmissibilidade das provas ilegais

A inadmissibilidade das provas é regulamentada pelo art. 157 do CPP, que exclui as provas obtidas por meios ilícitos. A doutrina distingue entre provas ilícitas e ilegítimas, mas o Código não faz distinção.

### Conceitos
- **Prova ilegal**: prova obtida em violação a normas constitucionais ou legais
- **Prova ilícita**: prova obtida através da violação de direitos fundamentais
- **Prova ilegítima**: prova que não atende aos requisitos legais para sua admissão

### Referências legais
- Art. 157 do CPP
- Art. 5º, LVI da CF/88

### Jurisprudência
- RE 123456
- Enunciado nº 5 da Procuradoria-Geral de Justiça e Corregedoria-Geral do Ministério Público de São Paulo

### Dicas de prova
- Entenda a distinção entre provas ilícitas, ilegítimas e legítimas.
- Conheça as normas constitucionais e legais que regulamentam a admissibilidade das provas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.323 (1)", "page_number": 323, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 157 do CPP", "Art. 5º, LVI da CF/88"], "jurisprudence": ["RE 123456", "Enunciado nº 5 da Procuradoria-Geral de Justiça e Corregedoria-Geral do Ministério Público de São Paulo"], "confidence": 0.8, "extracted_at": "2026-05-29T03:01:47.279481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=323", "doc_key": "063d9be9a997f11ed15328832e00e9de"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a1842c07fe0c43dc6b759732b8ac7164799f1ec830d407705fcdb107bd311a92'),
  ('cpiuris2025::16d85be7478708ec370ad1f4592160a6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão do artigo 3º-A do CPP e sua relação com o artigo 156 do Código de Processo Penal', '## Revisão do artigo 3º-A do CPP e sua relação com o artigo 156 do Código de Processo Penal

A Lei nº 13.964/19 alterou a estrutura do processo penal, proibindo a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação. Isso levantou interpretações sobre a revogação tácita do artigo 156 do Código de Processo Penal.

### Conceitos
- **Revisão Tácita**: Processo pelo qual uma lei posterior revoga ou modifica uma lei anterior sem expressa menção à sua revogação.
- **Iniciativa do Juiz**: O direito do juiz de tomar ações no processo penal antes da conclusão da investigação.
- **Substituição da Atuação Probatória**: A substituição do órgão de acusação por outro, sem a necessidade de uma nova investigação.
- **Estrutura Acusatória**: A organização lógica e estrutural do processo penal, que inclui a defesa da acusação.
- **Lei nº 13.964/19**: Lei que alterou a estrutura do processo penal, proibindo a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação.
- **Artigo 3º-A do CPP**: Dispositivo legal que alterou a estrutura do processo penal, proibindo a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação.
- **Artigo 156 do Código de Processo Penal**: Dispositivo legal que regulava a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação.
- **Lei de Introdução às Normas do Direito Brasileiro**: Lei que estabelece as regras básicas para a interpretação das leis brasileiras.

### Referências legais
- Art. 3º-A do CPP
- Art. 156 do Código de Processo Penal
- Art. 2º, §1º, da Lei de Introdução às Normas do Direito Brasileiro

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre iniciativa do juiz e estrutura acusatória.
- Conheça as implicações da revisão tácita de leis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.322 (2)", "page_number": 322, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-A do CPP", "Art. 156 do Código de Processo Penal", "Art. 2º, §1º, da Lei de Introdução às Normas do Direito Brasileiro"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:02:08.076022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=322", "doc_key": "16d85be7478708ec370ad1f4592160a6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ca8398b6df7101e3b1888a6adaddb017a3facb06f1b333962bcab98d3472a56f'),
  ('cpiuris2025::e5014251db9e6036a46d7d1dc0affc04', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas Ilícitas e Ilegítimas', '## Provas Ilícitas e Ilegítimas

Resumo objetivo: Provas obtidas em violação a normas constitucionais ou legais, independentemente da natureza das normas violadas. Diferenciação entre provas ilícitas (violam normas de direito material) e ilegítimas (desobedecem regras de direito processual).

### Conceitos
- **Prova Ilícita**: Obtida em violação a normas constitucionais ou legais
- **Prova Ilegítima**: Desobedece regras de direito processual
- **Art. 203 do CPP**: Regra que proíbe o comprometimento de testemunhas

### Referências legais
- Art. 157, caput, do CPP

### Jurisprudência
- Operação Spoofing (STF)

### Dicas de prova
- Diferenciar entre provas ilícitas e ilegítimas
- Entender a importância da preservação de elementos informativos em provas obtidas ilegalmente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.323 (2)", "page_number": 323, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 157, caput, do CPP"], "jurisprudence": ["Operação Spoofing (STF)"], "confidence": 0.8, "extracted_at": "2026-05-29T03:04:12.398462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=323", "doc_key": "e5014251db9e6036a46d7d1dc0affc04"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9c6c1a9b5673a2afb005be9304184285c8350e0cf2b782dd28a829e0c61c7b8e'),
  ('cpiuris2025::7ad0d1c4464a8dd35d724217e707f54a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ilicitude por derivação (teoria dos frutos da árvore envenenada)', '## Ilicitude por derivação (teoria dos frutos da árvore envenenada)

A Corte entende que as provas derivadas de ilícitas são inadmissíveis e devem ser desentranhadas do processo, pois a ilicitude se estende às provas derivadas das ilícitas.

### Conceitos
- **Ilicitude**: A impossibilidade de admissão de uma prova devido à sua origem ilegal
- **Teoria dos frutos da árvore envenenada**: A teoria que afirma que a ilicitude de uma prova se estende às provas derivadas dela

### Referências legais
- Art. 1º, da CF/88
- Art. 5º, caput, da CF/88

### Jurisprudência
- STF. Plenário. ADPF 605. MC-Ref/DF

### Dicas de prova
- Entenda a noção de ilicitude e como ela se aplica às provas derivadas
- Conheça a teoria dos frutos da árvore envenenada e sua aplicação na jurisprudência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.324 (1)", "page_number": 324, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º, da CF/88", "Art. 5º, caput, da CF/88"], "jurisprudence": ["STF. Plenário. ADPF 605. MC-Ref/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:04:27.088241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=324", "doc_key": "7ad0d1c4464a8dd35d724217e707f54a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f22e6fe037a8a0c2b5891cdf675a1b8a34b0d4c4a52817777497c1e890d561a0'),
  ('cpiuris2025::991bd4ba53539dced1e399c9f2f055f1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas Ilícitas e Frutos da Árvore Envenenada', '## Provas Ilícitas e Frutos da Árvore Envenenada

Regra do Direito Processual Penal: provas ilícitas por derivação são inadmissíveis, pois a ilicitude da primeira prova contaminará as derivadas.

### Conceitos
- **Provas Ilícitas**: provas obtidas por meios ilegais
- **Frutos da Árvore Envenenada**: teoria norte-americana que afirma que a ilicitude de uma prova contamina as derivadas
- **Desentranhamento**: necessidade de separar provas ilícitas das derivadas
- **Fonte Independente**: teoria que afirma que não todas as provas são contaminadas por uma prova ilícita

### Referências legais
- Art. 157, §1º, do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a teoria da fonte independente e como ela se diferencia da teoria dos frutos da árvore envenenada
- Conheça as regras do desentranhamento de provas ilícitas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.324 (2)", "page_number": 324, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 157, §1º, do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:04:36.294883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=324", "doc_key": "991bd4ba53539dced1e399c9f2f055f1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '500e862c0b67b725c3e6bd156d58bdb6a627966c1e57072763c18b893f607c02'),
  ('cpiuris2025::cb1090b2e754710b16d60011f51d322b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Teorias da fonte independente e descoberta inevitável', '## Teorias da fonte independente e descoberta inevitável

Resumo objetivo: As teorias da fonte independente e descoberta inevitável diferenciam as provas ilícitas das lícitas, considerando a relação de causalidade entre elas.

### Conceitos
- **Teoria da fonte independente**: Considera que as provas não são contaminadas pela ilicitude de outra
- **Descoberta inevitável**: Exceção à teoria da fonte independente, considerando a relação de causalidade entre prova ilícita e derivada

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar as teorias da fonte independente e descoberta inevitável
- Entender a relação de causalidade entre provas ilícitas e derivadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.325 (2)", "page_number": 325, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T03:06:07.421324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=325", "doc_key": "cb1090b2e754710b16d60011f51d322b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '414fa3006d417f18e71b809c9221726a929c84fc657f84dc891ec8a37c6bafc8'),
  ('cpiuris2025::b6338aa3251b628c542b8b518eb676ee', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Teoria da Fonte Independente', '## Teoria da Fonte Independente

A teoria da fonte independente é uma exceção que exclui a ilicitude de provas derivadas de provas ilícitas, desde que não haja relação de dependência entre elas.

### Conceitos
- **Teoria da Fonte Independente**: Exceção que exclui a ilicitude de provas derivadas de provas ilícitas
- **Fonte Independente**: Prova que pode ser obtida por si só, seguindo os trâmites típicos e de praxe da investigação ou instrução criminal
- **Relação de Dependência**: Conexão causal entre provas ilícitas e derivadas

### Referências legais
- Art. 157, §1º, CPP

### Dicas de prova
- Entenda a diferença entre teoria da fonte independente e teoria da descoberta inevitável
- Verifique se há relação de dependência entre as provas ilícitas e derivadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.325 (1)", "page_number": 325, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 157, §1º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:06:23.983095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=325", "doc_key": "b6338aa3251b628c542b8b518eb676ee"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ec97b6b2ff7f7b6936038420373c85c101504ce5778ad11071c2c9de9d622df3'),
  ('cpiuris2025::61b86529943545488fe71fe916abb335', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Teoria da Descoberta Inevitável e Fonte Independente', '## Teoria da Descoberta Inevitável e Fonte Independente

A teoria da descoberta inevitável afirma que a prova é produzida de qualquer forma, independentemente da fonte. Já a teoria da fonte independente estabelece que uma prova pode ser obtida por uma fonte independente das ilícitas, sem relação de derivação.

### Conceitos
- **Teoria da Descoberta Inevitável**: A teoria que afirma a autonomia da prova, independentemente da fonte.
- **Fonte Independente**: Uma prova obtida por uma fonte que não tem relação de derivação com as ilícitas.
- **Autonomia da Prova**: A capacidade da prova de ser produzida independentemente da fonte.

### Referências legais
- Art. 157, §1º e §2º do CPP

### Dicas de prova
- Entenda a diferença entre teoria da descoberta inevitável e fonte independente.
- Identifique a autonomia da prova em cada teoria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.326 (1)", "page_number": 326, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 157, §1º e §2º do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:06:49.281278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=326", "doc_key": "61b86529943545488fe71fe916abb335"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b0a4594c7972096e628ca38504364a17cfc88d859c57388ae3640982b60c1cb8'),
  ('cpiuris2025::5b65cb91f24892e9bd5a735af328d62e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Descontaminação do julgado e inadmissibilidade de provas', '## Descontaminação do julgado e inadmissibilidade de provas

O artigo 157, §4º, do CPP estabelece que o juiz que conhece do conteúdo de uma prova declarada inadmissível não pode proferir sentença ou acórdão. A alteração foi vetada pelo Presidente da República, que argumentou que ela poderia causar transtornos no andamento processual e afetar a imparcialidade do juiz.

### Conceitos
- **Descontaminação do julgado**: Princípio que visa evitar que o juiz que fez toda a instrução processual seja substituído por outro que não conhece o caso.
- **Inadmissibilidade de provas**: Prova considerada inapropriada ou inadequada para ser utilizada em julgamento.
- **Juiz imparcial**: Juiz que pode apreciar o caso concreto com a imparcialidade necessária.

### Referências legais
- Art. 157, §4º, do CPP

### Dicas de prova
- Entenda a importância da descontaminação do julgado e como ela se relaciona com a inadmissibilidade de provas.
- Conheça as razões pelas quais o artigo foi vetado pelo Presidente da República.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.326 (2)", "page_number": 326, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 157, §4º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:08:36.536929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=326", "doc_key": "5b65cb91f24892e9bd5a735af328d62e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '93ee1421cf3ef19a5e07d7f4128dacc262e42b309a465cb5afb47050893fa7fb'),
  ('cpiuris2025::e0b329f0564c77117f2e53f3b1300e33', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Descontaminação do julgado e exame de corpo de delito', '## Descontaminação do julgado e exame de corpo de delito

O Pacote Anticrime introduziu a descontaminação do julgado, exigindo que o juiz afaste-se de casos concretos após tomar conhecimento de provas ilícitas. Além disso, o exame de corpo de delito é obrigatório para infrações penais que deixam vestígios.

### Conceitos
- **Descontaminação do julgado**: Exigência de afastamento do juiz de casos concretos após tomar conhecimento de provas ilícitas
- **Exame de corpo de delito**: Perícia destinada à comprovação da materialidade das infrações que deixam vestígios
- **Infrações não transeuntes**: Infrações penais que deixam vestígios, obrigitando o exame de corpo de delito
- **Infrações transeuntes**: Infrações penais que não deixam vestígios, não exigindo o exame de corpo de delito

### Referências legais
- Art. 157, §5º do CPP
- Lei n.º 13.964/19

### Jurisprudência
- ADI 6.298
- ADI 6.299
- ADI 6.300
- ADI 6.305

### Dicas de prova
- Entenda a distinção entre infrações não transeuntes e transeuntes
