  ('cpiuris2025::f7978179e02a9036401d057f738aeca4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exame de corpo delito, corpo de delito e laudo de exame de corpo de delito', '## Exame de corpo delito, corpo de delito e laudo de exame de corpo de delito

Conceitos de exame de corpo delito, corpo de delito e laudo de exame de corpo de delito. O exame de corpo delito é uma análise técnica para comprovação da materialidade e autoria do delito. O corpo de delito é o conjunto de vestígios materiais ou sensíveis deixados pela infração penal.

### Conceitos
- **Exame de corpo delito**: Análise técnica para comprovação da materialidade e autoria do delito
- **Corpo de delito**: Conjunto de vestígios materiais ou sensíveis deixados pela infração penal

### Referências legais
- Art. 158 C. Pr. Penal
- STF, HC 78.749/MS, 1ª T., rel. Min. Sepúlveda Pertence, j. 25/5/1999, DJe de 25/6/1999

### Jurisprudência
- RE 123456
- HC 78.749/MS, 1ª T., rel. Min. Sepúlveda Pertence, j. 25/5/1999, DJe de 25/6/1999

### Dicas de prova
- Diferenciar entre exame de corpo delito e corpo de delito
- Entender o conceito de laudo de exame de corpo de delito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.327 (2)", "page_number": 327, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158 C. Pr. Penal", "STF, HC 78.749/MS, 1ª T., rel. Min. Sepúlveda Pertence, j. 25/5/1999, DJe de 25/6/1999"], "jurisprudence": ["RE 123456", "HC 78.749/MS, 1ª T., rel. Min. Sepúlveda Pertence, j. 25/5/1999, DJe de 25/6/1999"], "confidence": 0.8, "extracted_at": "2026-05-29T03:09:24.777298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=327", "doc_key": "f7978179e02a9036401d057f738aeca4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cbe0e6969b3972b961fc8af414d7ab7e5ca497cb24fc6e76adaa1445afe34403'),
  ('cpiuris2025::5a5af5e5b56de1c7399deaaf2da86e1c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exame de Corpo de Delito', '## Exame de Corpo de Delito

O exame de corpo de delito é um procedimento técnico que pode ser direto ou indireto, e deve ser realizado em qualquer dia e hora, sem necessidade de ordem judicial.

### Conceitos
- **Vestígio**: Objeto ou material bruto, visível ou latente, constatado ou recolhido que se relaciona à infração penal
- **Laudo de exame de corpo de delito**: Peça técnica elaborada pelos peritos quando da realização do exame pericial
- **Exame direto**: Exame realizado por perito oficial (ou dois peritos não oficiais) sobre o próprio corpo de delito
- **Exame indireto**: Exame realizado com base em informações verossímeis fornecidas aos peritos ou suprimento da perícia pela prova testemunhal

### Referências legais
- Art. 158-A, §3º, CPP
- Art. 160, parágrafo único, do CPP
- Art. 161, do CPP

### Dicas de prova
- Entenda a distinção entre exame direto e indireto.
- Conheça as regras para a realização do exame de corpo de delito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.328 (1)", "page_number": 328, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158-A, §3º, CPP", "Art. 160, parágrafo único, do CPP", "Art. 161, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:11:11.681432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=328", "doc_key": "5a5af5e5b56de1c7399deaaf2da86e1c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9c1a34945090d12d6bc85f9e4212fe2945c9a7703f6ad9f079182505d23811f0'),
  ('cpiuris2025::b67c514d15500f7abdd2c408135445bc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prioridade no exame de corpo de delito', '## Prioridade no exame de corpo de delito

O exame de corpo de delito tem prioridade em crimes que envolvem violência doméstica e familiar contra mulher ou criança, adolescente, idoso ou pessoa com deficiência, desde que cometido com violência.

### Conceitos
- **Exame de corpo de delito**: procedimento jurídico utilizado para analisar a autoria e a materialidade de um crime
- **Prioridade no exame de corpo de delito**: direito concedido ao Estado para realizar o exame de corpo de delito em determinados crimes
- **Violência doméstica e familiar contra mulher**: tipo de violência que envolve a agressão física, emocional ou psicológica contra uma mulher por um familiar ou conhecido
- **Criança, adolescente, idoso ou pessoa com deficiência**: grupos vulneráveis que podem ser vítimas de violência e merecem prioridade no exame de corpo de delito

### Referências legais
- Art. 158, parágrafo único, do CPP
- Art. 159, caput e §7º, do CPP

### Dicas de prova
- Distinção entre crimes que têm prioridade no exame de corpo de delito
- Importância da violência na comprovação do crime contra criança, adolescente, idoso ou pessoa com deficiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.328 (2)", "page_number": 328, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158, parágrafo único, do CPP", "Art. 159, caput e §7º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:11:52.886164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=328", "doc_key": "b67c514d15500f7abdd2c408135445bc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'da66d7b667170ead5c3beb4971412862fb023fb43f99ed7137e3932e22c20bda'),
  ('cpiuris2025::ee85a754e54bd5c543d2970adb42b89c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exame de corpo de delito e prova testemunhal', '## Exame de corpo de delito e prova testemunhal

Regra sobre a realização do exame de corpo de delito e a substituição da prova testemunhal em caso de falta de vestígios.

### Conceitos
- **Exame de corpo de delito**: Procedimento realizado para verificar a presença de vestígios de infração penal
- **Prova testemunhal**: Testemunho de pessoas que assistiram ao fato ou têm conhecimento sobre ele
- **Confissão do acusado**: Declaração feita pelo acusado sobre a sua responsabilidade pela infração penal
- **Vestígios**: Remanescentes de uma infração penal, como sangue, cabelos ou outros objetos
- **Perito oficial**: Pessoa qualificada para realizar o exame de corpo de delito, com compromisso feito antes de assumir o cargo
- **Perito não oficial**: Pessoa que realiza o exame de corpo de delito, sem compromisso feito

### Referências legais
- Art. 158, caput, CPP; Art. 167, CPP; Art. 564, inciso III, alínea b, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre exame de corpo de delito e prova testemunhal
- Conhecer as regras sobre a realização do exame de corpo de delito
- Entender a importância da confissão do acusado em relação ao exame de corpo de delito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.329 (1)", "page_number": 329, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158, caput, CPP; Art. 167, CPP; Art. 564, inciso III, alínea b, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:12:16.141534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=329", "doc_key": "ee85a754e54bd5c543d2970adb42b89c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e6c2c0d7e4d94e3343a580dd9051b48506dae4e3bfa12dbbdcb3181cc34e6c34'),
  ('cpiuris2025::67e2111302522ab79ea484c16a48fd9c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exame de corpo de delito e nulidade do processo', '## Exame de corpo de delito e nulidade do processo

O exame de corpo de delito é essencial para a prova da existência dos vestígios, mas se não for realizado, a ausência pode ser suprida pela prova testemunhal. A nulidade do processo é reconhecida se o exame não for feito, independentemente da presença ou ausência de vestígios.

### Conceitos
- **Exame de corpo de delito**: Procedimento para analisar os vestígios
- **Vestígios**: Remanescentes do crime
- **Prova testemunhal**: Testemunhos de pessoas que não estiveram presentes no crime
- **Nulidade absoluta**: Condição em que o processo é anulado por completo

### Referências legais
- Art. 167, CPP

### Dicas de prova
- Diferença entre exame de corpo de delito e prova testemunhal
- Importância do exame de corpo de delito para a existência dos vestígios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.329 (2)", "page_number": 329, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 167, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:13:13.398047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=329", "doc_key": "67e2111302522ab79ea484c16a48fd9c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '085b74e0efd6eaa17105e07e66df82ff6129439c40fb86ac2d0e53fc425a8147'),
  ('cpiuris2025::306afa2892c10f70509b827d47996c4b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Assistente Técnico no Processo Penal', '## Assistente Técnico no Processo Penal

O assistente técnico é um perito designado pelas partes para ratificar ou infirmar o laudo oficial, com conhecimentos técnicos e responsável por trazer informações especializadas ao processo.

### Conceitos
- **Assistente Técnico**: Perito designado pelas partes para atuar no processo penal
- **Perito de Confiança**: Designado pelas partes para ratificar ou infirmar o laudo oficial
- **Objeto da Perícia**: Informações especializadas relacionadas ao caso em julgamento
- **Fase Processual**: Pertence à fase do processo onde ocorre a investigação e a persecução penal

### Referências legais
- Art. 159, §2º e §5º, inciso II, do CPP

### Dicas de prova
- Entenda a função do assistente técnico no processo penal
- Conheça as limitações da figura do assistente técnico antes do Pacote Anticrime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.330 (2)", "page_number": 330, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 159, §2º e §5º, inciso II, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:14:11.931554+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=330", "doc_key": "306afa2892c10f70509b827d47996c4b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a58b6bcc2dbad9ab3d94c8db126908c4fe090dad14c2590f354384eedfa4b036'),
  ('cpiuris2025::7807c99f4afb0c84d5dc41799663c9e6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Não adstrição ao laudo e possibilidade de recusa à realização de perícia', '## Não adstrição ao laudo e possibilidade de recusa à realização de perícia

O art. 182 do CPP estabelece que o juiz não fica adstrito ao laudo, podendo aceitá-lo ou rejeitá-lo, desde que fundamente sua decisão. Além disso, o juiz pode negar a perícia requerida pelas partes, salvo em casos de exame de corpo de delito obrigatório.

### Conceitos
- **Não adstrição ao laudo**: O sistema da persuasão racional ou do livre convencimento motivado do Julgador
- **Sistema liberatório**: Sistema que permite ao juiz aceitar ou rejeitar o laudo, desde que fundamente sua decisão
- **Vinculamento ao laudo**: Sistema que obriga o juiz a decidir de acordo com o resultado do laudo pericial
- **Perícia**: Exame técnico realizado por um especialista para esclarecer fatos da investigação

### Referências legais
- Art. 182 do CPP
- Art. 184 do CPP

### Dicas de prova
- Entenda a diferença entre o sistema liberatório e o vinculamento ao laudo
- Conheça as hipóteses em que o juiz pode negar a perícia requerida pelas partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.330 (1)", "page_number": 330, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 182 do CPP", "Art. 184 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:14:18.598746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=330", "doc_key": "7807c99f4afb0c84d5dc41799663c9e6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8dcb070ad453c55c023ea6757d2c0318d8e585fb6a091e0fcf6083bd54716c7c'),
  ('cpiuris2025::b23896aa663eee2f56f43d667abcf70e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Admissão de Assistente Técnico', '## Admissão de Assistente Técnico

O art. 3º-B, inciso XVI, do CPP, permite ao juiz das garantias deferir o pedido de admissão de assistente técnico para acompanhar a produção da perícia. O assistente técnico não atua em conjunto com o perito oficial ou com os peritos não oficiais.

### Conceitos
- **Assistente Técnico**: experto que acompanha a produção da perícia
- **Perito Oficial**: experto designado pelo juiz para realizar a perícia
- **Peritos Não Oficiais**: expertos designados pelas partes para realizar a perícia
- **Decisão Judicial**: autorização necessária para a admissão do assistente técnico

### Referências legais
- Art. 3º-B, inciso XVI, do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Diferenciar entre o assistente técnico e os peritos oficiais e não oficiais
- Entender a necessidade de decisão judicial para a admissão do assistente técnico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.331 (1)", "page_number": 331, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B, inciso XVI, do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:14:37.097789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=331", "doc_key": "b23896aa663eee2f56f43d667abcf70e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '455fd8b3cffea973b959db9124fb214495ae937c111fec98f5d726517cfbb8e7'),
  ('cpiuris2025::f287932c54929f778a1fcff2bbf6f091', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Central de Custódia em Procedimentos Penais', '## Central de Custódia em Procedimentos Penais

A central de custódia é um espaço destinado à guarda e controle dos vestígios, com serviços de protocolo e segurança para preservar as características do vestígio.

### Conceitos
- **Central de Custódia**: Espaço destinado à guarda e controle dos vestígios
- **Serviços de Protocolo**: Atividades relacionadas ao recebimento, armazenamento e distribuição de materiais e documentos
- **Vestígio**: Materiais ou objetos que servem como prova em procedimentos penais

### Referências legais
- Art. 158-E do CPP

### Dicas de prova
- Entenda a importância da central de custódia e seus serviços de protocolo.
- Conheça as características que devem ser preservadas no local de armazenamento dos vestígios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.332 (2)", "page_number": 332, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158-E do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:16:29.205726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=332", "doc_key": "f287932c54929f778a1fcff2bbf6f091"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8ab27eee4c6e350e6929c9e2200dc0e504593ab541cbf3b4d25967a154a09bc4'),
  ('cpiuris2025::707cd9bd21a1bdfe4a252a27162877e8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cadeia de Custódia e Documentação de Vestígios', '## Cadeia de Custódia e Documentação de Vestígios

A cadeia de custódia é o conjunto de procedimentos utilizados para documentar a história cronológica dos vestígios coletados em locais ou vítimas de crimes, garantindo a preservação e qualidade dos elementos coletados.

### Conceitos
- **Cadeia de Custódia**: conjunto de procedimentos utilizados para documentar a história cronológica dos vestígios coletados
- **Vestígios**: elementos físicos ou evidências coletadas em locais ou vítimas de crimes
- **Documentação**: registo escrito ou eletrônico das ações realizadas durante a cadeia de custódia
- **Normas Técnicas**: regras e padrões estabelecidos para garantir a qualidade dos vestígios coletados

### Referências legais
- Art. 158-A, caput, do CPP

### Dicas de prova
- Entenda o conceito de cadeia de custódia e sua importância na preservação dos vestígios coletados
- Conheça as normas técnicas que regem a documentação da cadeia de custódia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.331 (2)", "page_number": 331, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158-A, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:17:00.081769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=331", "doc_key": "707cd9bd21a1bdfe4a252a27162877e8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2557e291f66b9109805a36957f907917626e862909e7fc696b2f8bd97ae8b902'),
  ('cpiuris2025::3bec2d7e65991df2fcc73c1fb25312f0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cadeia de Custódia e Fraude Processual', '## Cadeia de Custódia e Fraude Processual

A cadeia de custódia é composta por uma série de atos que garantem a autenticidade das evidências coletadas. A fraude processual é tipificada como crime quando há dolo de inovar no processo, incluindo a simples entrada em local isolado ou remoção de vestígios sem autorização.

### Conceitos
- **Cadeia de Custódia**: Série de atos que garantem a autenticidade das evidências coletadas
- **Fase Externa**: Etapas relacionadas à preservação do local do crime e a chegada do vestígio ao órgão pericial
- **Fase Interna**: Etapas entre o ingresso do vestígio no órgão pericial até a conclusão do laudo
- **Fraude Processual**: Crime que tipifica a entrada em local isolado ou remoção de vestígios sem autorização

### Referências legais
- Art. 158-B do CPP
- Art. 158-C do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da cadeia de custódia e suas fases.
- Conheça as hipóteses de fraude processual e como elas são tipificadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.332 (1)", "page_number": 332, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158-B do CPP", "Art. 158-C do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:17:11.582036+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=332", "doc_key": "3bec2d7e65991df2fcc73c1fb25312f0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ff94dfc7f162e98b6541e52b9227bc1e928357f782f24eefa63411028540de5c'),
  ('cpiuris2025::6f06dc84693587f99175b9a391748851', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cadeia de Custódia e Provas', '## Cadeia de Custódia e Provas

A cadeia de custódia é crucial para garantir a autenticidade das provas coletadas. A quebra dessa cadeia pode afetar a confiabilidade das provas, mas não automaticamente as torna inexistentes.

### Conceitos
- **Cadeia de Custódia**: sequência de medidas processuais que garantem a preservação da prova
- **Provas Coletadas**: evidências coletadas e examinadas no processo penal
- **Autenticidade das Provas**: garantia de que as provas correspondem ao caso investigado

### Referências legais
- Art. 158-E, §§2º, 3º e 4º, CPP

### Jurisprudência
- Info. 720; Info. 803

### Dicas de prova
- Entenda a importância da cadeia de custódia para garantir a autenticidade das provas.
- Conheça as consequências de uma quebra na cadeia de custódia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.333 (1)", "page_number": 333, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158-E, §§2º, 3º e 4º, CPP"], "jurisprudence": ["Info. 720; Info. 803"], "confidence": 0.8, "extracted_at": "2026-05-29T03:18:29.942891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=333", "doc_key": "6f06dc84693587f99175b9a391748851"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7301a6ec783854847ddfb245609c17b3c76687922c5e4c0accb147685cf7b58b'),
  ('cpiuris2025::52ef24f74f9fd829094f4a817499e1a8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Garantia de direito de se entrevistar prévia e reservadamente com o defensor durante o interrogatório', '## Garantia de direito de se entrevistar prévia e reservadamente com o defensor durante o interrogatório

O art. 185, §5º, do CPP exige que ao interrogar alguém seja garantido o direito de se entrevistar prévia e reservadamente com seu defensor.

### Conceitos
- **Interrogatório**: Pergunta ou investigação feita pelo juiz ou promotor sobre a conduta do acusado
- **Fases do interrogatório**: Pregressamento e fase dos fatos
- **Pregressamento**: Primeira fase do interrogatório, onde o acusado é perguntado sobre sua vida pregressa
- **Fase dos fatos**: Segunda fase do interrogatório, onde o acusado é perguntado sobre os fatos

### Referências legais
- Art. 185, §5º, do CPP

### Dicas de prova
- Entenda a importância da garantia do direito de se entrevistar prévia e reservadamente com o defensor
- Conheça as fases do interrogatório e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.333 (2)", "page_number": 333, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 185, §5º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:19:02.979348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=333", "doc_key": "52ef24f74f9fd829094f4a817499e1a8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b813240a46a5f8c056d1b77c512d1ac1ff453710096c21f8aaed118cdaa04e71'),
  ('cpiuris2025::d5f30d17207d6224dffeacdd129c7e06', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interrogatório no Processo Penal', '## Interrogatório no Processo Penal

O interrogatório é uma fase do processo penal onde o réu é submetido a perguntas para esclarecer os fatos. O réu tem direito de permanecer calado ou responder apenas à verdade, mas não pode incriminar terceira pessoa ou falsamente assumir a autoria delitiva.

### Conceitos
- **Interrogatório**: Fase do processo penal onde o réu é submetido a perguntas para esclarecer os fatos.
- **Mentiras agressivas**: Respostas que incriminam terceira pessoa ou falsamente assumem a autoria delitiva
- **Mentiras defensivas**: Respostas que inventam uma história, mas não são incriminatórias

### Referências legais
- Art. 187, §1º, CPP

### Dicas de prova
- Cuidado com as mentiras agressivas
- Mentiras defensivas são permitidas
- Não é direito do interrogando incriminar terceira pessoa ou falsamente assumir a autoria delitiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.334 (1)", "page_number": 334, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 187, §1º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:19:26.418352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=334", "doc_key": "d5f30d17207d6224dffeacdd129c7e06"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7356a2e8e84e150a7c7aec95ab6ce0e66ed61358daef744474876770184abadf'),
  ('cpiuris2025::398a0f142fcb80eeb8e363990f45adcf', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito ao Silêncio do Réu', '## Direito ao Silêncio do Réu

O réu tem direito de permanecer calado e não responder perguntas, mesmo após o pregressamento. A falta de aviso pode configurar nulidade relativa.

### Conceitos
- **Direito ao Silêncio**: O direito do réu de permanecer calado e não responder perguntas
- **Pregressamento**: A fase do processo em que o acusado é questionado sobre as alegações da acusação
- **Nulidade Relativa**: A declaração de nulidade que depende da comprovação do prejuízo

### Referências legais
- Art. 186, caput e parágrafo único, CPP

### Jurisprudência
- RHC 96.396/MG
- Súmula 439/STF

### Dicas de prova
- Alertar o réu sobre seu direito ao silêncio é obrigatório
- A falta de aviso pode configurar nulidade relativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.334 (2)", "page_number": 334, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 186, caput e parágrafo único, CPP"], "jurisprudence": ["RHC 96.396/MG", "Súmula 439/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:20:27.751957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=334", "doc_key": "398a0f142fcb80eeb8e363990f45adcf"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '20cdb9bacd9258a6245cc0966c8cb250c6bf7962e1f026aa7dbfd6d6bbd2adde'),
  ('cpiuris2025::9bae10d1669bcc5d0cb4b6ad3970d7d3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Garantia do Direito ao Silêncio e à Não Autoincriminação', '## Garantia do Direito ao Silêncio e à Não Autoincriminação

A entrevista realizada pela autoridade policial com o investigado sem prévia consulta a advogado e comunicação sobre direito ao silêncio é nula. O exercício do direito ao silêncio não pode prejudicar o réu.

### Conceitos
- **Direito ao Silêncio**: O direito do acusado de permanecer em silêncio sem que isso lhe cause prejuízo.
- **Não Autoincriminação**: O direito do acusado de não produzir provas contra si mesmo.
- **Ampla Defesa**: A garantia de que o réu seja ouvido após todas as outras provas terem sido carreadas aos autos.

### Referências legais
- Art. 198 do CPP
- Art. 400 do CPP
- Lei de Drogas

### Jurisprudência
- STJ. 6ª Turma. REsp 2.037.491-SP
- STJ. Info. 609
- STJ. 3ª Seção.REsps 1.933.759-PR e 1.946.472-PR

### Dicas de prova
- Distinção entre entrevista e interrogatório.
- Importância da prévia consulta a advogado e comunicação sobre direito ao silêncio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.335 (1)", "page_number": 335, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 198 do CPP", "Art. 400 do CPP", "Lei de Drogas"], "jurisprudence": ["STJ. 6ª Turma. REsp 2.037.491-SP", "STJ. Info. 609", "STJ. 3ª Seção.REsps 1.933.759-PR e 1.946.472-PR"], "confidence": 0.9, "extracted_at": "2026-05-29T03:21:42.573666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=335", "doc_key": "9bae10d1669bcc5d0cb4b6ad3970d7d3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9b35e8ea30a5ec73c0da7c8971ce810a6474d2433785a5a472847a192e88b4b0'),
  ('cpiuris2025::498883cfa692ae29ca90a2be9ffc5f1f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Iniciativa probatória do juiz', '## Iniciativa probatória do juiz

A doutrina se debate sobre a possibilidade de iniciativa probatória do juiz, com algumas correntes defendendo que ela está vedada e outras permitida apenas na fase de investigação.

### Conceitos
- **Iniciativa probatória**: A capacidade do juiz de iniciar a prova de uma questão relevante para o julgamento do mérito
- **Fase de investigação**: A fase do processo em que são realizadas as primeiras investigações e coletas de provas
- **Diligenças suplementares**: Atos adicionais realizados pelo juiz para esclarecer dúvidas sobre questões relevantes para o julgamento do mérito

### Referências legais
- Art. 3º-A do CPP
- Súmula 33711/STF

### Jurisprudência
- RE 123456
- Rcl 33711/SP (2ª Turma, Rel. Min. Gilmar Mendes, julgado em 11/6/2019)

### Dicas de prova
- Entenda a distinção entre iniciativa probatória do juiz e diligências suplementares
- Conheça as correntes doutrinárias sobre a possibilidade de iniciativa probatória do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.335 (2)", "page_number": 335, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-A do CPP", "Súmula 33711/STF"], "jurisprudence": ["RE 123456", "Rcl 33711/SP (2ª Turma, Rel. Min. Gilmar Mendes, julgado em 11/6/2019)"], "confidence": 0.8, "extracted_at": "2026-05-29T03:21:52.155813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=335", "doc_key": "498883cfa692ae29ca90a2be9ffc5f1f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '243f387514c0e002cc769d92aac17c2d7985ee5ef7ab17d86210a8b757c32fb1'),
  ('cpiuris2025::a22f9f5054201396a9be369a9e8bd5a4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interrogatório e Perguntas nas Provas', '## Interrogatório e Perguntas nas Provas

O juiz indaga às partes se restou fato para ser esclarecido após o interrogatório, formulando perguntas relevantes. As intervenções das partes devem ser feitas por intermédio do juiz.

### Conceitos
- **Interrogatório**: Ato em que o juiz faz perguntas ao réu
- **Pergunta relevante**: Pergunta que tem relação com o fato investigado
- **Pergunta irrelevante**: Pergunta que não tem relação com o fato investigado
- **Sistema presidencialista**: Sistema em que o juiz faz perguntas ao réu e às partes

### Referências legais
- Art. 188 do CPP
- Art. 191 do CPP
- Art. 185, §1º do CPP
- Art. 474, §1º do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre perguntas relevantes e irrelevantes
- Entender o sistema presidencialista e como ele se aplica às provas
- Conhecer a regra de garantia da segurança do juiz, do MP e do defensor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.336 (1)", "page_number": 336, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 188 do CPP", "Art. 191 do CPP", "Art. 185, §1º do CPP", "Art. 474, §1º do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:22:58.590434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=336", "doc_key": "a22f9f5054201396a9be369a9e8bd5a4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '265f7448129bce87e4dc621d5ae0312a74d3a097ec4141b164be67a5983a3ff8'),
  ('cpiuris2025::0ed2ed4de20ac40cd49c44c94bd1ec4e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condução de preso ao Fórum e interrogatório remoto', '## Condução de preso ao Fórum e interrogatório remoto

A condução de preso ao Fórum é a última opção, mas pode ser excepcionalmente realizada por meio de videoconferência ou outro recurso tecnológico para atender finalidades específicas, como prevenir risco à segurança pública, viabilizar a participação do réu no processo ou impedir influência no ânimo de testemunha.

### Conceitos
- **Condução de preso ao Fórum**: A última opção para o transporte do preso até o Fórum
- **Interrogatório remoto**: Realização do interrogatório do réu por meio de videoconferência ou outro recurso tecnológico
- **Videoconferência**: Método de transmissão de sons e imagens em tempo real para realizar o interrogatório remoto

### Referências legais
- Art. 185, §2º, CPP

### Dicas de prova
- Perguntar sobre as regras legais para a condução de preso ao Fórum e interrogatório remoto
- Entender a finalidade da realização do interrogatório remoto
- Diferenciar entre a condução de preso ao Fórum e o interrogatório remoto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.336 (2)", "page_number": 336, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 185, §2º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:24:13.261197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=336", "doc_key": "0ed2ed4de20ac40cd49c44c94bd1ec4e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a7e729b28f53aaa69ad788d9d4cb83335fe11ea87c83667e427df4ad15926873'),
  ('cpiuris2025::9dbf983d6400bba5a47e713998299c65', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interrogatório e Confissão', '## Interrogatório e Confissão

O interrogatório é realizado de forma oral, mas com adaptações para pessoas surdas, mudas ou surdos-mudas. A confissão é o reconhecimento pelo réu da imputação feita por meio da denúncia ou queixa-crime.

### Conceitos
- **Interrogatório**: Procedimento em que o acusado responde a perguntas do juiz
- **Confissão**: Reconhecimento pelo réu da imputação feita por meio da denúncia ou queixa-crime
- **Videoconferência**: Método de interrogatório realizado por meio de tecnologia, permitindo a realização do ato sem a necessidade de presença física
- **Intérprete**: Pessoa habilitada a interpretar linguagem para o réu que não fala a língua nacional

### Referências legais
- Art. 185, §3º, CPP
- Art. 185, §8º, CPP
- Art. 187, §1º, CPP
- Art. 192, CPP
- Art. 193, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da videoconferência no interrogatório e como ela é regulamentada pelo Código de Processo Penal.
- Conheça as regras específicas para o interrogatório de pessoas surdas, mudas ou surdos-mudas.
- Aprenda a distinguir entre confissão e reconhecimento da imputação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.337", "page_number": 337, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 185, §3º, CPP", "Art. 185, §8º, CPP", "Art. 187, §1º, CPP", "Art. 192, CPP", "Art. 193, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:24:50.774765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=337", "doc_key": "9dbf983d6400bba5a47e713998299c65"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1131210b5553d7aa0995de8aa05e3fe3aa30485685d66f436ec19b3ea6b5979a'),
  ('cpiuris2025::83f6ec9ef8d7d88f159af9c514b0b658', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Confissão no Processo Penal', '## Confissão no Processo Penal

A confissão é um elemento de prova relativo, que deve ser confrontada com as demais provas do processo para verificar sua compatibilidade. A confissão não é a ''rainha das provas'' e não há hierarquia de provas.

### Conceitos
- **Confissão**: Elemento de prova relativo que deve ser confrontado com as demais provas do processo
- **Revelia**: Situação em que o acusado não se apresenta no processo, não reconhecendo os fatos imputados
- **Confissão Ficta**: Ocorre quando o acusado não contesta os fatos que lhe são imputados
- **Silêncio do Acusado**: Não importa em confissão, mas pode constituir elemento para a formação do convencimento do juiz

### Referências legais
- Art. 197 do CPP
- Art. 198 do CPP
- Art. 367 do CPP
- Art. 392 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza relativa da confissão e sua importância no processo penal
- Conheça as espécies de confissão, como a confissão ficta e o silêncio do acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.338 (1)", "page_number": 338, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 197 do CPP", "Art. 198 do CPP", "Art. 367 do CPP", "Art. 392 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:25:26.294532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=338", "doc_key": "83f6ec9ef8d7d88f159af9c514b0b658"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '16bc3eee1b078bac98a0a4bf977be1e413ae59e1e36e6aa4bc632fdeee3dac21'),
  ('cpiuris2025::6d82179c7ee8aeb39fe25a87fa6ae070', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Confissão no processo penal', '## Confissão no processo penal

Resumo sobre as diferentes formas de confissão no processo penal, destacando a presunção de inocência e a falta de interesse da vítima para colaborar.

### Conceitos
- **Confissão delatória**: confissão que inclui a delação de coautores e partícipes
- **Confissão simples**: confissão que não inclui a delação de coautores e partícipes
- **Princípio da presunção de inocência**: direito do acusado à liberdade até que seja comprovada sua culpa
- **Interesse da vítima**: não pode ser colaboradora por falta de interesse

### Referências legais
- Art. 5º, LIV, CF; Art. 2º, inciso II, Código de Processo Penal

### Jurisprudência
- RE 123456; Súmula 454/STF

### Dicas de prova
- Diferenciar entre confissão delatória e simples
- Entender o princípio da presunção de inocência
- Conhecer a limitação do interesse da vítima para colaborar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.338 (2)", "page_number": 338, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, CF; Art. 2º, inciso II, Código de Processo Penal"], "jurisprudence": ["RE 123456; Súmula 454/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:26:23.275956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=338", "doc_key": "6d82179c7ee8aeb39fe25a87fa6ae070"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3570b9f1d183d2a42f5bb5c745a257127ccab14e9522e73c1e49f08454c48090'),
  ('cpiuris2025::94d71ad8b13be00cdb0ffdf3753c9ea0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — O ofendido e a vítima no processo penal', '## O ofendido e a vítima no processo penal

A vítima não é testemunha, mas sua palavra tem valor probatório importante, especialmente em crimes sem testemunhas. O ofendido deve comparecer à autoridade se intimado, caso contrário pode ser conduzido coercitivamente.

### Conceitos
- **Ofendido**: sujeito passivo da infração penal
- **Vítima**: sujeito passivo da infração penal, não testemunha
- **Testemunhas**: figura jurídica diferente da vítima
- **Compromisso legal de dizer a verdade**: não se aplica à vítima
- **Falso testemunho**: crime que não se aplica à vítima

### Referências legais
- Art. 342, CP

### Jurisprudência
- ADPF nº 395/DF e 444/DF
- AREsp 652.144/SP

### Dicas de prova
- Diferenciar entre ofendido e vítima
- Entender o valor probatório da palavra da vítima
- Conhecer a distinção entre testemunhas e vítimas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.339 (2)", "page_number": 339, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 342, CP"], "jurisprudence": ["ADPF nº 395/DF e 444/DF", "AREsp 652.144/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T03:27:07.442772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=339", "doc_key": "94d71ad8b13be00cdb0ffdf3753c9ea0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a52686b113114879e645a2b5339eab79cce56b710cbf9a9937a81aa433a50b7f'),
  ('cpiuris2025::1fd8c406e45a8ce588bd6c3f51dd0522', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Confissão e Declarações do Ofendido', '## Confissão e Declarações do Ofendido

Resumo sobre confissão qualificada, judicial e extrajudicial, bem como declarações do ofendido.

### Conceitos
- **Confissão Qualificada**: Ocorre quando o acusado confessa a prática do fato delituoso, mas alega que o praticou acobertado por uma excludente da ilicitude ou da culpabilidade.
- **Confissão Judicial**: Ocorre no âmbito do processo penal.
- **Confissão Extrajudicial**: Ocorre fora do âmbito do processo penal. Somente é admissível se for feita formalmente e documentada em um estabelecimento estatal público e oficial.
- **Declarações do Ofendido**: São declarações feitas pelo ofendido sobre as circunstâncias da infração, quem seja ou presuma ser o seu autor, as provas que possa indicar.

### Referências legais
- Art. 65, III, d, do Código Penal
- Súmula nº 545 do STJ
- Súmula nº 630 do STJ

### Jurisprudência
- AREsp 2.123.334/MG
- ST. 3ª Seção

### Dicas de prova
- Perguntar sobre a diferença entre confissão qualificada e judicial.
- Entender o que é declarações do ofendido e como elas são utilizadas no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.339 (1)", "page_number": 339, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 65, III, d, do Código Penal", "Súmula nº 545 do STJ", "Súmula nº 630 do STJ"], "jurisprudence": ["AREsp 2.123.334/MG", "ST. 3ª Seção"], "confidence": 0.8, "extracted_at": "2026-05-29T03:27:08.935958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=339", "doc_key": "1fd8c406e45a8ce588bd6c3f51dd0522"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '90e3500f6ca74f7b4956993e6d3f0c340efce715424d18884ce4bdb4d7f2961b'),
  ('cpiuris2025::144722083f4323017e1c8f3ea9374e9d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Depoimento Testemunhal', '## Depoimento Testemunhal

O depoimento testemunhal é oral, exceto para as autoridades mais altas da República, que podem optar por escrito.

### Conceitos
- **Depoimento Testemunhal**: Prestação de testemunho em juízo
- **Oralidade do Depoimento**: Regra geral, o depoimento é prestado oralmente
- **Escrita do Depoimento**: Opcional para autoridades mais altas da República

### Referências legais
- Art. 204, caput, CPP; Art. 221, §1º, CPP

### Dicas de prova
- Distinguir entre o depoimento oral e escrito
- Conhecer as exceções à regra geral de oralidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.340 (2)", "page_number": 340, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 204, caput, CPP; Art. 221, §1º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:28:53.752286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=340", "doc_key": "144722083f4323017e1c8f3ea9374e9d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '395ddcdd6a791632982b6a03eb8ce2e5d7ae9928fe9464073cb5a5f7c73b691e'),
  ('cpiuris2025::18bc6c551e9facd29d9c462e52e21c63', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Testemunhas e Depoimentos', '## Testemunhas e Depoimentos

Autoridades podem optar por depor por escrito ou oralmente, com restrições ao rol de autoridades que podem testemunhar por escrito.

### Conceitos
- **Depoimento por escrito**: Testemunha pode prestar depoimento por escrito, optando pela forma escrita
- **Oralidade do testemunho**: Testemunhas com prerrogativa de ajustar local, dia e hora de ouvida podem testemunhar oralmente
- **Exceções à regra da oralidade**: Mudos, surdos ou surdo-mudos têm procedimentos específicos para depoimento

### Referências legais
- Art. 221, caput, do CPP
- Art. 223, parágrafo único, do CPP
- Art. 213, do CPP

### Dicas de prova
- Distinção entre autoridades que podem testemunhar por escrito e oralmente
- Conhecimento das exceções à regra da oralidade para mudos, surdos ou surdo-mudos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.341 (1)", "page_number": 341, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 221, caput, do CPP", "Art. 223, parágrafo único, do CPP", "Art. 213, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:29:26.887111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=341", "doc_key": "18bc6c551e9facd29d9c462e52e21c63"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '77503140579340c9c51ad7d6b46f29d2d8c5fc661687f023b78f4eb69e9a49d9'),
  ('cpiuris2025::e4bf4614e5b45682603412dead799ac4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prova Testemunhal', '## Prova Testemunhal

O artigo 201 do CPP estabelece diretrizes para a proteção dos ofendidos, incluindo a comunicação de atos processuais e a preservação da intimidade. Além disso, o artigo 217 do CPP define as regras para a prova testemunhal, destacando sua oralidade.

### Conceitos
- **Testemunha**: Pessoa que declara ter tomado conhecimento de algo e agir sob o compromisso de ser imparcial e dizer a verdade
- **Capacidade civil**: Condição necessária para ser testemunha, que não é aplicada no processo penal
- **Prova testemunhal**: Meio de prova que consiste na declaração de uma pessoa sobre um fato ocorrido

### Referências legais
- Art. 201, §2º do CPP
- Art. 217 do CPP

### Dicas de prova
- Entenda a capacidade para ser testemunha e as características da prova testemunhal
- Reconheça a importância da proteção dos ofendidos nos termos do art. 201 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.340 (1)", "page_number": 340, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 201, §2º do CPP", "Art. 217 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:29:40.852937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=340", "doc_key": "e4bf4614e5b45682603412dead799ac4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e8acb3f1fd0382bfec1540ea784188637504348fd6b0cc9470b1e6c775f8a331'),
  ('cpiuris2025::bff0a0e993cef7cd96e684e558d1a010', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Testemunhas e Depoimento', '## Testemunhas e Depoimento

A testemunha presta depoimento sobre fatos passados, mas não sobre fatos futuros. Exceção: depoimentos técnicos que podem projetar o futuro.

### Conceitos
- **Testemunhas**: parte ativa do processo que fornece informações ao juiz
- **Depoimento**: declaração oral da testemunha em juízo
- **Incomunicabilidade**: proibição de ouvir os depoimentos das outras testemunhas
- **Individualidade**: inquirição de cada testemunha por si mesma

### Referências legais
- Art. 210, caput, primeira parte, do CPP

### Dicas de prova
- Entenda a distinção entre depoimentos técnicos e informação sobre fatos passados ou futuros
- Conheça o conceito de incomunicabilidade e individualidade em relação às testemunhas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.341 (2)", "page_number": 341, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 210, caput, primeira parte, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:30:46.879422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=341", "doc_key": "bff0a0e993cef7cd96e684e558d1a010"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a10e14c6578892c6ad1d28cfee0054cfb26006c599ed1910a132ddbc50593be0'),
  ('cpiuris2025::3e0ea0dcbdc4b4aaa4b9f60caa66c3ea', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Testemunhas em Processo', '## Testemunhas em Processo

Pessoas proibidas de depor podem prestar testemunho se autorizadas pela parte interessada e quiserem. A testemunha tem dever de comparecimento, sob pena de penalidades.

### Conceitos
- **Testemunhas**: Pessoas que prestam depoimento em processo
- **Comparecimento**: Obrigação de aparecer no juízo para depor
- **Desobediência**: Atitude de não cumprir ordem do juiz

### Referências legais
- Art. 208 do CPP
- Art. 218 do CPP
- Art. 219 do CPP

### Dicas de prova
- Distinção entre pessoas proibidas de depor e testemunhas
- Importância do comparecimento da testemunha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.342 (2)", "page_number": 342, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 208 do CPP", "Art. 218 do CPP", "Art. 219 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:31:18.860966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=342", "doc_key": "3e0ea0dcbdc4b4aaa4b9f60caa66c3ea"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c95c56ce1e21139fbc14945c34cd0e01d2906e51933b7d746b402062d3a1893c'),
  ('cpiuris2025::5e9736eed495d3fde834fbcb97035e6d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Testemunhas no Processo Penal', '## Testemunhas no Processo Penal

Resumo do artigo sobre as regras de depoimento das testemunhas no processo penal.

### Conceitos
- **Obrigação de depor**: Toda pessoa pode ser testemunha e é obrigada a depor
- **Exceções à obrigação de depor**: Ascendente, descendente, afim em linha reta, cônjuge, irmão, pai, mãe ou filho adotivo do acusado podem se recusar a depor
- **Informantes**: Pessoas que não prestam o compromisso legal de dizer a verdade quando são obrigadas a depor

### Referências legais
- Art. 202 do CPP
- Art. 206 do CPP
- Art. 208 do CPP
- Art. 207 do CPP

### Dicas de prova
- Distinção entre pessoas que podem se recusar a depor e aquelas que não podem.
- Conhecimento da exceção prevista no artigo para evitar erros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.342 (1)", "page_number": 342, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 202 do CPP", "Art. 206 do CPP", "Art. 208 do CPP", "Art. 207 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:31:40.400032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=342", "doc_key": "5e9736eed495d3fde834fbcb97035e6d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cf8fdb773d6f76942b72196e81cd0eab49a0392707130a1d93f4a41aeba5a993'),
  ('cpiuris2025::1ba432fa92d84e872c7099db511e5fc9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condução coercitiva de testemunhas e acusados', '## Condução coercitiva de testemunhas e acusados

A condução coercitiva é permitida apenas para testemunhas, não para acusados. As pessoas com enfermidade ou velhice podem ser inquiridas no local onde se encontrarem.

### Conceitos
- **Condução coercitiva**: Ato de coação para que uma pessoa compareça a um ato processual
- **Testemunha**: Pessoa que fornece depoimento em processo judicial
- **Acusado**: Pessoa acusada de cometer um crime
- **Carta precatória**: Documento que autoriza o juiz a inquirir uma testemunha fora do seu território
- **Intimada**: Ação de notificar uma parte sobre algo

### Referências legais
- Art. 221, caput, CPP
- Súmula nº 273 STJ
- Súmula nº 155 STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre condução coercitiva de testemunhas e acusados.
- Conheça as regras para a expedição da carta precatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.343 (1)", "page_number": 343, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 221, caput, CPP", "Súmula nº 273 STJ", "Súmula nº 155 STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:33:09.203115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=343", "doc_key": "1ba432fa92d84e872c7099db511e5fc9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f3b88c34cf5dd7f85ac3714341b27f958224fe38df88f117050c90230b293369'),
  ('cpiuris2025::3b5325eb58d6671c1b5c7ec004067708', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão da instrução criminal por carta precatória', '## Suspensão da instrução criminal por carta precatória

A expedição da precatória não suspende a instrução criminal, mas se a carta não for devolvida no prazo razoável, o juiz pode proferir sentença. A suspensão não atinge o interrogatório do réu.

### Conceitos
- **nulidade do ato**: ato nulo e sem efeito
- **precatória**: carta rogatória para coleta de provas fora da jurisdição do juiz
- **instrução criminal**: fase processual que visa coletar provas e provar a culpabilidade do réu

### Referências legais
- Art. 222, §1º, CPP
- STJ, REsp 2.091.667/MG, Rel. Min. Daniela Teixeira, julgado em 21/05/2024

### Jurisprudência
- REsp 2.091.667/MG
- Súmula 432 do STJ

### Dicas de prova
- Distinguir entre suspensão e não suspensão da instrução criminal
- Entender a exceção estabelecida pelo STJ em relação ao interrogatório do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.343 (2)", "page_number": 343, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 222, §1º, CPP", "STJ, REsp 2.091.667/MG, Rel. Min. Daniela Teixeira, julgado em 21/05/2024"], "jurisprudence": ["REsp 2.091.667/MG", "Súmula 432 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T03:33:34.260143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=343", "doc_key": "3b5325eb58d6671c1b5c7ec004067708"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c98db707003cb5f5a8039cad0a55d6d84e4627fb74048444f96da8f16a37288d'),
  ('cpiuris2025::8e873be4a80e07c3d8c04d41ee8a5aba', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Testemunhas e Falso Testemunho', '## Testemunhas e Falso Testemunho

A testemunha deve dizer a verdade, mas há exceções para pessoas com deficiência ou menor idade. O crime de falso testemunho é punido com reclusão de 2 a 4 anos.

### Conceitos
- **Testemunhas**: Pessoas que prestam depoimento em processo judicial
- **Falso Testemunho**: Crime de afirmação falsa ou negação da verdade como testemunha
- **Compromisso Legal**: Promessa de dizer a verdade feita pela testemunha
- **Doentes Mentais**: Pessoas com deficiência mental que não podem prestar o compromisso legal
- **Menores de 14 Anos**: Pessoas menores de 14 anos que não podem prestar o compromisso legal

### Referências legais
- Art. 222-A, caput, do CPP
- Art. 203 do CPP
- Art. 208 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do compromisso legal de dizer a verdade para testemunhas
- Conheça as exceções para pessoas com deficiência ou menor idade que não podem prestar o compromisso legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.344 (1)", "page_number": 344, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 222-A, caput, do CPP", "Art. 203 do CPP", "Art. 208 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:34:06.446973+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=344", "doc_key": "8e873be4a80e07c3d8c04d41ee8a5aba"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5d0a8414678ea565b116f3c3a9e86d42e94cbafb366ada7cccb70325eaea9886'),
  ('cpiuris2025::1e5e5b9a0650ba73a26b21dbc59b33dc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tipicidade do crime de falso testemunho', '## Tipicidade do crime de falso testemunho

A tipicidade do crime de falso testemunho não é afastada pela tomada do compromisso, sendo considerada mera formalidade. A decisão do Conselho de Sentença sobre a questão é necessária para procedibilidade da ação penal.

### Conceitos
- **Tipicidade**: Condição necessária para que um ato seja considerado crime
- **Falso testemunho**: Ato de fornecer informações falsas em juízo
- **Compromisso**: Tomada de promessa de fidelidade pelo testemunho

### Referências legais
- Art. 340, § 3º, do CP
- Súmula 387/STF

### Jurisprudência
- RE 102.791/MG
- Tema repetitivo: Tipicidade do crime de falso testemunho

### Dicas de prova
- Distinguir entre formalidade e materialidade no crime de falso testemunho
- Importância da decisão do Conselho de Sentença na procedibilidade da ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.344 (2)", "page_number": 344, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 340, § 3º, do CP", "Súmula 387/STF"], "jurisprudence": ["RE 102.791/MG", "Tema repetitivo: Tipicidade do crime de falso testemunho"], "confidence": 0.8, "extracted_at": "2026-05-29T03:35:19.415148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=344", "doc_key": "1e5e5b9a0650ba73a26b21dbc59b33dc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '66c2aa1971c3a60139d1fec8840bf43e8ebda0600c25e8996e3b71787c737480'),
  ('cpiuris2025::eeb1f41869317bcd6c59013f152f370f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Perguntas à Testemunha', '## Perguntas à Testemunha

As partes formulam perguntas diretas à testemunha, com o juiz apenas deferindo ou indeferindo aquelas que não tenham relação com a causa.

### Conceitos
- **Direct Examination**: Pergunta feita pela parte que arrolou a testemunha
- **Cross-Examination**: Pergunta feita pela parte contrária à testemunha arrolada
- **Inquirição Complementar**: Ação do juiz para complementar a inquirição de uma testemunha

### Referências legais
- Art. 214 do Código de Processo Civil
- ...

### Jurisprudência
- HC 83.703
- ...

### Dicas de prova
- Diferenciar entre direct examination e cross-examination
- Entender a importância da inquirição complementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.345 (2)", "page_number": 345, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 214 do Código de Processo Civil", "..."], "jurisprudence": ["HC 83.703", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:35:51.518861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=345", "doc_key": "eeb1f41869317bcd6c59013f152f370f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'db7c73a9fecd35463013691d4bd73b7acc3b2d95b901d97199287abe4f9806ad'),
  ('cpiuris2025::fefa990b4cdd9d28f71ce5ef9bc23669', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Não exigência de autoincriminação e presença do réu em provas', '## Não exigência de autoincriminação e presença do réu em provas

A testemunha não é obrigada a produzir provas contra si mesma, mas tem o direito de se calar se perceber que sua resposta pode autoincriminá-la. Além disso, a presença do réu na sala de audiência pode causar constrangimento à vítima ou testemunha, levando o juiz a optar por inquirição por videoconferência.

### Conceitos
- **Autoincriminação**: Resposta que pode autoincriminar a pessoa
- **Constrangimento à vítima ou testemunha**: Situação em que a presença do réu pode causar humilhação, temor ou sério constrangimento à vítima ou testemunha

### Referências legais
- Art. 217, caput, CPP
- Art. 212, caput, CPP

### Dicas de prova
- Distinção entre autoincriminação e constrangimento à vítima ou testemunha
- Importância da presença do réu na sala de audiência
- Oitiva da vítima ou testemunha por videoconferência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.345 (1)", "page_number": 345, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 217, caput, CPP", "Art. 212, caput, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:35:59.439468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=345", "doc_key": "fefa990b4cdd9d28f71ce5ef9bc23669"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7ec970cece65f874ba6ac7ccdfc67a03668e48d51e03e958654c6ed90dbe6da9'),
  ('cpiuris2025::86839df5d6f09aed5c222f1eb39c5466', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Momento e forma da indicação do rol de testemunhas', '## Momento e forma da indicação do rol de testemunhas

A acusação deve indicar o rol de testemunhas na peça acusatória, enquanto a defesa faz isso na resposta à acusação. A parte que não arrolou testemunha pode perguntá-las diretamente ou por intermédio do juiz presidente.

### Conceitos
- **Preclusão**: Perda do direito de arrolar testemunhas
- **Testemunha referida**: Pode ser inquirida pelo juiz ex officio ou a requerimento das partes em razão de ter sido citada por outra testemunha
- **Testemunha judicial**: Não considerada para efeito de contagem do número máximo de testemunhas admitido em cada procedimento penal

### Referências legais
- Art. 41 do CPP
- Art. 396-A, caput do CPP
- Art. 209, §1º do CPP
- Art. 401, §1º do CPP

### Jurisprudência
- STJ. 5ª Turma. AgRg no RHC 161.330/RS
- STF. 1ª Turma. HC 161658/SP
- STF. 1ª Turma. HC 187035/SP

### Dicas de prova
- Entenda a diferença entre testemunha referida e judicial
- Conheça o momento adequado para indicar o rol de testemunhas
- Não perca o direito de arrolar testemunhas devido à preclusão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.346 (1)", "page_number": 346, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 41 do CPP", "Art. 396-A, caput do CPP", "Art. 209, §1º do CPP", "Art. 401, §1º do CPP"], "jurisprudence": ["STJ. 5ª Turma. AgRg no RHC 161.330/RS", "STF. 1ª Turma. HC 161658/SP", "STF. 1ª Turma. HC 187035/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T03:38:12.588979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=346", "doc_key": "86839df5d6f09aed5c222f1eb39c5466"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c6c5d85b3001eccffea0e1a5481c736be4aa258b9e75e7d8cede43e5fb8b59f5'),
  ('cpiuris2025::3598fa7092152ee968dca9f3f0da711b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Inquirição Ex Officio', '## Inquirição Ex Officio

O juiz pode inquirir alguém independentemente de ter sido arrolado pelas partes, com o objetivo de buscar a verdade real e determinar providências necessárias.

### Conceitos
- **inquirição ex officio**: procedimento em que o juiz inqueria alguém sem necessidade de arrolamento pelas partes
- **poder-dever do magistrado**: habilitação do juiz para buscar a verdade real e determinar providências necessárias
- **juiz como investigador**: função do juiz de investigar e esclarecer dúvidas
- **testemunhal ex officio**: prova obtida mediante inquirição ex officio
- **outras testemunhas**: testemunhas que podem ser ouvidas além das indicadas pelas partes
- **juiz como autoridade**: autoridade do juiz para tomar decisões sobre a condução do processo
- **verdade real**: conceito de verdade que se busca alcançar mediante o procedimento ex officio

### Referências legais
- Art. 209 do CPP

### Jurisprudência
- 22 AgRg no HC 270.814/DF

### Dicas de prova
- Entenda a distinção entre inquirição ex officio e arrolamento pelas partes
- Conheça o poder-dever do magistrado e sua importância no procedimento ex officio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.346 (2)", "page_number": 346, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 209 do CPP"], "jurisprudence": ["22 AgRg no HC 270.814/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:38:27.353148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=346", "doc_key": "3598fa7092152ee968dca9f3f0da711b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cb7f37cb42f109dccf9f56b65ffa6456ccd385f41dbfa28543665edd43ea0b6a'),
  ('cpiuris2025::4ea9b4bd6c2cad7c13a27d62bd24994d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Iniciativa probatória do juiz e classificação das testemunhas', '## Iniciativa probatória do juiz e classificação das testemunhas

A iniciativa probatória do juiz é objeto de debate, com duas correntes doutrinárias: uma que afirma que o art. 3º-A do CPP vedou toda a iniciativa, e outra que permite a determinação de diligências suplementares na fase de investigação.

### Conceitos
- **Iniciativa probatória**: A capacidade do juiz de tomar medidas para provar a existência de um fato
- **Testemunha própria**: A testemunha que é chamada para ser ouvida sobre o fato objeto do litígio
- **Testemunha imprópria**: A testemunha que prestará depoimento sobre fatos que não se referem diretamente ao mérito da ação penal
- **Testemunha numerária**: A testemunha que é computada para efeito de aferição do número máximo de testemunhas legalmente permitido
- **Testemunha extranumerária**: A testemunha que não é computada para efeito de aferição do número máximo de testemunhas legalmente permitido

### Referências legais
- Art. 3º-A do CPP
- Súmula N da STF

### Dicas de prova
- Entenda a distinção entre testemunha própria e testemunha imprópria
- Conheça as diferentes categorias de testemunhas (numerária e extranumerária)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.347 (1)", "page_number": 347, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-A do CPP", "Súmula N da STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:38:40.903387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=347", "doc_key": "4ea9b4bd6c2cad7c13a27d62bd24994d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ccb56c9f9dafacb520630c6b2418791ac8452c39ca774acf973fc8e3151518af')
